export default {"actually-a-skill-issue":{"cat":"F","roles":{"A":["settled","streak:losing"],"B":["veteran"]},"world":[],"ex":[[["A","I have nothing at that range. Not one button."],["B","Your low reaches."],["A","It's minus on block."],["B","You're getting hit for free instead. Pick which problem you want."]],[["B","How many of those did you lose to that same poke?"],["A","That poke is the matchup. That's what the matchup is."],["B","Sure."],["A","You're supposed to argue with me here."]],[["A","I might need a second character just for this matchup."],["B","You just picked the first one up."],["A","And it doesn't work here."],["B","Doesn't work here yet. Not the same complaint."]],[["B","You want the honest version or the version where I agree with you?"],["A","The second one."],["B","Awful matchup. Unwinnable. Nobody's ever taken a round in it."],["A","Fine. Give me the other one."]],[["A","Do you ever lose this matchup?"],["B","All the time. Slower than you, but yeah."],["A","Great. Very helpful."],["B","Stop dashing in from that range and you'll lose it slower too."]],[["B","Set the recording to that jump-in and block it for ten minutes."],["A","It's not the jump-in. Once they're in on me I've got no answer at all."],["B","You've got three. You go for the throw every time and they've stopped falling for it."],["A","It works sometimes."]],[["A","Six in a row against that character. Six."],["B","You eaten anything since you got here?"],["A","Don't do that."],["B","I'm getting fries regardless. That's all I'm telling you."]],[["B","That was closer than you're acting like."],["A","I opened the same way every game and it worked twice. That's not close, that's a bad matchup."],["B","It's a bad opener."],["A","Same result either way."]],[["A","Everybody calls this matchup even. Everybody's wrong."],["B","Who's everybody?"],["A","The people making the charts."],["B","None of them are in here, and you've played one person all night."]],[["A","I'm done. The matchup's broken."],["B","Which part."],["A","The part where I press a button and lose the round."],["B","That button's minus. It was minus before you got mad about it."]],[["A","Feels like I committed to the wrong character for this."],["B","You committed to one that wants to hold ground. You give ground every time they step forward."],["A","Because everything they have outranges me."],["B","Not all of it. And you're moving back before they even press."]],[["A","I'm going to walk around for a minute before I say something about that matchup."],["B","Popcorn machine's dead, if that's the direction you were heading."],["A","I was going to stand by the curtain and be angry."],["B","There's room."]]]},"after-money-match":{"cat":"G","roles":{"A":["lost"],"B":["won"]},"world":[],"ex":[[["A","I've got a twenty and a five, is that alright?"],["B","That's how money works, yeah."],["A","I only ask because last time somebody paid me in ones and I felt like a vending machine."],["B","I'd have taken the ones."]],[["B","You don't have to hand it over right this second. Go get a drink first."],["A","No, take it now. If I sit on it I'll start doing math about whether I actually lost."],["B","You lost."],["A","I know. That's the problem with the math."]],[["A","Count it."],["B","I'm not counting it in front of you."],["A","Count it, because if it's short I'd rather hear it now than get a text about it."]],[["B","Same again next week?"],["A","Not for money. I'll play you all night for free, I'm just not funding it."],["B","Fair."],["A","Ask me again in a week though, I'm bad at remembering this feeling."]],[["A","The low was the whole set. I kept standing up and you kept knowing."],["B","You stand up when you're behind. Every time."],["A","That's useful and I hate that you told me."],["B","You paid for it. Seemed rude not to."]],[["A","Here. Folded, so nobody has to watch."],["B","Half the room watched the set."],["A","Watching the set is fine. Watching the handover is different."]],[["B","You alright? You've been staring at the same corner of the screen."],["A","Trying to work out where the last one went. I had you at low health and then I didn't."],["B","You went for the throw and I'd already jumped."],["A","Right. Okay. That's less mysterious than I was hoping."]],[["A","I don't have cash on me."],["B","Then don't agree to money matches, that's sort of the whole system."],["A","I'll get it out of the machine by the doors, it just charges me three dollars to do it."],["B","So it's a forty-three dollar match. Noted."]],[["B","Take it back."],["A","Absolutely not. Don't do that."],["B","That first game was a fluke and both of us know it."],["A","You still won two. Buy something with it so I stop thinking about it."]],[["B","Popcorn machine's going. I'll spend it on that and we can both pretend it's shared."],["A","I'm not eating popcorn I paid for."],["B","You'll eat some."],["A","I'll eat some."]],[["A","That was the most expensive drop of my life. I had the confirm and I panicked."],["B","I saw your hands stop."],["A","Everyone saw my hands stop."],["B","Lab it. Same bet next month, I'm not going anywhere."]]]},"bad-advice":{"cat":"A","roles":{"A":["lost"],"B":["won"]},"world":[],"ex":[[["A","What am I doing wrong in neutral? Genuinely."],["B","You're not doing anything wrong exactly. It's more like... I know where you're gonna be."],["A","Okay, so how do you know that."],["B","I don't know. I just do. That's not helpful, I get it."]],[["A","Give me one thing. Just one thing to fix."],["B","Your low is slower than you think it is."],["A","Slower how? Like I'm late on it, or the move itself?"],["B","One of those."]],[["A","How were you getting in on me so easy?"],["B","I wasn't thinking about it much, so I'm the wrong person to ask."],["A","You did it like nine times."],["B","Sure, but I couldn't tell you the button. Muscle stuff."]],[["A","Was I whiffing too much or blocking too much? I honestly can't tell which set that was."],["B","Both, kind of. Different rounds."],["A","That's the least useful answer available."],["B","I know. Ask me again when I've had a minute to think about it."]],[["B","You want me to go through it or do you want to just play again."],["A","Go through it. I've got time."],["B","Your pressure's fine. It's after they block that you fall apart. You do a thing, it gets blocked, and then you do another thing."],["A","So what should I do after it's blocked?"],["B","Wait? I don't actually know. I wait."]],[["A","Break down that combo you were getting after the throw."],["B","It's just the two hits and then the ender."],["A","There's a delay in it though. I can hear it."],["B","Maybe. I've never counted. I press it when it looks right."],["A","I'm going to go find someone who counted."]],[["A","How do I deal with that long poke you keep sticking out?"],["B","Be further away, I guess."],["A","I can't hit you from further away."],["B","Yeah, that's the problem with it. That's why I use it."]],[["B","You looked mad at yourself the whole time, which I think was most of it."],["A","That's not a fix, that's a diagnosis."],["B","I never said I was good at this part."],["A","Somebody's got to be. I'll ask around."]]]},"bad-apology":{"cat":"J","roles":{"A":["warned"],"B":["rel:hostile"]},"world":[],"ex":[[["A","They've got me signing in at the desk before I'm allowed to sit down in here. So that's where we are."],["B","That's not a sentence that goes anywhere."],["A","I shouldn't have shouted over your set. That's the part I'll own."],["B","Okay."]],[["B","You don't have to do this."],["A","I sort of do. It's the condition they gave me."],["B","Then it's for them, not me. Go tell them you did it."],["A","I'm telling you as well."]],[["A","About the cabinet. I hit it, an attendant saw, I've been spoken to. Sorry."],["B","You hit it in the middle of my game."],["A","I'm not going to pretend I remember whose game it was."],["B","Then we're done."]],[["B","You've been hovering."],["A","I'll apologize for kicking the chair over if you cop to what you said first."],["B","That isn't how any of this works."],["B","You're stuck. I'm playing."]],[["A","This was supposed to be a Sprite. Machine gave me whatever this actually is."],["B","And it's mine because?"],["A","Because they wrote me up over the popcorn machine thing and your name was in it."],["B","Leave it on the chair."]],[["B","Staff talk to you?"],["A","At length."],["B","And?"],["A","And I'm sorry the whole room had to sit through it. That's the honest version."]],[["A","I'm sorry about the chair, do you have next or not."],["B","You put those in one breath on purpose."],["A","Saves us both time."],["B","I've got next. Sit somewhere else."]],[["A","You going to say anything?"],["B","Projector's crooked again. Look at the corner."],["A","I said I was sorry."],["B","I heard you the first time."]],[["A","I wrote it down, because I say it worse out loud. Here."],["B","You want me to stand here and read your apology in front of you."],["A","Read it later, I don't care."],["B","I'll read it later."]]]},"bad-week-outside":{"cat":"J","roles":{"A":["mood:low","rel:close"],"B":["rel:close"]},"world":[],"ex":[[["A","Don't ask me how the week's going."],["B","Wasn't going to. You want the good stick or the back row?"],["A","Back row."],["B","It's yours. I'll bring the chair over."]],[["B","You're leaving after this, aren't you."],["A","That's the plan. Lose to you, then go home."],["B","You can lose to me and stay. Those are two different things."],["A","I'll see."]],[["A","If I start playing badly, just keep beating me. I don't want the talk where you ask if I'm okay."],["B","I was going to beat you regardless."],["A","Good."]],[["B","Have you eaten anything today?"],["A","Coffee. Around four."],["B","That's not food. There's popcorn or there's the vending machine and I won't defend either of them."],["A","Popcorn."]],[["B","You nearly didn't come in."],["A","Sat in the car a while."],["B","How long's a while?"],["A","Long enough that the spot by the doors opened up."]],[["A","Sorry. That wasn't about you or the throw."],["B","I know. Run it back."],["A","Give me a second."],["B","Take two, I'll get a drink."]],[["B","Do you need money or do you need a ride somewhere?"],["A","Neither. Ask me next week."],["B","Next week I'll ask again."],["A","I know you will."]],[["A","I'm playing better in a bad mood, which is irritating."],["B","You're blocking. Normally you're busy trying to be clever with meter."],["A","Too tired to be clever."],["B","Stay tired, then."]],[["B","Slept?"],["A","Some. On and off. Mostly off."],["B","We'll just play casuals then, I won't count anything."],["A","Count it. I want it to count."]],[["A","I put the pad down hard. Not thrown. But hard."],["B","I saw."],["A","It isn't the game."],["B","I know it isn't the game. Pick it up and sit down, we've got the setup for another twenty minutes."]]]},"before-money-match":{"cat":"G","roles":{"A":[],"B":[]},"world":[],"ex":[[["B","Both stacks are under the popcorn machine with somebody I've never met."],["A","Go get them."],["B","They offered to hold it. It'd be strange to take it back now."],["A","Then that's the person I'm chasing down after."]],[["A","People are sitting down. In rows."],["B","The chairs were already in rows."],["A","Nobody ever sits in them, that's the part I'm noticing."],["B","Sit down yourself and quit counting."]],[["B","First to three, and we're not extending it if it gets close."],["A","Three's fine. I've got work in the morning."],["B","So do I, I just wasn't going to lead with it."]],[["A","My hands are freezing."],["B","Stand behind the vending machine. It puts warm air out the back."],["A","Does that actually do anything?"],["B","No. But you'll feel like you did something about it."]],[["B","I'm locked in, before you ask. Same character all five if it goes that far."],["A","No counterpicks at all?"],["B","If I start switching I'll spend the whole set thinking about switching."],["A","Locked too, then."]],[["A","Somebody's announcing this on the front desk mic."],["B","That mic carries all the way out to skee-ball."],["A","So we're getting kids in here."],["B","Play well then."]],[["B","You good for it either way?"],["A","It's twenties, back pocket, you can count it right now."],["B","I'm not counting your money with thirty people watching."],["A","Then take my word and sit down."]],[["A","I want left side and I'm not discussing it."],["B","Take it. Right's been fine for me all night."],["A","Right's fine for everybody but me."],["B","Then it's settled and you can stop explaining."]],[["B","Warm up if you need it. I'd rather not hear about your hands afterward."],["A","Ten minutes."],["B","Take ten."],["A","You say that now and then you'll be pacing at four."]],[["A","If people start calling out what I'm going for, we stop and restart the game."],["B","Tell them that, not me."],["A","They listen to you."],["B","I'll say it once. After that it's on you to tune it out."]],[["B","You want to start now or wait for the room to thin out?"],["A","Now. If I sit here any longer I'll talk myself into a different character."],["B","Now, then. Somebody grab the chair out of the way."]],[["A","Bathroom first. Two minutes."],["B","Go. Nobody's starting without you."],["A","It's not nerves."],["B","I didn't say anything."]]]},"birthday-party-outside":{"cat":"H","roles":{"A":[],"B":[]},"world":[],"ex":[[["A","They're doing the song again."],["B","Third time. It's a different kid each round, I think it's a shared party."],["A","Do you want to pause?"],["B","No, just don't blame the noise when you lose."]],[["A","You've got frosting on your sleeve."],["B","They handed me a plate at the concession counter. I wasn't in line for cake, I was in line for a drink."],["A","Did you eat it?"],["B","Obviously."]],[["B","Run it back, I can't hear my own inputs."],["A","You don't listen to your inputs."],["B","I listen to the throw. There's a sound. It's gone right now."],["A","Then I'm going for throws until the party ends."]],[["A","That was a scream, right? Out there?"],["B","Prize counter. Someone got the big stuffed thing off the top shelf."],["A","Huh."],["B","Your turn. Still your turn."]],[["B","Half the folding chairs are gone."],["A","They took them for the long table. There were like twenty kids."],["B","So we stand."],["A","You stand anyway. You've never once sat down for a set."]],[["A","I dropped that because a balloon popped."],["B","Sure."],["A","I'm serious, it was right at the confirm."],["B","You drop that one when it's quiet too. I've watched you do it in an empty room."]],[["B","Should we put the projector on? Kids might come look."],["A","It's already on. Nobody's coming through the curtain, they've got skee-ball and a cake."],["B","One of them will. There's always one."]],[["A","Party's making me want pizza."],["B","Concession pizza is a mistake and you know it's a mistake."],["A","I know. Get me one too."]],[["B","You keep looking at the curtain."],["A","My kid's birthday is next month. I'm pricing it out in my head."],["B","Ask at the desk, there's a package thing on the whiteboard."],["A","Yeah. After this set."]],[["A","They're playing music out there now."],["B","It's fine. Better than the machine noise, honestly."],["A","You're going to time your dashes to it."],["B","I already was. Been doing it since the second song."]],[["B","Two of them came in and asked if this was the movie room."],["A","Because of the screen."],["B","I said no. Then I felt bad, so I let them watch one game."],["A","Which one?"],["B","The one I lost. They didn't stay for the next."]]]},"blames-hardware":{"cat":"A","roles":{"A":["lost"],"B":["won"]},"world":[],"ex":[[["A","Down-back doesn't take on this stick. Not always. Enough that I noticed."],["B","Take my side. I'll play out of that one."],["A","No, then I've got nothing to say when I lose again."],["B","You'll find something."]],[["B","You keep looking at the buttons instead of me."],["A","Because the heavy is eating inputs. I press it, nothing happens, then it happens late."],["B","Swap. Genuinely. I don't care which side I sit on."],["A","Fine. If it's still late over there I'm going to be quiet about it."]],[["A","That stick's got a dead zone the size of a dinner plate."],["B","Then come over here and I'll take the plate."],["A","You'd win anyway and then I've lost the excuse too."]],[["B","Want this side? I've been on it all night, it's warm and everything."],["A","It's not the seat, it's the throw button. Sticks about half the time."],["B","Sticks or you're mashing it and hitting the edge?"],["A","Could be either. Let's say sticks."]],[["A","I dropped two conversions off the same button not registering."],["B","Alright. Sides."],["A","You're being very calm about this."],["B","I'm up. Calm's free."]],[["A","Something's wrong with the up-forward on that one. I couldn't get a jump out cleanly."],["B","Move over then, run it back from here."],["A","Later. I want to sit with it a minute."],["B","Sit with it on my side, the chair's better."]],[["B","You can have this station if you want it. Same offer as always."],["A","The buttons over there are mushy. All of them, not one."],["B","They're mushy here too. Different mushy."],["A","Great. I'll take a new mushy."]],[["B","Sides?"],["A","No. It's not the sticks, it's that I kept pressing buttons on your oki and there's nothing there for me."],["B","There genuinely isn't. You have to hold it."],["A","I know. I did say it was the sticks first though."]],[["A","Left one's loose. It rattles when I dash."],["B","It's rattled since I got here. Doesn't stop me hitting the direction."],["A","So swap with me and rattle for a bit."],["B","Happily. Put a coin up first, someone's waiting."]],[["B","You've been flexing your hand between games. Is that the stick or is that your hand?"],["A","The stick's stiff. Wrist's fine."],["B","Take mine, it's been broken in. If the wrist keeps going we stop."],["A","The wrist is fine."]],[["A","Every single low I blocked, I got hit anyway. That's a button not going down."],["B","Or that's me throwing you. You want the other side, you can have it."],["A","Now I don't want it."],["B","That's on the table until someone else sits down."]]]},"both-playing-badly":{"cat":"B","roles":{"A":["rel:familiar"],"B":["rel:familiar"]},"world":[],"ex":[[["A","We should stop. Neither of us is doing anything."],["B","One more. I want to see if it gets worse."],["A","It will."],["B","Then we'll know."]],[["B","I dropped the same confirm three times."],["A","I know, I was standing there waiting for the rest of it. Kept blocking a combo that never showed up."],["B","That's the only reason you won that one."],["A","I'll take it."]],[["A","Are you tired or am I just not making you press anything?"],["B","Both, probably. I've been holding back for no reason all set."],["A","Same. We're basically taking turns standing still."]],[["B","Whoever wins this should feel bad about it."],["A","I already feel bad and I'm losing."],["B","Then we're covered either way."]],[["A","I keep going for the throw at like the worst possible moment."],["B","I'd tech it if I was awake. I'm not doing you any favours."],["A","So it's working."],["B","It's not working. It's just not being punished."]],[["B","That was the ugliest set I've played in a while."],["A","You were the better half of it, if that helps."],["B","It doesn't."],["A","No, I didn't think it would."]],[["B","I've got nothing in neutral today. I just walk forward and hope."],["A","I've been walking forward too. We keep meeting in the middle and panicking."],["B","That's not a plan, that's a traffic accident."],["A","It's been going on all set, so at this point it's a plan."]],[["A","Do you want to go get food and come back to this."],["B","Yeah. I'm not learning anything from it."],["A","Leave the chairs, someone will take them if we don't."],["B","Let them. They'll play better in them than we did."]],[["B","You're mashing."],["A","You're mashing back. That's why it's been so close."],["B","I thought I was reading you. Turns out I was just also pressing."]],[["A","How long have we been on this setup?"],["B","Long enough that it's not warming us up anymore. It's doing the other thing."],["A","Yeah. Everything's a half second late."],["B","Run one more and then I'm sitting down for a bit."]],[["B","Was that a whiff punish or did you just happen to be there?"],["A","Happened to be there. I was pressing that button regardless."],["B","Comforting. I lost the round to a button you were pressing anyway."],["A","Don't whiff into it, then."]]]},"bracket-posted":{"cat":"G","roles":{"A":[],"B":[]},"world":["bracket:up"],"ex":[[["A","Bracket's up. You're on the far side from me, so we don't touch until late."],["B","Late assumes a lot about both of us."],["A","I'm being optimistic. It's a whole new thing for me."]],[["B","Who put me in the top half? I signed up last."],["A","It's random. It's supposed to be random."],["B","Then random hates me specifically."],["A","Random put me against you in the second round, so."]],[["A","Sixteen names. I counted twice because I didn't see mine the first time."],["B","You're spelled wrong. Bottom left."],["A","That's not even close to how it's spelled."],["B","You'll answer to it."]],[["B","There's an empty slot next to your first match."],["A","Bye?"],["B","Somebody didn't fill it in. Could go either way."],["A","I'll warm up like it's a person."]],[["A","You looked at the bracket for a long time without saying anything."],["B","Working out the earliest I can lose and still get food before the top eight."],["A","And?"],["B","Second round. Comfortably."]],[["B","Whole left side is people who beat me last week."],["A","That's four names. You lost to four people?"],["B","Busy week."]],[["A","We're in the same half again."],["B","Third time. I'm starting to think the seeding has opinions."],["A","There's no seeding. Someone wrote names down as they walked in."],["B","Then I'm going to start walking in later."]],[["B","Sign-ups are still open, right? There's room under the last line."],["A","Ten minutes, they said. Get your name on it."],["B","I only came to watch."],["A","You brought your own pad."]],[["A","You're first match on stream. Projector and everything."],["B","Which one's the stream setup, the one on the left?"],["A","The one people are already sitting in front of."],["B","Great. I'll drop everything in front of an audience."]],[["B","Half these names I don't recognize."],["A","Two of them came in off the skee-ball side about an hour ago. Watched a few sets, asked how to enter."],["B","Any good?"],["A","One of them found a whiff punish I'd have missed. So, unclear."]],[["A","You've got the round-one match nobody wants."],["B","I saw. Fine."],["A","That's it? Fine?"],["B","I'd rather get it out of the way than sit around waiting for it."]],[["B","Whose handwriting is that? I can't tell if that's a name or a doodle."],["A","Ask at the desk, they wrote it off the sign-up sheet."],["B","I'm playing them in twenty minutes. Feels like I should know."],["A","You'll find out when they sit down."]]]},"brand-new-character":{"cat":"F","roles":{"A":[],"B":[]},"world":["char:new"],"ex":[[["A","Everyone's on the new one. Both setups, all night."],["B","I gave it two games and went back. Can't get anything out of the low."],["A","It's minus. Way minus. People just aren't punishing it yet."],["B","Give it a week and it'll be nobody's favorite."]],[["B","You've got the new character on both slots."],["A","I'm trying to find out what happens when it fights itself."],["B","And?"],["A","Neither of us knows what we're doing, so, a lot of jumping."]],[["B","How long have you been in training mode?"],["A","Since I got here. The new one's got a launcher I can't confirm off of consistently."],["B","Consistently meaning?"],["A","Meaning about half. Which in a set is zero."]],[["A","Do you know if the new character's dash is any good?"],["B","It's fine. Nothing special. Goes about as far as everyone else's."],["A","Shame. I wanted a reason."],["B","You don't need a reason to pick a character, you just pick it."]],[["A","You beat me with a character you've had for a week."],["B","I beat you with jumping. Character came along for the ride."],["A","Run it back and I'm anti-airing everything."],["B","Then I'll stop jumping and we'll see how much I actually know."]]]},"broken-setup":{"cat":"H","roles":{"A":[],"B":[]},"world":["setup:broken"],"ex":[[["A","That stick's eating my down-back. Not every time. Enough that I noticed."],["B","That's why nobody else is on it."],["A","Nobody told me that."],["B","Nobody tells anybody. You sit down and you find out."]],[["B","You know the sound only comes out of the left speaker on that one."],["A","I figured it out somewhere in the middle and didn't want to stop the set."],["B","Yeah, that's what everyone does."]],[["A","Should one of us go tell the desk about the middle setup?"],["B","Then they cart it off and we're down to one screen for who knows how long."],["A","So we all just keep away from it."],["B","We keep away from it. That's the system."]],[["A","Whoever's on the far setup, your jumps aren't the problem. That stick drops up-forward."],["B","I've been sitting here deciding I got worse."],["A","You might also have gotten worse. But the stick is real."]],[["B","It cut out on us twice."],["A","Three times if you count before you sat down."],["B","Has anybody said anything up front?"],["A","I keep meaning to when I'm walking past and then I'm past."]],[["A","Somebody taped over the start button on that setup and wrote nothing on the tape."],["B","That's mine. I ran out of energy at the tape."],["A","What does it do?"],["B","Pauses on its own. Middle of a round, no warning."]],[["B","You keep sitting at the one everyone else walks past."],["A","The heavy button's half dead so I have to actually commit to pressing it. My confirms are cleaner."],["B","That's a terrible reason."],["A","It's the one I've got."]],[["A","It's fine when it's cold. Forty minutes in, the button starts staying down."],["B","So we're on a clock."],["A","We're on a clock. Somebody should mention it to the desk before then."]],[["A","I lost low block for a second in that last one. Just gone."],["B","Which side were you on?"],["A","Left. Swapped over after and it happened on the right too."],["B","So it's the whole setup, not the sticks. I'm going to the other one."]],[["B","Why's the line this long? There's two setups."],["A","There's one setup and one thing that turns on."],["B","What's wrong with the second one?"],["A","Picture's a beat behind. You feel it the second you try to poke."]],[["A","You're not blaming the machine."],["B","Sit on it for one game, {t}. That's all I'm asking."],["A","One game in and forward gives out on me."],["B","Yeah. I'm still down two, so it doesn't help me much."]]]},"cabinet-glitched":{"cat":"B","roles":{"A":[],"B":[]},"world":["setup:broken"],"ex":[[["A","Screen went black for a second there. Did yours?"],["B","Mine stayed on. I saw you standing still and hit you."],["A","Great. So it's a me problem."],["B","It's a cabinet problem. I'm just not going to stop hitting you about it."]],[["B","Sound cut out halfway through and I couldn't hear anything I was doing."],["A","You play by sound?"],["B","More than I thought, apparently."]],[["A","Hold on. Hold on. My down input just stopped registering."],["B","Stopped, or stopped when you needed it."],["A","Come round and press it yourself."],["B","Yeah, that's dead. Fine. Run that one back."]],[["B","That reset wasn't me. I didn't touch anything."],["A","I know, I watched it go. It does that when somebody leans on the coin door."],["B","Nobody's near the coin door."],["A","Then I don't have a second theory."]],[["A","Something's loose in the stick on the left side. It's got a wobble before it engages."],["B","How much of a wobble."],["A","Enough that I'm getting neutral when I want back."],["B","Take the right side then. I'll live with it, I'm mostly pressing buttons anyway."]],[["B","Did the game just slow down or was that me?"],["A","Everything went syrup for about a round. Then it snapped back."],["B","So the combo I dropped wasn't real."],["A","The drop was real. The reason might not be."]],[["A","You froze up right at the start and then ate everything."],["B","Screen was still loading on my end. I got the last half second of it."],["A","That's not a game then. Clear it."],["B","Clearing it. Don't be nice about the next one though."]],[["B","Do you smell that?"],["A","It's been warm back there since we sat down. I've been trying not to think about it."],["B","We should probably tell somebody at the counter."],["A","After this set."]],[["A","My throw button died mid-round. Just gone."],["B","Is that why you kept walking into me and doing nothing?"],["A","Yes."],["B","I thought it was a bait. I respected it for like four seconds."]],[["B","Stop, stop. The picture's rolling."],["A","Give it a minute, it usually settles."],["B","Usually."],["A","It settled last week. That's what I'm going on."]],[["B","It ate my credit and then didn't start."],["A","Hit it on the side panel, low down. Not hard."],["B","That worked. Why did that work?"],["A","Don't ask me things about this room."]]]},"called-out-ducking":{"cat":"C","roles":{"A":["h2h:losing"],"B":["h2h:dominant"]},"world":[],"ex":[[["B","You looked at the bracket, saw my name, and went to get a slushie."],["A","I did get a slushie."],["B","You got two."],["A","Line was long. Wasn't going back."]],[["A","Twenty minutes. I want to clean up my blocking first."],["B","You said twenty minutes twenty minutes ago."],["A","Then I'm nearly done."]],[["B","Every time I sit down you remember you've got a call to make."],["A","It was a real call."],["B","To who?"],["A","Set it up, I'll take the left side."]],[["A","I'm not playing you tonight."],["B","Okay."],["A","That's it? No argument?"],["B","You'll be here next week."]],[["A","You've played everyone who walked through that curtain except me."],["B","I'm getting to you."],["A","You said that when the popcorn machine was still full."],["B","Sit down, then."]],[["A","Once I know what to do when you knock me down, I'll run a long set."],["B","You'd learn that faster playing me."],["A","I'd learn it cheaper in training mode."],["B","Cheaper, sure."]],[["B","That's twice you've passed the controller off right before my name came up."],["A","Somebody else wanted in."],["B","Nobody wanted in. I asked the whole row."],["A","I'll go after this one."]],[["B","You're ducking me."],["A","Yes."],["B","At least you didn't invent a wrist thing."],["A","Wrist's fine. It's the record."]],[["B","You're eating that very slowly."],["A","I'm enjoying it."],["B","You've been enjoying it since before I got here."],["A","It's a big pretzel."]],[["B","You wrote your name under mine on the board and then scratched it out."],["A","Put it in the wrong spot."],["B","You put it in the right spot and then had a think about it."],["A","I did have a think."]],[["B","Took me a while to find you. You're out by the skee-ball."],["A","Up two hundred tickets."],["B","Great. Set?"],["A","After this run."]],[["A","Why won't you play me? You've had free hands all night."],["B","Last time you lost a set you didn't say a word to anyone for the rest of the night."],["A","That wasn't about the set."],["B","Left side or right."]]]},"cannot-settle":{"cat":"E","roles":{"A":["exploring"],"B":["settled"]},"world":[],"ex":[[["A","I played four different characters tonight and lost with all of them, which at least is consistent."],["B","You lost the same way with all of them too. Walking straight in."],["A","So it's not the character."],["B","It's never been the character."]],[["B","You're on someone new again."],["A","The buttons feel better. I don't know how else to say it."],["B","That's the only reason I ever picked mine. People act like there's more to it."]],[["A","How long did it take you to know yours was the one?"],["B","I stopped asking the question. That was more or less it."],["A","That's not an answer."],["B","No."]],[["B","Whatever you were doing with that low poke, keep it. That was actually good spacing."],["A","I probably can't. I'm not sure I'm playing them again."],["B","You had one thing working and you're leaving."],["A","There's like nine other ones I haven't tried."]],[["A","Does it get boring? Same character every set, every week."],["B","Sometimes. Then I find out a button's plus and I'm fine for another month."],["A","That's a low bar for fine."],["B","I never claimed otherwise."]],[["B","You spent that whole set figuring out what your buttons do."],["A","I did learn what one of them does."],["B","You could learn that in the lab and not give me free games."],["A","I'm aware. I don't want to be alone in there."]],[["A","Trying somebody with a command throw tonight. Feels wrong in my hands."],["B","You'll drop it about thirty times before it stops feeling wrong."],["A","And then?"],["B","Then you'll drop it less. That's the whole arc."]],[["B","Who are we playing this time."],["A","Haven't picked. I'll know when the screen's up."],["B","Fine. I'm not adjusting either way."]],[["A","I keep waiting to feel something. Everyone talks about it clicking."],["B","Mine didn't click. I got stuck on one for a couple weeks because I was too lazy to move and then I was good at it."],["A","That's bleak."],["B","It worked, though."]],[["A","You've never once thought about switching?"],["B","I think about it every time I lose to something I have no answer for. Then I go back to the same one."],["A","So you do think about it."],["B","Thinking about it is free."]]]},"choked-on-stream":{"cat":"G","roles":{"A":["lost","mood:low"],"B":["rel:familiar"]},"world":["tournament:today"],"ex":[[["A","Everyone's going to have seen that."],["B","Yeah. It's a projector, that's sort of the whole idea."],["A","I had it. I had the round."],["B","You had the round. Then you pressed a button. Both things are true."]],[["B","You want water or you want to be left alone."],["A","Water."],["B","Vending machine ate my dollar earlier so bring exact change or don't bother."],["A","Then I want to be left alone."]],[["B","Sit down, you've got a while before your next one."],["A","I don't want to sit in here."],["B","Go stand by skee-ball then. Nobody out there knows what you did."]],[["A","Was the stream up the whole time or did it cut."],["B","It was up."],["A","Okay."],["B","Chair's still warm, you're not banned from the building."]],[["B","You went for the throw at the end there."],["A","I know what I went for."],["B","I'm saying it was the right call. It got teched. Those are separate."],["A","Feels like one thing from where I was sitting."]],[["A","My hands stopped working. Like actually stopped."],["B","Happens. Mine did in my first set today, nobody was watching so it doesn't count."],["A","Convenient."],["B","I've made peace with it."]],[["B","How long are we doing this for."],["A","Doing what."],["B","Staring at the bracket like it's going to change."],["A","Give me another minute."]],[["A","Somebody laughed. I heard it from the seat."],["B","That was the popcorn machine. It does a thing when it's empty."],["A","No, it was a person."],["B","Probably. There were forty of them."]],[["B","You're minus for the rest of the day, huh."],["A","Don't."],["B","Sorry. That was cheap."],["A","It was, a bit."]],[["A","I've never been that nervous in neutral. I couldn't hold ground at all."],["B","You were walking back the whole set. I noticed from over here."],["A","Great."],["B","You've got another one coming. Walk forward in that one and it's over with."]]]},"compared-to-elsewhere":{"cat":"I","roles":{"A":["newcomer"],"B":["veteran"]},"world":[],"ex":[[["A","Last place I played was the back of a bar. Screen was mounted up by the ceiling, so you played looking up at it."],["B","How'd that go."],["A","Neck ached by the third set. Everybody complained and nobody ever moved the screen."],["B","Sounds like a room I've been in."]],[["B","You keep leaning forward like the chair owes you something."],["A","Where I played before we had couches. Low ones. I'm still adjusting."],["B","Folding chairs keep you honest. Don't sit in the one on the end, though, it walks."],["A","Found that out already."]],[["A","How long's the wait for a setup, usually?"],["B","Couple of sets. It moves."],["A","Two hours at my old spot. One TV, twelve people, and somebody who never got off it."],["B","We've got a few of those. They just don't sit on the screen all night."]],[["B","You're dropping stuff you obviously know how to do."],["A","Everything here comes out faster than I'm used to. I'm early on all of it."],["B","Old TV?"],["A","Huge one. Somebody's living room set from ten years ago, sat on a milk crate."]],[["A","This is the first place I've played that isn't somebody's house."],["B","Better or worse?"],["A","You can leave. At a house you lose and then you're standing in a kitchen for forty minutes being polite."],["B","Yeah. Here you just walk out."]],[["A","Was there somewhere before this? People keep mentioning a back room."],["B","Game store across town. Two setups behind the card tables."],["A","What happened to it?"],["B","Rent. Good half the people you see tonight came off that."]],[["A","Forty minutes each way. That's the part I haven't decided about yet."],["B","Was an hour for me, back when I lived out past the highway. You stop counting it."],["A","Did you actually stop counting?"],["B","No."]],[["B","You were the best one wherever you came from."],["A","How can you tell?"],["B","You look around after you lose like there's supposed to be someone standing there to explain it to you."],["A","There was somebody for that. Different city now."]],[["A","Had to walk past a kid trading in tickets for a stuffed shark to get back here."],["B","Same shark most weeks. There's a guy who's very good at the crane."],["A","Old place was above a laundromat. Smelled like dryer sheets, no sharks."],["B","I'd take the dryer sheets over the popcorn machine, honestly."]],[["B","You brought your own drink."],["A","Habit. Old spot had a vending machine with one row stocked."],["B","Which row?"],["A","Peanut butter crackers. That was the entire food situation."]]]},"costly-decision":{"cat":"I","roles":{"A":["veteran"],"B":["veteran"]},"world":[],"ex":[[["B","Desk gave me my entry back. I didn't even ask."],["A","Whole bracket got it back. Both setups died so they called it off."],["B","So that's every entry in the building refunded, and the pot still went out to the top three."],["A","I tried to leave mine on the counter. Got handed it twice."]],[["A","Those aren't the old TVs."],["B","Monitors. The good kind. Each one's worth about four of whatever was there before."],["A","Times how many setups?"],["B","Don't."]],[["A","It's cold in here."],["B","Vent got fixed. New unit, not a patch job."],["A","In the one room that doesn't sell food."],["B","I complained about that thing for two summers and now I want my hoodie back."]],[["B","The long tables cleared out early."],["A","They got asked to leave. Somebody had a bottle out on the pinball."],["B","That's a big tab standing up and walking."],["A","From where I was it didn't sound like much of a conversation. Two sentences and coats on."]],[["B","Entry's still five on the whiteboard."],["A","Concession went up. Tokens went up. The parking out back went up, somehow."],["B","I'd pay eight and so would you."],["A","Keep that between us."]],[["A","There's a cooler next to the popcorn machine and the sodas in it are free."],["B","For now."],["A","I took two."],["B","Everybody takes two. That's a case gone before anyone's played a set."]],[["A","New chairs."],["B","Padded. Every row, not just the front."],["A","Nobody asked for chairs."],["B","I did. Ages ago. Figured it went in one ear."]],[["A","Sticks on the second setup are new. And not the cheap ones."],["B","There's a box of spares behind the desk now too. Buttons, gates, all of it."],["A","Meanwhile the projector bulb's been going orange for a month."],["B","One thing at a time."]],[["B","Pot's bigger than what we all put in."],["A","Difference came out of the register. I was standing right there when it got counted."],["B","That's not something that happens twice."],["A","I'd stop counting on it, yeah."]]]},"dead-even":{"cat":"C","roles":{"A":["h2h:even"],"B":["h2h:even"]},"world":[],"ex":[[["A","You're up one on me."],["B","No. We're level. You won two off me the night the projector bulb went."],["A","That still counts?"],["B","It counts. I hated it, but it counts."]],[["B","Whatever happens tonight, one of us goes home ahead for the first time in a while."],["A","Don't say it like that. I'll start pressing buttons early."],["B","You already do that."],["A","Right, but now I'll know about it."]],[["A","I keep a note on my phone."],["B","So do I. Mine says thirty-one each."],["A","Mine says the same. That's almost worse."]],[["B","Set?"],["A","Not with everyone standing behind us. Feels like a thing."],["B","It is a thing. That's why they're standing there."]],[["A","We could just stop. Leave it even, never play again."],["B","You'd last a week."],["A","I'd last less than that. I'm already picking a side of the cabinet."]],[["B","Anything you want to tell me before we start."],["A","I labbed the throw punish. The one where you land in front."],["B","Good. I stopped landing in front."]],[["A","Every time we get to even, one of us takes a set and then loses the next week. It's a loop."],["B","Then break it. Take two weeks in a row."],["A","I've never taken two weeks in a row against anyone."],["B","Neither have I. Sit down."]],[["B","You've got that look you get when you've changed something."],["A","I changed nothing."],["B","You changed your button layout. Throw's on the shoulder now."],["A","Okay, one thing."]],[["A","Do casuals count toward it?"],["B","We agreed no."],["A","We agreed no when you were down four."],["B","And I've been honest about it ever since."]],[["B","Someone asked me who's better between us."],["A","What did you say."],["B","I gave them the number and let them work it out."]],[["A","You beat me in neutral all last week and it still ended level."],["B","Because you took every round where I had meter and panicked with it."],["A","I'll take those rounds. They go in the same column."]],[["B","Whoever loses tonight has to hear about it until we play again."],["A","That's just true, you don't have to make it a rule."],["B","I want it stated out loud. Front of mind."],["A","Fine. Stated. Pick your side."]]]},"dead-night":{"cat":"H","roles":{"A":[],"B":[]},"world":["arcade:dead"],"ex":[[["A","Third setup's free if you want your own station."],["B","I'd rather sit next to you and lose. It's less weird."],["A","Suit yourself. First to three?"],["B","First to whenever somebody else walks in."]],[["B","Did something happen tonight? Game somewhere, a wedding, anything?"],["A","Not that anyone told me."],["B","So they all just individually decided."],["A","Guess so."]],[["A","You can hear the skee-ball from in here when it's like this."],["B","You can hear it always. You just stop noticing when there's people."],["A","That's worse."]],[["B","No queue means we can actually run a long set for once. Ten games, no rotation."],["A","I'll be done at six."],["B","You say that every time and then you want one more."],["A","Yeah, but I mean it earlier tonight."]],[["A","Popcorn machine's been on all night for the three of us."],["B","Take some. It's just going to sit there."],["A","It tastes like nobody's been eating it."],["B","That's the taste, yeah."]],[["B","I keep looking at the curtain."],["A","Me too. Every time it moves it's someone going to the bathroom."],["B","Well, put your controller down and play me, then."]],[["A","Empty room's actually good for me. I stop rushing."],["B","You've dropped two confirms already."],["A","Different problem. That's my hands, not my head."],["B","Both of them showed up tonight and neither one of them brought friends."]],[["B","Nights like this used to make me want to leave early."],["A","And now?"],["B","Now I just play worse and stay anyway."]],[["A","You're allowed to say if you'd rather go home."],["B","I drove out here. I'm getting my money's worth out of the drive."],["A","That's not really a yes."],["B","Put in a coin."]],[["B","Chairs are all still in rows from the last event. Nobody's moved a single one."],["A","I sat in the second row earlier like it was a show."],["B","Was it?"],["A","You were in training mode for forty minutes, so no."]],[["A","I've learned more about your spacing in the last hour than in a month of first-to-twos."],["B","Same. I know exactly which poke you're scared of now."],["A","I'd rather you didn't."],["B","Should've hoped for a busier night."]],[["B","Front desk asked me if we were still using the room."],["A","What'd you say?"],["B","That there were more of us coming. Which I don't know."],["A","Keep saying it. It's worked so far."]]]},"defending-lowtier":{"cat":"E","roles":{"A":["main:lowtier"],"B":[]},"world":[],"ex":[[["B","You know that thing you keep doing where the second hit comes out early? That's not supposed to happen."],["A","It's been in the game since launch. Nobody patched it because nobody plays them."],["B","So it IS a bug."],["A","It's a bug that's older than my account. At some point that's just the move."]],[["A","Blocking low doesn't work there. It's a real overhead, it just doesn't look like one."],["B","The animation is the same. I watched it four times."],["A","The animation is lazy. The hitbox isn't."],["B","Great. Love that."]],[["B","Whatever that was, I'm not learning it. You'll drop the character in a month anyway."],["A","People have been saying that since I picked them up."],["B","And?"],["A","And I'm still here and you still don't know what's plus."]],[["A","You keep calling it broken. It's the only thing in the whole kit that isn't minus."],["B","Fine. It's the only good move and it happens to look like a glitch."],["A","Yes. Correct. That's the pitch."],["B","Not the pitch I'd have gone with."]],[["B","Someone told me that character got left half-finished."],["A","They did. I've made peace with it."],["B","That's not peace, that's you doing the same two setups until I guess wrong."],["A","With half a character, yeah. Two is what I've got."]],[["A","Ask me how many buttons on this thing are actually safe."],["B","I'm not going to enjoy the answer."],["A","One. And it's slow. So when I get a knockdown I'm going to squeeze it for everything, and you can call that a bug if you want."]],[["B","Reversal came out at like frame one. That's got to be unintentional."],["A","It's frame three and it loses to throws, which is what you should be doing."],["B","So I throw and it's dead."],["A","Every time. Please. I'd love to see somebody actually do it."]],[["A","You've been mashing after the knockdown all set because you think something's wrong with my oki."],["B","Something is wrong with your oki."],["A","There's nothing wrong with it. It's just bad and I'm hiding it well."]],[["B","Nobody picks that character. Not at any level. That should tell you something."],["A","It tells me you've never blocked the low."],["B","I blocked plenty of lows."],["A","Not that one."]],[["B","You spent that whole meter on one hit."],["A","That's what the meter's for on this character. There's no big cash-in. One hit is the ceiling."],["B","That's miserable."],["A","It's fine. I like it here."]],[["A","Say it's broken again, I'll go pull up the frame data."],["B","I don't need the frame data, I need to stop getting hit by it."],["A","Those are the same project."],["B","Run it back, then. I'll figure it out on your time."]]]},"deflect-to-food":{"cat":"A","roles":{"A":["lost"],"B":["won"]},"world":[],"ex":[[["A","Did they ever fix the pretzel warmer or is it still cheese sauce and hope."],["B","You want to talk about that last one at all?"],["A","I want a pretzel."],["B","Cheese is out. Has been since this afternoon."]],[["A","It is freezing in here."],["B","It's the same as it always is."],["A","Then it's always freezing and nobody's said anything."],["B","Run it back cold, then."]],[["A","How long has the popcorn machine been running? Because it smells like the bottom of it in here."],["B","It runs all day. That's the machine."],["A","Someone should scrape it out."],["B","You going to do that now, or do I get the seat back."]],[["B","Good set. You around next week?"],["A","There's a kid out on the floor who beat me at skee-ball twice today."],["B","At skee-ball."],["A","Twice."]],[["B","Good games."],["A","Do you think the nacho cheese and the pretzel cheese come out of the same bag."],["B","Yes."],["A","That's what I thought too, and now I can't order either one."]],[["A","I'm getting a drink. You want a drink."],["B","I'm alright."],["A","I'm getting you a drink."],["B","Then get me a drink."]],[["A","Who put these chairs in a curve? They're supposed to be in rows."],["B","They've been in a curve all night. You sat in one of them."],["A","And it's been bothering me all night."],["B","Move them. I'm not going anywhere."]],[["A","The light over that side flickers. It's been doing it for weeks."],["B","You sat there for one game."],["A","One's enough to notice."],["B","Take the other side and we'll see."]],[["B","Chips for dinner again."],["A","There's four chips in here and two dollars of air."],["B","Every bag out of that machine is like that."],["A","This one's worse and I'd like that on the record."]],[["A","This soda's mostly syrup. Taste it."],["B","I'm not tasting your drink. Mine came out fine."],["A","Yours came out fine because you got to the machine first."],["B","Sure. Go get another cup."]]]},"discussed-in-absence":{"cat":"K","roles":{"A":["veteran"],"B":["veteran"]},"world":["arcade:established"],"ex":[[["A","Did anyone ever hear back from {t}?"],["B","Texted them in the spring. Got a thumbs up."],["A","That's not hearing back."],["B","It's not nothing either."]],[["B","Their old setup's still the one with the loose bracket. Nobody fixed it because everyone knew to sit on the left."],["A","New people don't know that."],["B","New people find out."]],[["A","Somebody should tell them we finally got the second projector bulb."],["B","You think that's what's keeping them away? A bulb?"],["A","No. But it's something to say."],["B","Then say it. They still read messages, they just don't answer them."]],[["B","I keep expecting them to come through the curtain about twenty minutes late."],["A","I did that too for a while. Stopped a couple months ago."],["B","How'd you stop?"],["A","Started sitting where I can't see the curtain."]],[["A","Nobody's beaten their tournament count."],["B","Because nobody else came every single week for that long."],["A","I came every week."],["B","You came every week and left early. That's not the same record."]],[["B","Kid asked me today who taught me to block low against the dive."],["A","What'd you say?"],["B","Said someone who used to play here. Then I had to explain the whole thing myself anyway."]],[["A","Their name's still on the bracket sheet from the last one they entered. Nobody wiped that board."],["B","I've noticed. I'm not going to be the one to do it."],["A","Same."]],[["B","You were the one who played them the most. You must miss the sets."],["A","I miss losing the first two and figuring it out. Nobody here makes me do that anymore."],["B","I could try."],["A","You could, but you'd tell me what you were doing halfway through. You always do."]],[["A","Heard they had a kid."],["B","That was two years ago. It's the job now, apparently. Different hours."],["A","Huh. I thought it was the kid."],["B","It's probably both. It's usually both."]],[["B","Anyone else play that low-tier grappler since they quit?"],["A","Two people tried. Both went back to what they knew inside a month."],["B","So the matchup's just gone."],["A","Gone. I forgot the throw range already."]],[["A","I ran into them at the grocery store."],["B","And?"],["A","We talked about parking for four minutes and then they said they should get going."],["B","Did you say anything about here?"],["A","No."]],[["B","We should get them out for the anniversary thing."],["A","They'd say yes and then not come."],["B","Maybe. Still asking."]]]},"do-they-make-money":{"cat":"I","roles":{"A":["veteran"],"B":["veteran"]},"world":[],"ex":[[["B","They replaced the popcorn machine. That's a real machine, those cost money."],["A","Or somebody's cousin had one in a garage."],["B","You think everything here came out of a garage."],["A","Show me one thing that didn't."]],[["A","Concession stopped stocking the good drink. Everything else is still there, just not that one."],["B","That's not money trouble, that's whoever does the ordering."],["A","That's what money trouble looks like from the outside, though."],["B","Sure. Or one person forgot."]],[["A","How much do you think the electric bill is on all of it. Not just our room, all of it."],["B","Don't do that. I did that once and I couldn't enjoy the lights."],["A","I'm asking as a curious person."],["B","You're asking like someone who wants to feel bad about a projector."]],[["B","Birthday party out there. Two tables pushed together, maybe fifteen kids."],["A","That's the business. That's the whole business, and we're the closet they let the adults sit in."],["B","I don't mind being the closet."]],[["B","Rent on a building this size can't be small."],["A","They own it. Somebody told me that once at the counter, so, grain of salt."],["B","That would explain a lot. Explains the carpet."]],[["A","If this place folded, where do we even go."],["B","Somebody's basement, and then that gets weird in about two months."],["A","It always does."],["B","So let's hope the nine-year-olds keep spending."]],[["B","Ticket counter had a line out past the tables. Actual line."],["A","Those tickets don't make them anything. That's them paying out."],["B","The line's the part that makes them money. The kid spent forty bucks to get the tickets."],["A","Huh. Yeah."]],[["A","They keep the setups in here for free, and we buy, what, two drinks between all of us."],["B","I bought a pretzel last week."],["A","That's the healthiest this room's been financially."],["B","It wasn't a good pretzel."]],[["B","Half the pinball row has been dark since whenever. Nobody's fixing those."],["A","Parts are hard. That's not a money thing, that's a nobody-makes-them-anymore thing."],["B","Someone told you that or you decided it."],["A","Bit of both."]]]},"dropping-my-main":{"cat":"E","roles":{"A":["settled","streak:losing"],"B":[]},"world":[],"ex":[[["A","I'm done. Picking someone else next week."],["B","You said that about two weeks ago and then locked in like nothing happened."],["A","This time I already deleted the button config."],["B","That takes four seconds to rebuild and you know where every input goes."]],[["B","You've been sitting there a while."],["A","Trying to decide if I hate the character or if I hate losing with the character."],["B","Those aren't the same problem."],["A","No, but they've got the same fix."]],[["A","Going to try somebody with a real reversal. I'm tired of guessing on wakeup every single time."],["B","You'll still guess. You'll just have a button for it."],["A","Then I'll guess with a button."]],[["A","Last one. Then I'm switching."],["B","You want me to play different so it's a nice send-off, or?"],["A","God, no."],["B","Fine. Same as always then."]],[["B","Heard you're dropping the character."],["A","Word travels fast in a room with nine people in it."],["B","You told me while we were in line for popcorn."],["A","Then it wasn't much of a secret, was it."]],[["A","I've put more hours into this character than anything else I do and I'm still losing to people who picked theirs at random."],["B","So switch."],["A","That's the plan. Feels stupid saying it out loud."],["B","It'll feel stupid the other way in a month. Pick either stupid."]],[["B","What are we labbing?"],["A","Nothing. I'm shopping. Going down the roster and seeing who has a fast low."],["B","You're allowed to just say you're switching."],["A","I'm switching."]],[["A","Every time I try to get in I'm minus and eating something. That's not a me problem anymore."],["B","It's a little bit a you problem."],["A","Sure. But I'd rather have the you problem with better buttons."]],[["A","I'm dropping them."],["B","Okay."],["A","You're not going to argue?"],["B","You've lost seven in a row. What am I arguing for."]],[["B","You keep saying you're switching and then you keep queueing up with the same one."],["A","Muscle memory. My hands haven't got the message."],["B","Send it again."]],[["A","Who should I go to? Honest answer."],["B","Someone whose neutral doesn't need three reads a round. You hate that part and it shows."],["A","So basically anybody with a long poke."],["B","Basically. Try two or three before you commit, don't do what you did last time."]]]},"evo-is-close":{"cat":"G","roles":{"A":["veteran"],"B":[]},"world":["evo:soon"],"ex":[[["A","You booked it, or you're still 'looking at flights'?"],["B","Booked. Red eye, middle seat, don't care."],["A","So you're actually going."],["B","Guess so."]],[["B","Pools start at eight in the morning out there."],["A","That's what, five here?"],["B","Six. I've been setting the alarm for it all week. Waking up furious and playing like garbage."],["A","Play bad now, play bad there. At least it matches."]],[["A","You need the entry covered?"],["B","Entry's fine. It's the room that's stupid."],["A","How many of you in it?"],["B","Four beds, six people. Somebody's on the floor and I already know which one of us that is."]],[["B","You want anything from out there?"],["A","Just text me your pool when it posts."],["B","It goes on the website. You can look at it same as me."],["A","I'd rather you told me."]],[["A","People out there will block low on wakeup. Nobody in here does that."],["B","Everybody in here does that."],["A","Not twice in a row, and you've been getting away with the second one for a month."]],[["A","Are you flying with the stick or checking it?"],["B","Backpack. Wrapped in a towel."],["A","They'll open it."],["B","They always open it. I just stand there and watch them do it."]],[["B","I keep running the first match in my head and nothing past it."],["A","The first one's the only one you can run."],["B","That's not helping."],["A","Wasn't the goal."]],[["A","We'll throw the stream on the projector that weekend. Popcorn machine and everything."],["B","So you can all watch me go out of pools in high definition."],["A","That's happening whether you like it or not."],["B","Fine."]],[["B","I need real sets before I go. First to five, no talking in between."],["A","I can do first to five. I can't do the no talking."],["B","Then talk less."],["A","I'll try. Pick a side."]],[["A","Did you register already or are you doing it at the venue?"],["B","Registered ages ago. Paid the entry before I had a flight, which is backwards."],["A","That's how everyone does it."]],[["B","The setups out there are supposed to be worse than these."],["A","Different worse. You'll drop stuff you never drop here."],["B","Should I be practising dropping it, then."],["A","Practise confirming later than feels right. Same result, less panic."]]]},"finally-committed":{"cat":"E","roles":{"A":["settled"],"B":["veteran"]},"world":["arcade:established"],"ex":[[["A","I'm sticking with the one I played last night. That's it. Done deciding."],["B","Okay."],["A","You don't sound convinced."],["B","I'm convinced. I'm just not writing it down yet."]],[["B","You went back to the same character three sets in a row. That's new."],["A","I deleted everything else off my notes app. Felt worse than I expected."],["B","That part passes. The knowing what your buttons do part takes longer."]],[["A","Ask me who I play."],["B","No."],["A","Come on."],["B","You've had me ask four times. I'll ask again in a month and see if the answer holds."]],[["A","I'm done switching. I want to actually get good at one thing before I'm too old to care."],["B","Then stop labbing the throw loop and go play people. You've got the combo, you don't have the neutral."],["A","The combo's the fun part."],["B","Yeah. That's the problem with you."]],[["B","You looked mad in that set and you didn't switch."],["A","I thought about it. Around the second game I was reaching for the select screen in my head."],["B","And?"],["A","And I lost the same way twice instead. Feels like progress."]],[["A","Every matchup I hate, I have to actually learn now. Can't just pick around it."],["B","That's the whole trade."],["A","Nobody said that part out loud when I was asking for advice."],["B","We did. You were busy trying the third one."]],[["B","Something's different. You're not checking the other side of the roster between games."],["A","Nothing over there for me."],["B","Huh."],["A","Don't make it a thing. Just run it back."]],[["A","How long did it take you to stop second-guessing who you picked?"],["B","I never picked. I just kept losing with the same one until it counted as a decision."],["A","That's bleaker than what I wanted."],["B","It works, though."]],[["B","Locked in?"],["A","Locked in."],["B","Good. Now your bad habits are permanent and we can start fixing them."]],[["B","You blocked low there. Old you would've pressed a button and shrugged about it."],["A","Old me had four characters and no reason to remember what's minus."],["B","So what's minus?"],["A","The sweep. Which I've been losing to for months, apparently."]],[["A","I told the guys at the counter I finally settled on somebody and one of them said good, because they were tired of hearing about it."],["B","They're not wrong."],["A","You could have told me that yourself."],["B","I figured you'd land somewhere eventually. Put your name up, there's four ahead of you."]]]},"finally-stocked":{"cat":"H","roles":{"A":["fav-food-stocked"],"B":[]},"world":["concession:stocked"],"ex":[[["A","They've got the big pretzels again."],["B","Since when?"],["A","Sometime today. I bought two, because I don't trust them to have any tomorrow."],["B","Two is a lot of pretzel for one person."]],[["B","You're eating in the middle of a set. That's new."],["A","Nachos are back on. Not letting the window close on me."],["B","Cheese on the buttons and everyone suffers."],["A","There's a napkin. I'll get to it."]],[["A","Cherry slush is up on the board."],["B","The board's been wrong about everything else."],["A","I'm holding one. It's cold and it's real."],["B","Get me one before they change their minds, then."]],[["B","What is that smell."],["A","Mozzarella sticks. They restocked today."],["B","You got a whole basket."],["A","They came with a cup of marinara and I wasn't going to argue."]],[["A","I ordered the tots and they just handed them over. No apology, no 'we're out of those'."],["B","Strange when it works."],["A","Asked if it was a permanent thing and the person behind the counter said they only work Thursdays."],["B","So, no."]],[["A","Hot dogs are back. Got you one."],["B","I didn't ask for a hot dog."],["A","You'll eat it."],["B","I will, yeah."]],[["A","Third time I've asked about it and today the answer was yes."],["B","Asked about what?"],["A","Chili cheese. They finally ordered a case."],["B","You're going to feel awful in an hour."],["A","Probably."]],[["B","You've been holding that cup for a while without drinking any of it."],["A","It's the blue one. They never have the blue one."],["B","So drink it."],["A","Working up to it."]],[["A","Popcorn machine's got actual popcorn in it."],["B","It's been a lamp for as long as I've noticed it."],["A","Filled a bag. Warm, salted, the whole deal."],["B","Leave some on the chair, I'm out of this one shortly."]],[["B","You look pleased with yourself."],["A","Jalapeño poppers came in."],["B","Congratulations."],["A","You could have one."],["B","I could not."]],[["A","Whiteboard out front says the tenders are back. I don't believe the whiteboard."],["B","That whiteboard still has a deal on it from a month ago."],["A","Went and looked anyway. There's a full tray sitting in the warmer."],["B","Bring them back through the curtain before they go cold."]]]},"first-bracket-win":{"cat":"G","roles":{"A":["won"],"B":["rel:familiar"]},"world":["tournament:today"],"ex":[[["A","Do I need to sign something? For the money."],["B","You take it off the desk and then you help stack the chairs like everybody else."],["A","That's the whole ceremony."],["B","That's it."]],[["B","Hands still going?"],["A","They started up in the middle of that last one. I couldn't feel the buttons, I was guessing where they were."],["B","You guessed fine."]],[["A","I want to run it back right now."],["B","There's nothing left to run. You won the bracket. Go eat."],["A","After."],["B","You said after at eleven this morning."]],[["B","You quit going for the throw on their wakeup about halfway through."],["A","Because it stopped working and I panicked."],["B","Panicking was the right call. Don't tell anyone that's what it was."]],[["B","Get up to the desk before the line for the prize counter builds."],["A","Wait, they pay it out of the front register?"],["B","They count it out next to some kid trading tickets for a stuffed shark, yeah."],["A","I'll go now."]],[["A","So now people go lab me, or what."],["B","One person will. You won't know which one."],["A","Cool. Great."]],[["A","Let me get you something out of the machine at least."],["B","You won like forty dollars."],["A","And I'm spending two of it on you."],["B","Get the water. The orange one's been in there since before I started coming."]],[["A","Was that up on the screen? The whole set?"],["B","Everyone watched you drop the confirm and win anyway."],["A","I dropped it twice."],["B","We know."]],[["B","You didn't switch once all day."],["A","Never had a reason to."],["B","Everybody switches when a set goes bad."],["A","None of them went bad."]],[["A","Feels smaller than I thought it would."],["B","Wait till you're in the car."],["A","That's what three people have told me now."]],[["B","You know you came out of the ugly half of that bracket."],["A","Did I?"],["B","All the hard ones were on your side. I got the soft half and lost in it."],["A","Am I supposed to feel bad about that?"]]]},"first-ever-win":{"cat":"A","roles":{"A":["won","h2h:losing"],"B":["lost","h2h:dominant"]},"world":["arcade:established"],"ex":[[["A","I want to say something and I don't know what it is."],["B","You don't have to say anything. You won, that's the whole thing."],["A","Feels like there should be more to it."],["B","There isn't. Put your quarter up again."]],[["B","What changed? Because something did."],["A","I stopped going for the throw every time you blocked low."],["B","That's it? That's all of it?"],["A","That's all I had."]],[["A","You want to run it back?"],["B","Give me a minute. I'm going to go stand near the popcorn machine."],["A","Take two."],["B","I'll be back before you get bored."]],[["B","Congratulations. Genuinely."],["A","You're being weird about it."],["B","I'm being nice about it. Those look similar from where you're sitting."]],[["A","How long have I been trying that?"],["B","Long enough that I'd stopped watching for it."],["A","So I got you because you got comfortable."],["B","You got me because you kept coming back. Don't hand me the credit for it."]],[["B","My hands were cold that whole set."],["A","Sure."],["B","I'm not saying it's why."],["A","You're saying it near the reason it happened, though."]],[["A","I'm not going to be normal for the rest of the night."],["B","Nobody expects you to be."],["A","I might tell people."],["B","Tell them. Better they hear it from you than from me pretending it didn't happen."]],[["B","That last one you didn't drop a single confirm."],["A","I dropped one. Early. You were still up at that point so it didn't matter."],["B","Didn't notice."],["A","That's the first time I've had something you didn't notice."]],[["A","Say the score out loud for me."],["B","No."],["A","One time."],["B","Ask me again in an hour when I've made peace with it."]],[["B","You were shaking on that last round. I could see the stick moving."],["A","I was pretty sure I was going to press the wrong button and hand it back to you."],["B","So was I. That's why I went for the big punish instead of playing it safe."],["A","Yeah, I saw that coming, weirdly."]]]},"first-meeting":{"cat":"D","roles":{"A":["rel:stranger"],"B":["rel:stranger"]},"world":[],"ex":[[["A","You've got next after this, right? I put my name under yours."],["B","Yeah, that's me. I've been standing here so long I forgot I signed up."],["A","Same. I'll wave you over."]],[["B","Do you want the stick or the pad side? I don't have a preference."],["A","Pad side, if that's real."],["B","It's real. The stick one's fine, I just play worse on it and I'd rather find that out later."]],[["A","Is there a rule about the popcorn machine or can anybody just take some."],["B","Nobody's ever stopped me."],["A","That's not really a yes."],["B","It's the best I've got."]],[["B","First to two or three?"],["A","Whatever's normal here. I've been watching, I still can't tell."],["B","Two. Then people complain and we do three."]],[["A","That last round you had me in the corner and just stopped. Why."],["B","I lost track of my meter and didn't want to guess wrong."],["A","I was going to block low the whole time. For what it's worth."],["B","Great. Now I know that."]],[["B","You're the one who was in here before the curtain guy turned the projector on."],["A","I got here early. Didn't know if I was supposed to sit or something."],["B","You sit. Or stand. Nobody's watching that closely."],["A","Noted."]],[["A","Good games. I don't think I've played anybody who walks backward that much."],["B","I'm scared of your long poke. That's the whole plan."],["A","It's minus. You can hit me after it."],["B","Don't tell me that, I'll have to actually try."]],[["B","Are you new or have I just never looked up?"],["A","Third time here. I mostly played out on the floor before, the skee-ball side."],["B","Big drop in ticket payout back here."],["A","I noticed."]],[["A","Sorry, I didn't catch your name when you sat down."],["B","I didn't say it. I never do, it feels like a lot."],["A","Okay, well. I'm going to need something to call you when I lose."]],[["B","You dropped the same combo twice and then got it the third time. What changed?"],["A","I stopped trying to confirm it and just committed."],["B","That's what I do. It works about half the time, which is more than never."]],[["A","Is it always this cold in here or did somebody mess with the thermostat."],["B","Always. I bring a hoodie now."],["A","That's grim."],["B","It's out in the car if you want it. I run warm anyway."]],[["B","You went for a throw every single time I got up. Every one."],["A","You never teched it. I wasn't going to stop on principle."],["B","Fair. Run it back, I'll figure out the button."],["A","Sure. I'll keep doing it until you do."]]]},"food-smell":{"cat":"H","roles":{"A":[],"B":[]},"world":["concession:stocked"],"ex":[[["A","What is that."],["B","Egg salad. From home, not from out there."],["A","Out there they'd have to answer for it. In here there's no oversight."],["B","I'll finish it in the lobby. Save me the winner's side."]],[["B","Whoever's got the fish, I'm not naming names, but I know where you're sitting."],["A","It's not fish. It's the garlic thing they put on the fries now."],["B","They changed the fries?"],["A","They changed something. Nobody's admitted to it."]],[["A","Curtain's not a wall. It's a suggestion. Everything you eat, we all eat."],["B","You want me to stand in the pinball area like a smoker."],["A","Yes."],["B","Fine. Hold my chair, and don't let anyone start a set on that cabinet."]],[["B","You've had that container open since I got here."],["A","It's better warm."],["B","It's not better for anybody else. I could taste your onions during that last one."],["A","That's not why you lost."]],[["A","Two people got up and left and I don't think it was the queue."],["B","It's a chili dog. It's a normal food that normal people eat."],["A","In a dim room with no airflow and forty minutes of sets left, it's not."]],[["B","Eat it, don't just have it sitting there gassing the room out."],["A","I'm waiting for my turn. If I start eating, I'll be mid-bite when they call me."],["B","Then you'll be mid-bite. Lid on or lid off, pick one and commit."],["A","Lid on."]],[["A","Something in this room has gone off."],["B","It's the popcorn machine. It's been sitting since before anybody got here."],["A","That's not popcorn. Popcorn doesn't do that to a person."],["B","Then it's whatever's in the bin next to it and I'd rather not find out."]],[["B","You brought a hot lunch to an arcade."],["A","I came straight from work. It was this or nothing until nine."],["B","There's a whole counter that sells food. Right past the bathrooms."],["A","Have you eaten it?"],["B","...Sit further back."]],[["A","Whatever that is, it's in my hoodie now. It's coming home with me."],["B","Wash it, then."],["A","That's not the point I was making."]],[["B","Can you at least close it while we run this set."],["A","It's closed. That's what you're smelling coming through the plastic."],["B","Great. Put it under the chair."],["A","Under the chair is worse. It's warmer down there for some reason."]],[["A","Everyone's blaming the vending machines but the vending machines don't sell anything that smells."],["B","Nope. It's mine. Curry, from home."],["A","You could have let them keep guessing."],["B","I've got a bowl in my lap. It wasn't going to hold."]]]},"forgot-the-score":{"cat":"B","roles":{"A":["rel:familiar"],"B":["rel:familiar"]},"world":[],"ex":[[["A","Hold on. Are we at two, or is this still going?"],["B","I thought you were tracking it."],["A","I stopped somewhere around the one where you switched sides."],["B","Run it again either way. I'm not done finding out about that low."]],[["B","Somebody has to say a number."],["A","Three?"],["B","Three to what?"],["A","I'd take three to two in either direction, that's how little I know."]],[["A","My hands are shaking a little. That hasn't happened in a while."],["B","Same. I keep missing the confirm because I'm gripping too hard."],["A","Sit for a second. Whatever the score was, it's gone."],["B","It's gone."]],[["B","Who won that?"],["A","You did, I'm pretty sure. The last one."],["B","No, the set."],["A","Oh. Then no idea."]],[["A","You were plus on that button the whole time and I kept pressing anyway."],["B","You got away with it twice, which is why you kept going."],["A","Twice out of about nine."],["B","You were having fun. I didn't want to interrupt with math."]],[["B","Someone's waiting, we should probably wrap it."],["A","We're past first to three. We have to be."],["B","Well past. Nobody said anything, so I didn't either."],["A","Let them have it. My thumb's done anyway."]],[["A","Every neutral in that was different. You never gave me the same opening twice."],["B","I was reacting. I didn't plan any of it."],["A","That's worse for me."],["B","It's worse for me too, I can't do it again on purpose."]],[["B","I want to say I lost more than I won."],["A","That's my read too, and we can't both be right."],["B","So one of us is being modest."],["A","Not me. I genuinely don't remember winning."]],[["A","Did anybody see any of that?"],["B","Two guys behind us, and one of them left partway."],["A","So it's just us then."],["B","Just us. Which is fine, I don't want it on a screen anywhere."]],[["B","You stopped going for the throw at the end there."],["A","Because you were teching it every single time. I had to find something else."],["B","Whatever you found worked. I have no idea what the count is now."],["A","Neither do I, and I'd like to keep it that way for one more."]],[["A","How long were we on there?"],["B","Long. My drink's warm and I got it after the first game."],["A","Did we finish the set or just stop?"],["B","Stopped, I think. Nobody counted, nobody said next."]],[["B","That's the best I've played here."],["A","You were reading the low every time it mattered. I felt like I was announcing it."],["B","You weren't. It just kept coming at the same point in the string."],["A","Great. Now I've got something to lab, and no idea if I won."]]]},"friends-in-bracket":{"cat":"G","roles":{"A":["rel:close"],"B":["rel:close"]},"world":["tournament:today"],"ex":[[["A","They put us on the same side of the bracket again."],["B","Someone did that on purpose."],["A","Nobody here is organized enough to do anything on purpose."],["B","Then it's just bad luck and I'm still taking it personally."]],[["B","You want to warm up first or just go?"],["A","We warmed up for an hour before this. Twice, if you count the drive."],["B","Fine. Loser gets the food run."],["A","Loser is going to be too sad to order correctly."]],[["A","Don't go easy."],["B","When have I ever."],["A","There was that one where you didn't press the punish and I know you saw it."],["B","I dropped it. I'd rather you thought I was being nice."]],[["B","This is the part where I pretend I don't know what you're doing."],["A","You do know, though."],["B","I know all of it. Doesn't mean my hands do."]],[["A","Whoever loses this is out, right?"],["B","No, there's losers side. You get to lose again later, in front of more people."],["A","Great. Something to build toward."]],[["B","We've played this set a hundred times in your living room."],["A","There's a bracket sheet with our names on it now. It's different."],["B","It's a piece of paper on a whiteboard."],["A","Then why are your hands doing that."]],[["A","If I win, I don't want to hear about the buttons."],["B","The buttons are genuinely bad on that side."],["A","Then take my side, I'll go over there."],["B","No. Then I've got nothing to say afterward."]],[["B","Sit down, they're calling us."],["A","I need a minute. I ate too much popcorn."],["B","That's the third time you've said that at a tournament."],["A","And I've been right every time."]],[["A","Weird playing you when it counts."],["B","It counted at my place too. You cried."],["A","I did not cry, I went out to the car."],["B","For twenty minutes."]],[["B","I labbed something specifically for you."],["A","Of course you did."],["B","It's not even good. It just annoys you specifically."]],[["A","Handshake now or after?"],["B","Now. After, one of us is going to be insufferable."],["A","Both of us, historically."]]]},"furious-nonsense":{"cat":"A","roles":{"A":["lost","mood:low"],"B":["won"]},"world":[],"ex":[[["A","I had you in the corner and you just pressed a button. That shouldn't work."],["B","It's plus on block. I keep telling you it's plus."],["A","Nothing's plus on block. Nothing in this entire game is plus on block."],["B","Okay."]],[["B","You want water? There's a machine right there."],["A","I want the buttons to be the same on both sides. That's all. That's the only thing I want out of this room."],["B","They are the same buttons."],["A","Then I don't know what happened."]],[["A","I'm done. I'm not doing this. Run it back."],["B","Which one of those?"],["A","Run it back. Then I'm done."]],[["B","You alright?"],["A","Somebody out there wins a stuffed animal and screams every single time I'm in a last round. Every time. It's the same kid."],["B","Want me to go ask them to keep it down?"],["A","No."]],[["A","You're not even playing it properly. You're not supposed to be able to win doing that."],["B","Okay."],["A","Don't say okay like that."],["B","What am I supposed to say?"]],[["A","That's the worst set I've ever played and I played fine the whole way through."],["B","Those can't both—"],["A","They can."]],[["A","I'm gonna go lab it. I'm not labbing anything, there's nothing to lab, the matchup's just bad and everyone knows it."],["B","So don't lab it."],["A","I'll lab it tonight."]],[["B","You had me in that one before you switched sides. That was close."],["A","Don't."],["B","Don't what?"],["A","Be nice about it in ten minutes. Not now."]],[["A","Four hours of sleep. Not that it makes any difference, you don't need sleep to press buttons."],["B","Sure."],["A","It makes some difference."]],[["A","This pad's cooked."],["B","Take mine, I'm not using it."],["A","It's not the pad."]],[["A","Say something."],["B","Nice set."],["A","That's worse. That's so much worse."],["B","Then what do you want."]],[["A","I win that four times out of five."],["B","We played five."],["A","Yeah, and I lost the wrong ones."]]]},"game-is-fading":{"cat":"L","roles":{"A":["veteran"],"B":["veteran"]},"world":["relevance:falling"],"ex":[[["A","Bracket's down to twelve next weekend. They didn't even cut it, that's just who signed up."],["B","Twelve's fine. Twelve is everyone who was ever going to show up anyway."],["A","It was thirty in the spring."],["B","Some of those thirty were bad. I'm keeping the twelve."]],[["B","The big tournament dropped us off the main stage. We're in the side hall now, apparently."],["A","Do we still get a stream?"],["B","Second stream. Same one the tabletop stuff is on."],["A","So a camera pointed at a TV. Same as here, then."]],[["A","Nobody's posted a combo video in months. I keep checking."],["B","There's nothing left to find. That's not a sad thing, it's just what happens when everyone's done looking."],["A","Feels sad from where I'm standing."],["B","Then find something and post it."]],[["B","You ever think about learning the new one?"],["A","I looked at it. Everything's faster and I don't like the throw range."],["B","That's what I said too. Out loud, to someone, so now I have to mean it."]],[["A","The tier list thread finally died. Last reply was three weeks ago and it was someone asking if the thread was dead."],["B","Did anyone answer?"],["A","No."],["B","Then it's not dead. It's just slow."]],[["B","You notice the curtain crowd used to fill both rows of chairs."],["A","We fill one row and half of them are waiting for the skee-ball tickets to print."],["B","They still watch. Watching's watching."],["A","I'll take it. I just remember the noise."]],[["A","Got asked at work what game I play competitively and I couldn't make the name land."],["B","You have to say it twice, that's normal."],["A","I said it three times and then said it's like the one with the swords, which it isn't."],["B","Close enough. They weren't going to look it up."]],[["B","Patch notes came out. Two lines."],["A","What'd they change?"],["B","A crash on one of the menus and a spelling mistake in the credits."],["A","So we're balanced. Officially."]],[["A","Half the players I used to lose to don't exist anymore. Online, I mean, the names are just gone."],["B","They didn't quit, they just stopped queuing. Different thing."],["A","Not to me it isn't. I had stuff worked out for those matchups."],["B","I'll play the matchup. I'm worse at it, but I'm here."]],[["B","Someone in the lobby asked if this game was old."],["A","What'd you tell them?"],["B","Yes. Then they asked if it was any good and I said also yes, and they went to play the racing one."]],[["A","We should run a bigger event. Get people back in."],["B","With what pot? Everyone who'd put in is already standing in this room."],["A","So we pass the same forty dollars around all night."],["B","We already do that. At least this way there's a bracket attached."]],[["B","You still labbing that setup you were on last month?"],["A","Yeah. Nobody's going to see it, but yeah."],["B","I'll see it."],["A","You'll block it, which is worse."]]]},"genuinely-bad-matchup":{"cat":"F","roles":{"A":["settled"],"B":["settled"]},"world":[],"ex":[[["A","I can't get in. That's not me being sour about the set, it's just what the matchup is."],["B","You can get in. You'll take a hit doing it, but the door's there."],["A","Right. That's what I said."]],[["B","How many times did you block that long low poke tonight?"],["A","All night. It's plus and nothing I have reaches that far."],["B","So we've solved the matchup."],["A","You've solved it. I'm still standing here."]],[["A","You looked half asleep out there."],["B","I'm not asleep, I'm waiting. If I move first in this matchup I lose, so I don't move."],["A","That was the entire game though. Both of us standing still."],["B","Yeah. That's the matchup."]],[["B","Do you actually like this matchup? Be honest."],["A","No. I win it and I don't like it."],["B","Okay. That's fair, then."]],[["A","Three people have now told me to just pick up a second character for this."],["B","You're not going to."],["A","No. I'll keep losing this exact matchup until something gets patched, and then I'll probably still lose it."]],[["B","The tier list people have this at six-four."],["A","The tier list people aren't in this room getting my whiffed sweep blocked for free."],["B","So worse than six-four."],["A","I'm not putting a number on it. I'm just tired of it."]],[["A","Sit for a second. I'd rather ask you about this matchup than lose to it again first."],["B","Ask."],["A","At that range, right before you step in. What am I supposed to be pressing?"],["B","Nothing. Walk back and make me come further. That's the real answer and I know you hate it."]],[["A","Bad matchup for you?"],["B","Worst one I've got."],["A","Want to stop?"],["B","No."]],[["B","Once you knock me down I don't get to play. There's no gap anywhere in your oki."],["A","There's one. You have to guess right twice in a row."],["B","Then there's no gap."]],[["A","I think I lose this matchup."],["B","I've thought I lose it since the first time we played."],["A","One of us is wrong, and it's not getting settled tonight."]],[["B","I labbed this matchup all week. Every button, every range."],["A","And?"],["B","The lab doesn't have you in it."],["A","That's usually where it falls apart, yeah."]]]},"good-sport-cost":{"cat":"A","roles":{"A":["lost","humor:earnest"],"B":["won"]},"world":[],"ex":[[["A","Good set. Genuinely."],["B","You don't have to say it right away. I can wait."],["A","No, I want it done while I still mean it."]],[["B","You're shaking my hand very firmly."],["A","That's the only part of this I've got control over."],["B","Understood."]],[["A","The low into the mix-up. That's the answer, isn't it. That's been the answer all night."],["B","Pretty much, yeah."],["A","Great. Good. That's useful. I'm going to go stand by the vending machine and think about it."]],[["A","You outplayed me. I'm not going to pretend the buttons did it."],["B","The buttons on that side are bad, though."],["A","Don't. I've already decided not to say it and you're making it very hard."]],[["B","You want to run it back?"],["A","Yes. Not right now. In a bit."],["B","I'll be here."],["A","I know. That's part of the problem."]],[["A","Nothing to be mad about. You were reading me the whole time and I kept giving you the same thing."],["B","You're being weirdly nice about it."],["A","I'm trying it out. Being mad hasn't worked either."]],[["B","You okay?"],["A","Fine. Learning. Losing and learning, which is the good kind."],["B","You're saying that with your jaw locked."],["A","It's a process."]],[["A","That whiff punish at the end was clean. Sat there and waited for it and I walked straight in."],["B","You were doing it every knockdown."],["A","Yeah. Say more, actually. Get it all out now while I'm still being reasonable."]],[["B","You're stacking the chairs."],["A","Somebody has to. Might as well be somebody with nothing better going on."],["B","You could just be annoyed at me instead."],["A","I'm doing both."]],[["A","You've gotten better at the neutral. That's real, I'm not just saying it."],["B","Been labbing the spacing on the long poke."],["A","I can tell."],["B","You want me to show you what I found?"],["A","Not tonight. Tonight I'd resent it."]]]},"grudge-nobody-recalls":{"cat":"C","roles":{"A":["rel:hostile"],"B":["rel:hostile"]},"world":["arcade:established"],"ex":[[["A","You've got next on this one after me."],["B","I'll take the other side of the room."],["A","Both other setups have three people on them."],["B","Then I'll wait."]],[["B","Board says you're running the bracket tonight."],["A","It does."],["B","Then I'm not entering."],["A","Nobody put your name up."]],[["A","Still owe me twenty, {t}."],["B","You still saying that out loud."],["A","Every time I see you, apparently."],["B","Easy fix on your end."]],[["A","The kid on the second cabinet asked me why we never play sets. I told them to ask you."],["B","They did. I said it was before their time."],["A","Nice and clean."],["B","It was true."]],[["A","You paused."],["B","My cable came out of the back of the stick."],["A","It came out."],["B","Play somebody else."]],[["B","I've got you three to one in tournament, all time."],["A","Three to two. One of those was you DQ'ing me because I was in the bathroom."],["B","Bracket's the bracket."],["A","Sure."]],[["A","Nobody's asked me about you in months. Not once."],["B","Good."],["A","I didn't say I'd stopped thinking about it."],["B","Also good."]],[["A","That's my stick."],["B","It's been in my bag longer than it was ever in yours."],["A","That isn't how borrowing works."],["B","Buttons are mine, case is yours. Take the case."]],[["B","You taught half the room the oki I showed you."],["A","It's in the game. Anyone can find it."],["B","You were writing it down while I was still talking."],["A","Then talk less."]],[["B","You moved chairs when I sat down."],["A","I wanted to be closer to the screen."],["B","Screen's behind you now."],["A","Then I moved wrong."]],[["A","First to three. Right now, this setup."],["B","No."],["A","You've said no every time since the finals."],["B","And it keeps holding up."]],[["A","Somebody sat us at the same table for the anniversary thing."],["B","I ate out by the ticket counter."],["A","I know. I watched you do it."]]]},"hate-your-character":{"cat":"E","roles":{"A":["settled"],"B":[]},"world":[],"ex":[[["B","You had other options at the start. You know that, right? A whole roster of them."],["A","I picked the one I liked."],["B","You picked the one with the button that's plus and also hits low and also I can't see it coming."],["A","Those are three things I like."]],[["A","Set?"],["B","Give me a minute. I have to get in the right frame of mind about your character."],["A","How long does that usually take."],["B","Historically I never get there. I just start playing anyway."]],[["B","Every time I block that overhead I feel like I got away with something instead of like I did my job."],["A","That's the correct feeling. That's what the move is for."],["B","See, you say that like it's fine."]],[["A","You always groan when the select screen loads. Every time. Before I've even moved the cursor."],["B","I know where the cursor's going."],["A","I could switch."],["B","You won't, and I'd rather lose to something I understand."]],[["B","Nothing personal. It's the character."],["A","It's a little personal. I'm the one pressing the buttons."],["B","Fine. It's forty percent you."]],[["A","You went in the lab against my main, didn't you."],["B","An hour. I found out the low is only minus if I block it point blank, which never happens, so that was a great use of an hour."],["A","You could just ask me."],["B","Then I'd have to admit I care."]],[["B","How do you sit down and choose that."],["A","I liked the walk speed."],["B","The walk speed."],["A","Everything else came after. But yeah. The walk."]],[["A","You beat me three straight and you're still complaining."],["B","Winning against that character doesn't feel like winning. It feels like the round ended."],["A","Take the wins. Nobody's giving you a different set."]],[["B","There's a version of you that plays somebody honest and we're friends in that timeline."],["A","We're friends now."],["B","We're friends between games."]],[["A","You held the throw all set. Every single knockdown."],["B","Because with your main it's always the throw. I've stopped thinking about it. I just hold it and get on with my life."],["A","Good, because I stopped going for it two games ago and you kept holding."],["B","...yeah, that tracks."]],[["B","Somebody at the desk asked me what the best character is and I said anything but yours."],["A","Helpful."],["B","They went to play skee-ball instead. So in a way I saved them."]],[["A","You know I didn't design the character."],["B","I'm aware of the chain of responsibility. You're just the closest link."],["A","So what do you want me to do about it."],["B","Nothing. Keep your controller. I'll be over here."]]]},"introducing-two":{"cat":"D","roles":{"A":["veteran"],"B":["rel:stranger"],"C":["rel:stranger"]},"world":[],"ex":[[["A","You two have been standing shoulder to shoulder for an hour without saying anything."],["B","I assumed we'd met."],["C","We've played twice tonight. Close enough for me."]],[["C","Who am I playing after this one?"],["A","Them, and you should have been playing them a month ago. You're grinding the same matchup from opposite sides and complaining to me separately."],["B","I'm the losing side of it."],["C","Then sit down."]],[["B","My stick's been dropping inputs since I walked in."],["A","Talk to this one. Half the sticks in here have been opened up on that table over there."],["C","I can look at it. I'm not promising anything and I'm not buying parts."],["B","That's fine."]],[["C","We've never actually talked, have we."],["B","I know the name off the bracket sheet."],["A","You've sat through each other's sets all night. Both of you. Every set."],["C","I was watching the screen."]],[["A","This is the one who put you out in winners. You complained to me about it for twenty minutes afterward."],["B","I didn't know it was them."],["C","You said nice set at the time."],["B","I say that no matter what happened."]],[["B","That's the other one who plays my character, right?"],["A","Same character, and neither of you has said a word to the other. It's been strange to watch."],["C","You spend meter ending combos. I've noticed that much."],["B","Does it not work?"]],[["C","I've walked past this curtain for weeks. I thought it was storage."],["A","It's not. And this is the person who's been winning in here the whole time you were on skee-ball."],["B","There were four of us tonight. It's not much of a claim."],["C","I'll grab a chair anyway."]],[["A","Names. Go."],["B","We've read each other's names off the screen plenty of times."],["C","Couldn't say it out loud, though."]],[["B","I've asked you about that corner pressure four separate times and you keep guessing."],["A","Because I am guessing. Ask this one, they hold it better than anybody here."],["C","I don't hold it. I lose to it slower."],["B","Still ahead of where I am."]],[["A","Introduce yourselves before one of you stops showing up."],["B","Is that about to happen?"],["C","Happens to everyone eventually. Hi."],["B","Hi."]],[["C","Is anybody here on Thursdays? Weekends are dead for me."],["A","This one is only ever here Thursdays. You've been missing each other by a whole calendar."],["B","I work weekends."],["C","Same."]]]},"is-the-game-good":{"cat":"F","roles":{"A":["veteran"],"B":["veteran"]},"world":[],"ex":[[["A","Game's fine. People just don't want to block."],["B","Say that again after twenty seconds in the corner."],["A","I've been in the corner. I got out. Once."]],[["B","You've told me this game is broken every week since the last patch and you're still in here on your day off."],["A","It's broken and I like it. Those aren't arguing with each other."],["B","They're arguing a little."],["A","Get in the queue."]],[["A","None of us are good enough for the balance to matter."],["B","I lose to the same oki everybody's complaining about, so it matters to me."],["A","You lose to it because you press buttons while you're still getting up."],["B","Yeah. That's what everybody's complaining about."]],[["B","It was better before they touched meter gain."],["A","It was better because you had every answer memorised and now you don't."],["B","Having the answers is the good state."]],[["A","It's not the character. It's that one person in here plays it properly and nobody else does."],["B","So the character's fine as long as no one does it right."],["A","Yes."]],[["B","Two people came through the curtain last month and neither one came back."],["A","That's not the game. That's us."],["B","It's a bit the game. First-timers can't see what's hitting them."],["A","It's mostly us. I watched you run a whole set on somebody who'd had a stick in their hands for a week."]],[["B","Meter comes back too fast. Losing the entire round and still cashing in at the end feels wrong."],["A","Feels wrong or is wrong?"],["B","Don't do that."],["A","You do it to me constantly."]],[["A","I think I'm done with it until they change something."],["B","You're not sick of the game, you're tired. You haven't taken a weekend off since spring."],["A","Could be both."],["B","Take the weekend. If you still hate it after, I'll actually listen."]],[["A","Would you rather it was fair or fun?"],["B","That's a bad question and you know it's a bad question."],["A","Pick anyway."],["B","Fun. And I'm not defending it."]],[["B","That tier list going round has my character dead last."],["A","Have you been losing to the ones near the top?"],["B","Not the way the list says I should be."]]]},"just-reopened":{"cat":"H","roles":{"A":[],"B":[]},"world":["arcade:reopened"],"ex":[[["A","Four days off and my hands are stupid. Dropped the same confirm three times in a row."],["B","I was fine in training mode at home. Sat down here and forgot which button does what."],["A","So it's the room."],["B","It's the room."]],[["B","Anybody actually say why we were closed?"],["A","Something with the walk-in freezer. Concession's cold sandwiches only for now."],["B","So no nachos."],["A","No nachos. Bring your own if you're that invested."]],[["B","Thin in here tonight."],["A","People stopped checking. I texted a couple and both said they didn't know we opened back up."],["B","It's on the whiteboard out front."],["A","Yeah, well."]],[["A","Both setups are on the one power strip now. That's new."],["B","That's why the left screen dips when the popcorn machine kicks on."],["A","Does it dip enough to matter?"],["B","It did in my last set. I'm claiming the right one from here on."]],[["B","I labbed the whole shutdown with nobody to try any of it on. It's stacked up in there."],["A","Try it on me, then."],["B","Half of it isn't finished."],["A","Best-of-five will finish it."]],[["A","Vending machine's completely full."],["B","They cleared it out before we closed. Everything in there's new stock."],["A","Did they finally drop the green ones nobody touches?"],["B","Two rows. They restocked what didn't sell."]],[["B","First four days I haven't touched the game since I started coming. Slept like a normal person."],["A","And?"],["B","I'm not mashing out of every knockdown. Feels like I can actually see the neutral."],["A","Give it two weeks."]],[["B","Is the bracket dead or did they push it?"],["A","Pushed. Same entry, they're keeping everyone who already signed up."],["B","So I don't pay again."],["A","You don't pay again. You do have to show up, which historically is the harder part for you."]]]},"just-stopped-turning-up":{"cat":"K","roles":{"A":["veteran"],"B":["veteran"]},"world":["arcade:established"],"ex":[[["A","You hear anything?"],["B","Nothing. Phone's on, messages go through, no reply."],["A","So not a falling out. Just done."],["B","Looks like it."]],[["B","Their stick's still in the cubby back there. Been there weeks."],["A","Leave it. If it's gone next time we'll know they came by."],["B","And if it isn't?"],["A","Then it's still there."]],[["A","I keep leaving that chair open."],["B","I noticed. Somebody sat in it last week and I had a whole reaction I didn't say out loud."],["A","It's a folding chair."],["B","I know what it is."]],[["B","Nobody blocks low against me anymore. Down to one person and that person stopped showing up."],["A","So you're just winning now."],["B","I'm winning against people who don't know that yet. It's not the same."],["A","Give it a month, everyone learns it, you'll be miserable again."]],[["A","Did anybody actually get a last set in?"],["B","I did. Didn't know it was the last one. Went long, went to the wire, we said see you next week."],["A","Who took it?"],["B","They did. Which is fine. That's fine."]],[["B","Baby, apparently."],["A","That'll do it."],["B","Said as much on the way out the door months ago and I thought it was a joke about being tired."]],[["A","Every time the curtain moves I look up."],["B","Yeah."],["A","It's been a while now. I should stop doing that."],["B","Probably. Tell me how that goes."]],[["B","Somebody should tell the new ones the reason we all crouch on wake-up here. That was one person's habit and we all built around it and now they're gone."],["A","You want to give a lecture?"],["B","I want somebody to know why we play this way."],["A","Write it on the whiteboard out front. Between the birthday deal and the token special."]],[["B","You still labbing that punish for their throw setup?"],["A","Finished it, actually. Whole thing works."],["B","On who?"],["A","Nobody. That's the part I hadn't thought through."]],[["A","Someone said they saw them out front. Playing skee-ball with a kid."],["B","Didn't come through the curtain?"],["A","Didn't come through the curtain."],["B","Fifteen feet. Unbelievable."]],[["B","I'm not going to keep asking about it every week."],["A","Nobody asked you to."],["B","You've asked me twice tonight if I've heard anything."],["A","Different thing. Who's got next."]]]},"known-from-stream":{"cat":"D","roles":{"A":["rel:stranger"],"B":["rel:stranger"]},"world":["stream:growing"],"ex":[[["A","You're taller than the camera makes you look."],["B","That's the angle. Everyone's a gremlin on that stream."],["A","I've watched you play maybe a dozen sets and never once seen your face."],["B","Keeps the mystery going. Are you in for the next one or just here?"]],[["B","I know your inputs. I don't know you."],["A","That's fair. I've never sat in this room before, I usually just have the stream up while I'm cooking."],["B","So you've watched me lose several times and I've got nothing on you."],["A","Nothing at all."]],[["A","Wait. You're the one who does the low sweep into nothing and then wins anyway."],["B","I do do that."],["A","I've argued about it in chat."],["B","I don't read chat, so as far as I'm concerned you lost the argument."]],[["B","Your name came up on the screen last week and I couldn't place a person to it."],["A","And now?"],["B","Still can't, really. But you're standing there, so."]],[["A","Sorry, I keep staring. You sound different than you look."],["B","The mic's on a stand about a foot too low. Makes everyone sound like they're at the bottom of a well."],["A","I assumed you just talked like that."],["B","Some days."]],[["B","Are you the one who beat that whole bracket without saying a word?"],["A","I said things. The mic wasn't near me."],["B","Everyone in chat had a theory about you."],["A","Do I want to know?"],["B","No."]],[["A","Recognised the jacket before I recognised anything else."],["B","It's in every single archive. I should rotate."],["A","Don't. It's how people find your sets."]],[["A","Are you the one who plays with the controller in your lap?"],["B","That's me. My wrists gave up on the tabletop thing."],["A","I tried it after watching you. Made everything worse for a week and then better."],["B","That tracks. Sit down, I'll show you where I rest my elbow."]],[["B","You've never played here, have you. I'd remember."],["A","First time in the room. I've had the channel on since around when it started getting busy."],["B","So you know the layout without knowing the layout."],["A","I knew the popcorn machine was over there. Didn't know it was that loud."]]]},"long-close-set":{"cat":"B","roles":{"A":["rel:familiar"],"B":["rel:familiar"]},"world":[],"ex":[[["A","My hands are done. I can feel the buttons in my wrists."],["B","Sit there then. Nobody's waiting."],["A","Somebody's waiting."],["B","They can want it a little longer."]],[["B","How long was that."],["A","No idea. The popcorn machine was still going when we started."],["B","It's off now."],["A","Yeah."]],[["A","You're not getting up either, I notice."],["B","I stood up once around the middle of that and it went badly."],["A","Water's four steps away."],["B","Bold of you to count them from a seated position."]],[["A","That last one shouldn't have been that close. I had it twice."],["B","You had it three times. I was counting because I had nothing else going on."],["A","Great. Thanks."],["B","You asked what I was doing back there."]],[["B","I need to stop blocking low on the wake-up. You got me with the same thing at the end of every game."],["A","I know. I kept waiting for you to fix it and then I stopped waiting."],["B","Say that again in like ten minutes, I'll write it down."]],[["A","Somewhere in the middle there I stopped thinking and it got better."],["B","I noticed. You quit hesitating in neutral, which was rude of you."],["A","Can't do it on purpose."],["B","Good. Keep not knowing how."]],[["B","My chair's warm. That's how long we've been in here."],["A","Mine squeaks now. It didn't when we sat down."],["B","You broke a folding chair."],["A","We broke a folding chair."]],[["A","Run it back?"],["B","Ask me that once I can lift my arms."],["A","So yes."],["B","Eventually yes."]],[["B","I have work at seven."],["A","You said that two games ago."],["B","It's more true now."]],[["B","You changed your throw timing after I started teching. Which was fine. I just want you to know I saw it."],["A","Took you long enough."],["B","I saw it early. Couldn't do anything about it, which is a different problem."],["A","That's the one I'd work on."]],[["A","I'm hungry but the walk out there sounds enormous."],["B","They're closing the fryer soon anyway."],["A","So we sit."],["B","We sit."]]]},"long-night-settling-in":{"cat":"J","roles":{"A":[],"B":[],"C":[]},"world":[],"ex":[[["A","Who's actually staying? I need to know if I'm buying the big popcorn."],["B","I'm here till they make me leave."],["C","Buy it anyway. If they bail I'll eat it."],["A","That's not a plan, that's just you eating popcorn."]],[["B","Bracket's done, so it's just us and whoever wanders in."],["A","Good. I want long sets. Not this best-of-three nonsense where I lose before I've woken up."],["C","First to seven?"],["B","First to whenever somebody's hands stop working."]],[["C","I moved my car so I don't have to think about it later."],["A","How late are you thinking."],["C","I told my roommate not to wait up, so."],["B","Then you're on the second setup with me. The one where the buttons are fine."]],[["A","Chairs. We need one more chair."],["C","There's a stack behind the popcorn machine."],["B","Two of those are broken and nobody's marked which."],["A","I'll sit on it and find out."]],[["B","Anyone eaten? Because I'm going to get worse around ten if I don't."],["A","Concession's still open. It's fries or it's fries with cheese on."],["B","Fine. Someone hold my spot."],["C","Nobody holds spots. Come back and get in line like everyone."]],[["C","You brought your own pad. That's a commitment."],["A","Last time I played on the house sticks for four hours and couldn't hold a fork after."],["B","Plug in on the left, then, the right port's loose."],["A","Left it is."]],[["B","I want to work on my neutral tonight. Actually work on it, not just say it."],["C","Then don't play me first. I'll rush you and you'll forget you said that."],["A","Play me. I'm slow and my pokes are honest."],["B","You've never been honest about anything on that side of the screen."]],[["C","They turned the front lights down. Family crowd's cleared out."],["A","That's the good part of the night."],["B","You can hear skee-ball again once the kids go. Whoever's out there is an adult playing skee-ball alone."],["C","Leave them be."]],[["B","Someone put something on the projector. It's just the menu screen sitting there."],["A","Put whatever's streaming. Nobody's watching it, it's for the noise."],["C","Then leave it off and talk to each other, you animals."],["B","I'm putting it on."]],[["C","How long are you both good for, roughly? I'm trying to work out if I lab now or later."],["A","Later. Lab when we're all too fried to play sets properly."],["B","That's when I do it too. Worst practice of my life, every time."],["C","Later, then."]]]},"low-on-the-list":{"cat":"F","roles":{"A":["main:lowtier"],"B":[]},"world":["tierlist:new"],"ex":[[["A","Bottom three. Whoever's doing the math on that list has never blocked my sweep."],["B","Nobody blocks your sweep. That's sort of the argument for you being higher."],["A","Then go tell them."],["B","I did. They asked how many majors you've won."]],[["B","You seen the update?"],["A","Yeah. I got moved down a row, which is fine, I don't care."],["B","You've said that twice now and I only asked once."]],[["A","Low tier's not the problem. The problem is people looking at the list and then playing me like I can't do anything."],["B","So that's good for you."],["A","It's great for me for about two sets. Then they figure it out and I'm back to having no buttons."]],[["B","Are you switching?"],["A","To what."],["B","Anything above the third row. Half the room did it this week."],["A","I'd have to learn a whole new set of confirms and I'm barely landing the ones I've got."]],[["A","They put me under the one with the eight-frame launcher. Eight frames."],["B","Placement's mostly who's been winning locals, not the frame data."],["A","Then call it a results list and stop calling it a tier list."],["B","Bring that up at the next meet. Slowly, so someone writes it down."]],[["A","Whole list dropped and I didn't get one comment. Not one person messaged me about it."],["B","What did you want them to say?"],["A","Something. Argue with it. It's like everyone agreed and moved on."],["B","I'll argue with it if you want. I don't have material, but I'll argue."]],[["B","You're taking the tier list better than I expected."],["A","I've been down there since the first one. Nothing changed except the picture got worse."],["B","There's a picture?"],["A","Somebody drew little crowns on the top row. Very professional."]],[["A","Do me a favor and don't bring the list up while we play."],["B","Wasn't going to."],["A","You brought it up in the concession line."],["B","That was outside the curtain. Different rules out there."]],[["B","Somebody should ask what the list is actually for."],["A","It's for people who want to know if losing was their fault."],["B","And it told them no."],["A","It told them no in bold."]],[["A","I labbed the whole matchup chart after they posted it. All the ones marked bad for me."],["B","How bad were they?"],["A","Two are wrong. I can win both if they respect the low. The rest, yeah, they got it right."],["B","Two's more than nothing. Show me the low one, I'll block wrong for you."]],[["B","Rough week for your main."],["A","You want to play or you want to keep reading the whiteboard."],["B","I can do both."],["A","Sit down then, the list isn't going anywhere."]],[["A","Every time that list updates I lose two of my regular opponents. They just stop picking me up."],["B","They think there's nothing to learn off you."],["A","Right. Which is how I go a whole night without a set."],["B","I'm here till they close the curtain. Run it as long as you want."]]]},"lowball-the-win":{"cat":"A","roles":{"A":["lost","mood:low"],"B":["won"]},"world":[],"ex":[[["B","That could've gone either way. Genuinely."],["A","It went one way. Two to nothing."],["B","Fine, but the second one was a coinflip at the end and we both know it."],["A","Sure."]],[["A","You don't have to do the humble thing. I'd rather you just took it."],["B","I'm not being humble, I dropped a confirm in there and got away with it."],["A","You dropped one. I dropped four."],["B","Then we're both bad and I got luckier. Works for me."]],[["B","I was guessing on your oki the whole time. Blind guessing."],["A","Guessed right, though."],["B","Yeah. Not something I can rely on."],["A","Rely on it a bit longer, apparently."]],[["A","Say something."],["B","Your buttons felt slow to me. Might be the stick on that side."],["A","Don't hand me an excuse."],["B","I'm not. I'll take that side next time and you can watch me lose on it."]],[["A","You're going to tell me it was close."],["B","It wasn't. But I've lost that exact set to you before."],["A","Not tonight I didn't."],["B","No."]],[["B","I want another one, that felt like nothing. Didn't learn a thing."],["A","I'm not going again right now."],["B","Okay. Whenever."]],[["A","Whatever you're about to say, skip it."],["B","I was going to ask if you wanted popcorn."],["A","...No."],["B","I'll get some anyway. Chair's yours if you want to sit through the next one."]],[["A","Two-nothing. Go on."],["B","You were up in the first one and pressed a button you didn't need to press."],["A","I know which button."],["B","Then that's the whole set, really."]],[["B","You want the seat back? I'm happy to give up next."],["A","You won. Just hold it."],["B","I don't feel like I earned holding it."],["A","Nobody's asking how you feel about it. Sit down."]]]},"mentor-going-badly":{"cat":"J","roles":{"A":["mentor"],"B":["student","mood:low"]},"world":[],"ex":[[["B","I don't want notes right now."],["A","Okay."],["B","...What were you going to say."]],[["A","You blocked low every time they walked forward. Every single time."],["B","I know what I did."],["A","Then say it back to me so I know you know it."],["B","I'm not doing that."]],[["A","Sit one out. Go watch the other setup for a bit."],["B","Watching doesn't fix my hands."],["A","Neither does getting back on there in this mood."],["B","I'm not in a mood. I'm behind."]],[["A","You're spending meter the second the bar fills."],["B","If I hold it I die with it."],["A","You die with it because you're saving it for the super instead of using it to get off the ground."],["B","Either way I'm dead and the bar's full. Great system."]],[["B","How many more sets of this before it starts working."],["A","I don't have a number for you."],["B","Make one up."],["A","Six."]],[["A","Want anything? I'm going out to the counter."],["B","I want to run it back."],["A","You've run it back three times and each one's been worse than the last. Eat something. Popcorn from that machine doesn't count."],["B","After."]],[["A","You went for that throw from way out of range. You knew it wasn't reaching before you pressed."],["B","You've said that three times tonight."],["A","You've done it three times tonight."],["B","Noted."]],[["B","The matchup's bad. You know it's bad."],["A","It's bad. It isn't this bad."],["B","Feels this bad."]],[["B","I'm heading out."],["A","It's early."],["B","It's early and I'm playing like that, so."]],[["A","Two things to look at before next week. Just the two."],["B","You said two last time and by the end it was five."],["A","It was two. The other three were context."],["B","Write them on something and I'll read it when I'm not like this."]],[["B","You could have told me they do that before the set instead of after."],["A","I did tell you. Sitting right here, before you put your coin in."],["B","Then you told me badly."],["A","Possibly."]]]},"mentor-going-well":{"cat":"J","roles":{"A":["mentor"],"B":["student"]},"world":[],"ex":[[["A","You blocked low three times in a row there. That on purpose?"],["B","Yeah. I saw it coming the second time."],["A","Then quit looking over at me right after. You're telling me you got it."]],[["B","I want to start doing the longer combo route."],["A","Your current one drops about one in ten. Get that to none and we'll talk about the long one."],["B","So that's a no."],["A","It's a later."]],[["A","What'd you find last night?"],["B","The throw loop doesn't work on the short characters. Spacing's off by a hair and they fall out."],["A","I've been saying that for a while and nobody ever goes and checks."],["B","I checked."]],[["B","Were you going easy on me that set?"],["A","No."],["B","Huh."],["A","Don't get strange about it, just plug back in."]],[["A","You spent meter getting out of something you could have just blocked."],["B","It felt scary."],["A","All of it's scary. Hold it and be scared with the bar full."]],[["B","You always wait a beat before you stand up off a knockdown."],["A","Because you always press. And now you've said it out loud, so I have to go change it."],["B","Should I not have told you?"],["A","Not me, no."]],[["A","That last one, the punish at the end. Good."],["B","I didn't see the whiff. I just pressed."],["A","Pressed at the right time. I'll take it for now."]],[["A","You beat someone who beats me."],["B","You want me to say I got lucky?"],["A","I want you to write down what you did before it leaves your head. Do it now, I'll hold the setup."]],[["A","Show me the corner knockdown thing again. Slower."],["B","You're asking me?"],["A","Don't make an occasion out of it. Meaty first, then the throw."]],[["B","What'd I do wrong that set? You had a face on."],["A","You won."],["B","You still had a face on."],["A","You won with one button I gave you three weeks ago and nothing else in your hands."]]]},"meta-gone-stale":{"cat":"F","roles":{"A":["veteran"],"B":["veteran"]},"world":["meta:stale"],"ex":[[["A","I know what you're doing before you do it. That's not me reading you anymore, that's just the game."],["B","Same from here. I stopped guessing a while ago. Now I just wait."],["A","So we're both waiting."],["B","Somebody presses eventually. Usually me."]],[["B","You running it or sitting?"],["A","I'll run it. I don't have anything new for you though."],["B","Nobody's got anything new. That's not a reason to sit."]],[["A","Spent an hour in training mode last night and came out with nothing."],["B","What were you working on?"],["A","Nothing specific. That was the problem, I just stood there doing my normal combo over and over."],["B","That's not labbing, that's fidgeting."]],[["A","Any word on them touching anything?"],["B","No. I quit checking."],["A","I still check. Same page every time, same numbers on it."]],[["B","You picked somebody different."],["A","Felt like it."],["B","It went badly."],["A","Sure, but I didn't know what was coming next, and I can't say that about my main right now."]],[["A","If I have to block that same setup off a knockdown one more time I'm going to let it hit me just to see something else happen."],["B","You'd lose."],["A","I'd lose differently."],["B","You'd lose the same and be annoyed about it."]],[["A","What if we ran first-to-five tonight instead. Longer sets."],["B","Longer sets of exactly this."],["A","More of it, yeah."],["B","Fine. I'm not doing anything else."]],[["A","People used to stand out by the popcorn machine arguing about matchups until somebody made them play."],["B","There's nothing left to argue about. Everyone agrees on all of it."],["A","That's the part I don't like."],["B","Yeah."]],[["B","The new one on the second setup is having a great night."],["A","Because they haven't worked out what's actually good yet."],["B","Don't tell them."],["A","I want to lose to them at least once before somebody does."]],[["A","I played skee-ball for twenty minutes before I came back here."],["B","Any good?"],["A","Same as it always is. But I don't ask skee-ball for anything."]],[["A","Three setups going and two of them are the same character."],["B","It works. What do you want them to do."],["A","Anything else. Pick badly on purpose."],["B","You've played one character since I've known you."],["A","I know."]]]},"might-close":{"cat":"I","roles":{"A":["veteran"],"B":["veteran"]},"world":["money:tight"],"ex":[[["A","Front desk didn't have anybody on the ticket counter tonight. Just a sign."],["B","That's been two weeks now. They shifted whoever's left onto concession."],["A","So we're at the part where they stop replacing people."],["B","We're somewhere in that part, yeah. Get the setup warm, I brought my own pad."]],[["B","Skee-ball's dark on four lanes. They didn't even rope it, they just turned them off."],["A","Broken or saving power?"],["B","Didn't ask. Either answer would've ruined my night."]],[["A","I put forty in the machine tonight and I don't want to talk about whether that helps."],["B","It doesn't. Not at the scale they need."],["A","Right. Thanks."],["B","You asked me not to talk about it and then you looked at me."]],[["B","Rumor going round that the lease is up in spring."],["A","Who's saying that?"],["B","Somebody who heard it from somebody. So, nobody."],["A","Then it's spring until it isn't. Your side or mine?"]],[["A","They stopped fixing the second cabinet. That's the tell for me."],["B","Part's on order."],["A","Part's been on order since it broke. Nobody's ordering a part."],["B","I know. I just like saying it."]],[["B","Slow in here. Even for a weeknight."],["A","Eleven people. I counted through the curtain because I didn't want to know and then I counted."],["B","Eleven's a bracket."],["A","Eleven's a bracket. Sure."]],[["A","If this place goes, I don't think I keep playing."],["B","You'd play online for a month and quit."],["A","That's what I'm saying."],["B","I'd give it two months. But same ending, yeah."]],[["A","Should we be doing something? Like actually. A tournament, flyers, get numbers in the door."],["B","We ran that last year and eight people came, six of them ours."],["A","So we run a worse one."],["B","I'll ask about the projector. If they'll let us use it we can at least make it look like an event."]],[["B","You're quiet."],["A","Thinking about whether to renew the card. There's money on it and I keep not adding more."],["B","Add ten. If the place closes you're out ten dollars and if it doesn't you needed it anyway."],["A","That's the most reasonable thing anybody's said to me in here."]]]},"might-stop-coming":{"cat":"K","roles":{"A":["retiring"],"B":["rel:close"]},"world":[],"ex":[[["A","I might be done with this. Coming out here, I mean."],["B","Okay."],["A","That's all you've got?"],["B","You want me to argue with you next to the vending machines? Sit down, we'll play. Tell me again at close and I'll believe it."]],[["B","Your name's not on the sheet."],["A","It might not go on it again. Ever, I mean."],["B","Then come sit with me. I'm losing early anyway."],["A","Alright."]],[["A","Wednesdays stopped working for me, and Wednesdays is this."],["B","There's sets at my place some Sundays."],["A","Four people in a living room isn't the same and you know it isn't."],["B","No. It's free, though."]],[["B","Your stick's in a bag by the door."],["A","If I stop coming, I'd rather somebody here had it than it sat in my trunk."],["B","You could just take it back out of the bag."],["A","I could."]],[["B","Is it the game or is it this place?"],["A","Neither, which is the annoying part. I just don't want to get in the car."],["B","That's this place, then."],["A","Maybe."]],[["A","I might keep showing up and just not play. Run the bracket, sit in the back."],["B","You'd be asking somebody for a controller by the second week."],["A","First."],["B","So put your name down."]],[["A","It's a break. Not a quitting thing."],["B","People come back from breaks. You wouldn't."],["A","Probably not."]],[["A","After tonight I think I'm done coming out."],["B","You're still in the bracket."],["A","I know."],["B","Then be done at eleven. Not at eight."]],[["A","Don't say anything to the others yet. I haven't decided."],["B","You said might. That's all I heard."],["A","Good."],["B","Left side's open if you want to warm up."]],[["B","You keep looking at the door."],["A","Doing sums on the drive. Both directions."],["B","Come every other week. Nobody's counting."],["A","Yeah."]],[["B","You've stopped asking me for sets."],["A","Everybody in here got better and I'm exactly where I was. Might be time to stop."],["B","You're blocking the same stuff you blocked last month and people caught up to it. That's not stuck, that's lazy."],["A","Feels the same from where I'm sitting."]]]},"my-main-got-nerfed":{"cat":"F","roles":{"A":["main:nerfed"],"B":[]},"world":["patch:fresh"],"ex":[[["A","My sweep's minus now. Like, actually minus, not minus-if-you-guess-right."],["B","How minus."],["A","Enough that you get a full combo. I checked twice because I didn't believe it."],["B","So stop sweeping."]],[["B","You've been on the same screen in training for a while."],["A","Trying to find something that still connects after the launcher. Everything's a frame short."],["B","There's usually one route left. There always is."],["A","Yeah, and it does less damage than the one I got for free before."]],[["A","They took the invincibility off my reversal."],["B","Oh. So you just have to block now."],["A","I don't know how to do that."]],[["B","You switching?"],["A","No. I'll play it bad for a couple of months and then decide."],["B","That's what everyone says right before they pick the new top tier."],["A","Probably. Put me on the list anyway."]],[["A","Everyone keeps telling me it's still fine."],["B","Is it still fine?"],["A","It's fine. It's just fine in a way that means I have to work in neutral now instead of pressing a button and being right."],["B","Welcome. It's worse over here but the chairs are the same."]],[["B","I noticed you weren't running the oki you always do."],["A","Can't. The knockdown's shorter, they're up before I get there."],["B","By a lot?"],["A","By enough that I've been standing over people looking stupid all night."]],[["A","Give me one set where you don't say anything about the patch."],["B","Fine."],["A","Thank you."],["B","I'm going to be thinking it very loudly, though."]],[["B","You lost that one and didn't blame the patch. Growth."],["A","I dropped a confirm. That's mine, that has nothing to do with anyone."],["B","Say it into the room so everybody hears."],["A","No."]],[["A","Meter costs went up on everything I actually spend it on."],["B","So you sit on it."],["A","I sat on it the whole last game and died with a full bar."],["B","That's a real problem but it's also very funny."]],[["B","How's it feeling."],["A","Like driving a car where they moved the pedals two inches."],["B","You'll adjust."],["A","I know. I just liked where the pedals were."]],[["B","The range on your poke looks shorter."],["A","It is shorter. You've been walking into that spot all night like it's still dangerous."],["B","Don't tell me that."],["A","Too late, I want the games where you knew."]]]},"name-on-the-wall":{"cat":"L","roles":{"A":["won"],"B":["rel:familiar"]},"world":["arcade:established"],"ex":[[["B","They're gonna write your name up there in that marker that never comes off."],["A","Is that a warning?"],["B","It's information. Whoever's up there before you has been up there since I started coming."],["A","Then I'm not touching the board. Somebody else can spell it."]],[["A","Do I have to do anything? Sign something?"],["B","You tell the desk, they find the sheet, the sheet is somewhere under the ticket counter."],["A","So no."],["B","So eventually."]],[["B","Longest streak in the room's yours now. Officially, on the whiteboard, everything."],["A","My hands are shaking and I don't think it's the streak. I skipped lunch."],["B","There's popcorn."],["A","That's not lunch, that's a smell."]],[["B","You know that's the record."],["A","I know."],["B","You could look happier."],["A","I dropped the confirm in the last one and still won. That's the part I'm sitting with."]],[["A","Weird thing is I don't feel any different than after a normal set."],["B","Give it till you're in the car."],["A","That's what everyone keeps saying about everything here."]],[["B","They'll put you on the board and then someone's kid will draw on it."],["A","Fine by me."],["B","Last time it was a whole horse. Took up two names."]],[["A","Who do I even tell about this."],["B","Nobody. It gets around. It always gets around."],["A","So I just sit here."],["B","You sit there and you play whoever's next, same as any night."]],[["A","Does the old holder still come around?"],["B","Sometimes. Brings a kid to the skee-ball and looks in through the curtain for a minute."],["A","Should I say something if that happens?"],["B","Say hi. They'll bring it up before you do."]],[["B","Record on that machine, on that stick, with the button that sticks."],["A","It stuck twice. I heard it stick."],["B","Everyone heard it. Nobody's fixing it now."]],[["A","Feels like I should buy something. Is that a thing people do?"],["B","You can get a round of sodas and everyone will forget by the second set."],["A","Then that's what it is. Sodas."],["B","Get me the one that isn't flat."]]]},"nameless-regular":{"cat":"D","roles":{"A":["newcomer"],"B":["veteran"]},"world":[],"ex":[[["B","You're here every week and I still call you the person with the blue bag."],["A","That's fine. I've been calling you the guy who takes the left seat."],["B","I do take the left seat."],["A","I know. It's a good system."]],[["A","Someone put me on the bracket as \"new guy\" again."],["B","That's on me, I filled it out. What do you want on there instead?"],["A","My name would be a start."],["B","Right. Yeah. Say it slow, I'm going to write it in pen this time."]],[["B","Hey. Sorry. What am I calling you?"],["A","You've asked me that twice."],["B","And I'll ask a third time in two weeks, probably. It's not personal, I forget everyone."],["A","Weirdly that helps."]],[["A","You don't know my name."],["B","No."],["A","You've played me like six sets."],["B","And I know exactly what you do on wakeup. Priorities."]],[["B","Someone asked me who you were and I said you were pretty good."],["A","That's it? Just pretty good?"],["B","It was more than I had on most people."]],[["A","I keep meaning to introduce myself properly and then it's my turn on the stick."],["B","That's how it goes. I met the person on that back setup after about a month, and only because we both wanted the same chair."],["A","So I should fight someone for furniture."],["B","It worked. We're friends now."]],[["B","You've got a name, right?"],["A","Everybody's got a name."],["B","Not in here. There's a person who's been coming since before me and we all just call them by their character."],["A","I'd rather not go down that road."]],[["B","There's popcorn if you want it. Nobody knows whose money bought it."],["A","Mine. Two weeks ago. The machine was empty and nobody was looking at it."],["B","Huh."],["A","Yeah. Anyway, I'm still not sure anyone here knows my name."]],[["B","You should sign up for the thing on the whiteboard out front."],["A","They need a name for the sheet."],["B","They do."],["A","Then it's going to be a whole conversation at the desk and I've got next on this cabinet."]],[["A","How long before people learn who you are around here?"],["B","Depends. Beat somebody good in front of the whole room and it's instant."],["A","And if I don't?"],["B","Then you keep showing up until someone needs you to fill a bracket slot."]]]},"never-beaten-them":{"cat":"C","roles":{"A":["h2h:never-won"],"B":["h2h:dominant"]},"world":["arcade:established"],"ex":[[["A","Run it?"],["B","Yeah, I've got time."],["A","If I take a single game off you I'm going home immediately."],["B","Fine by me. Pick a side."]],[["B","You're closer than you were. That's not me being polite."],["A","Don't be nice about it."],["B","I'm not. You blocked the low three times in a row, which you never used to do."],["A","And still lost."]],[["A","What are you actually doing when I go for the throw?"],["B","Teching it."],["A","Every single time?"],["B","You only go for it right after you block something. So yes, every time."]],[["B","I'm not relaxed in these, if that's worth anything to you."],["A","It isn't."],["B","Last round comes up and my hands go stupid. I've dropped three punishes on you tonight."],["A","You still won the last round."]],[["A","I switched sides, switched sticks, switched characters."],["B","I noticed the character."],["A","And?"],["B","It's a better character. Neutral looked the same though."]],[["B","New people keep asking me if you've ever taken a set."],["A","What do you tell them?"],["B","I say we play a lot."],["A","That's worse than just saying no."]],[["A","One game. I get one game and I never bring it up again."],["B","You've said that before."],["A","I meant it every time."]],[["B","You're not losing neutral anymore. You're losing the confirm."],["A","So I'm dropping combos."],["B","You're dropping the one that would've ended the round. Everything else you hit clean."],["A","Great, so it's my hands and not my brain."]],[["A","Do you ever get bored of it?"],["B","Of playing you?"],["A","Of winning."],["B","No."]],[["B","Take the good stick, I don't need it."],["A","I don't want the good stick."],["B","Then take whichever side and I'll sit on the other one."],["A","Just sit down."]],[["A","People have started watching when it's us two."],["B","There's nothing else going on the projector, they'd watch anything."],["A","They didn't used to."],["B","Somebody moved the chairs closer. That's all that is."]]]},"new-cabinet-outside":{"cat":"H","roles":{"A":[],"B":[]},"world":["game:new"],"ex":[[["A","There's a new machine out by the pinball wall."],["B","Racing one? I saw them wheeling it in past the tables."],["A","It's a shooter. Two seats, one of the guns doesn't reload."],["B","So the good seat's on the left."]],[["B","You went out there for twenty minutes."],["A","The new cabinet takes cards now. No coins at all."],["B","And?"],["A","And I don't have a card. I watched a kid play it."]],[["A","New thing on the floor is loud. I can hear it through the curtain when nobody's playing over here."],["B","It's got the attract mode volume cranked. Somebody'll turn it down by next week."],["A","Nobody turned the pinball down."],["B","No."]],[["B","Did you try the new one yet, or are you just going to keep asking me about it."],["A","I'll try it when the line dies. It's all birthday party right now."],["B","It's always birthday party out there."],["A","Then I'll try it never. Put me on the list, I want the winner side."]],[["B","Somebody's been playing the new machine between games and coming back sweaty."],["A","That's me. It's a whole body thing, you stand on a pad."],["B","Then go do that after we finish, because you're breathing like a dog and it's putting me off."]],[["A","Kid out there beat the new cabinet's high score twice while I was waiting for a soda."],["B","Initials?"],["A","All three slots. Same three letters."],["B","Respect. Leave it alone."]],[["B","You're not going to like this. The new machine's plugged into the strip behind the curtain."],["A","Behind us? That's our strip."],["B","It's on the other side of the wall, same circuit. If it browns out mid-set we'll know why."],["A","Great. I'll take that as an excuse in advance."]],[["A","Whole point of coming in early is getting a setup to myself, and now I've got a new cabinet chiming at me every thirty seconds."],["B","Sit further from the curtain."],["A","There is no further. The room is the room."],["B","Then bring headphones like a normal person."]],[["A","They put the new game right where people line up for the ticket counter."],["B","So it's got a crowd on it all day whether anyone's playing or not."],["A","Attendant already asked twice if we could stop cutting through there."],["B","We come in the front doors like everybody else. I don't know who was cutting."]]]},"new-skin-opinions":{"cat":"E","roles":{"A":["settled"],"B":[]},"world":[],"ex":[[["A","New outfit for my character, and they made the sleeves white."],["B","That's a problem?"],["A","That arm is the poke I live on. I read my own spacing off the color of it."],["B","Wear the old one, then."]],[["B","You keep leaning in at the screen."],["A","The new outfit puts a glow on my super. Covers half the screen when it goes."],["B","It's your own super."],["A","I can't see you come out of it. I've been guessing at the oki all night."]],[["B","Everyone's calling that new outfit the best one they've put out."],["A","It clips through the arm on every sweep. Nobody's calling that."],["B","Nobody's looking at your arm."]],[["A","They finally gave my character something that isn't brown."],["B","There was a balance change in the same patch."],["A","I saw the outfit and quit reading."],["B","It's a nerf."]]]},"new-staff":{"cat":"H","roles":{"A":[],"B":[]},"world":["staff:new"],"ex":[[["A","New kid at concession charged me for a large."],["B","That's what a large costs."],["A","Sure. I'm just used to not being charged for one."],["B","Enjoy your medium."]],[["B","Someone came through the curtain and asked if we needed anything."],["A","And?"],["B","I said no and then thought about it for the rest of the set. We could use a fan in here."]],[["A","The new hire keeps opening the curtain all the way and letting the skee-ball in."],["B","Tell them. They'll stop."],["A","I don't want to be the guy who has notes on curtain technique in week one."],["B","Then live with the skee-ball."]],[["B","You know the new one at the prize counter? Asked me if I wanted to see the scooters."],["A","Did you?"],["B","I looked at them. They're nicer than I expected."]],[["A","Popcorn machine's on. Nobody turns that on."],["B","New staff doesn't know it's decorative."],["A","It's not decorative if it works."],["B","Go get some then, and stop reporting to me about it."]],[["B","I got asked for my name twice today by the same person."],["A","You should be flattered they tried a second time."],["B","I gave a different answer the second time. Not on purpose. Just said my tag."],["A","So now you work here under two names."]],[["B","Someone actually swept in here."],["A","That's the new employee. Enthusiastic phase."],["B","My chair doesn't stick to the floor anymore. I keep sliding when I lean."],["A","Sit up straight then."]],[["A","New staff came in to check the vending machine and stayed for the whole set."],["B","Say anything?"],["A","Asked what the bar was under our health. I told them it's meter. Then they left."],["B","That's about as far as anyone gets on the first try."]]]},"newcomer-is-good":{"cat":"D","roles":{"A":["newcomer","won"],"B":["veteran","lost"]},"world":[],"ex":[[["B","Where were you playing before this?"],["A","Online mostly. My cousin's setup before that."],["B","Online doesn't teach you to stop pressing after a knockdown. Somebody taught you that."],["A","I lose to people who press. Picked it up from the other side of it."]],[["A","Do I owe anything for those games? I wasn't sure how the machines work in here."],["B","It's free play behind the curtain. Can I ask you something."],["A","Go ahead."],["B","Were you sandbagging that first game."],["A","No. I didn't know what your character did yet."]],[["B","That low sweep I keep throwing out is minus. You knew that by the second game."],["A","I blocked it a lot."],["B","You blocked it and then took your turn. Everyone else here just blocks it."],["A","I'll keep taking my turn, then."]],[["A","Is there somebody here better than you I should play?"],["B","Ow."],["A","I meant it as a real question."],["B","I know you did. Two people. One of them's out by the skee-ball with a kid, so it might be a while."]],[["B","You dropped nothing that whole set. Not one confirm."],["A","I dropped one."],["B","When?"],["A","You were still getting up, so it didn't cost me."]],[["A","Sorry, I didn't mean to run it out like that."],["B","Don't do that."],["A","Okay."],["B","You won. Say you won."],["A","I won."]],[["B","Again. Right now, before I think about it."],["A","Give me a minute, my hands are still cold from outside."],["B","You beat me with cold hands."],["A","Which is why I'd like to warm them up."]],[["B","You sat on that character select screen so long I figured you'd never seen the game."],["A","I hadn't seen yours. Wanted to read what the moves do."],["B","You learned my character off the menu text."],["A","It's a short list."]],[["A","It's quieter in here than I thought it would be, with all the noise out front."],["B","The curtain does more than it looks like it does. Sit wherever."],["A","Do I still have next, or does that reset after a set?"],["B","You won, so it doesn't reset. That's the part I'm dealing with."]],[["B","You teched every throw in that set except one."],["A","You went for it in the same place every time. Right after the second hit gets blocked."],["B","Nobody's told me that."],["A","I'd stop telling you if we're playing again."]],[["A","Are you usually the one people have to get through here?"],["B","Depends who shows up. Tonight, yeah, and it went how it went."],["A","You had me in neutral most of it. The rounds weren't close after that, though."],["B","That's the whole problem in one sentence, thanks."]]]},"newer-players-better":{"cat":"K","roles":{"A":["veteran","lost"],"B":["veteran"]},"world":["arcade:established"],"ex":[[["A","They're not doing anything I don't understand. That's the part I keep coming back to."],["B","You understand it fine. They just do it faster than you can decide."],["A","Yeah."],["B","I've been sitting with that one for a while myself."]],[["B","Rough one."],["A","I got outspaced the whole way. Every poke I threw, there was already something out there waiting for it."],["B","That's the new crowd. They lab neutral like it's homework."],["A","We used to just play until we figured it out."]],[["A","When did the kids start blocking low?"],["B","Couple months back, I think. Somebody posted a chart."],["A","Great. My whole game was people not knowing that."]],[["B","You're taking that harder than usual."],["A","Because I wasn't close. Close I can work with. That wasn't close."],["B","You still had the second one."],["A","They gave me the second one. There's a difference and we both know it."]],[["A","Sit down a second. Am I slower or are they faster?"],["B","Both. Not by much, either direction."],["A","That's the worst possible answer."],["B","You asked me while I was eating."]],[["A","I dropped two confirms in that set. Two. I don't drop those."],["B","You didn't used to have to hit them under that much pressure."],["A","Nobody applied it like that before."],["B","Right. So it's not the hands."]],[["B","You going to run it back?"],["A","Not tonight. I'd like to go home thinking about it instead of losing to it again."],["B","Fair."],["A","Ask me in a week and I'll say something braver."]],[["A","There was a stretch where I knew every habit in this room."],["B","There were eight of us."],["A","Still counts."],["B","It counted then."]],[["B","What'd you learn?"],["A","That my oki doesn't scare anyone anymore. They just tech and keep their turn."],["B","So change what you do on the knockdown."],["A","I know. I'm allowed ten minutes of not wanting to."]],[["A","They apologised to me after. Told me it was a good set."],["B","It probably was, from where they were sitting."],["A","That's what got me."]],[["B","You've got that face on."],["A","I keep thinking I'm being read and I'm not. I'm just being beaten in neutral, over and over, on purpose."],["B","That's cleaner than being read, at least. Nothing personal in it."],["A","Doesn't feel cleaner."]],[["A","Be honest. Am I still one of the ones people want to play?"],["B","You're in the top handful."],["A","Out of how many?"],["B","More than there used to be. Which is the whole thing you're upset about, so."]]]},"nobody-read-notes":{"cat":"F","roles":{"A":[],"B":[]},"world":["patch:fresh"],"ex":[[["A","Did they touch anything I use?"],["B","I got about four lines in and then somebody wanted the second setup."],["A","So we're finding out live."],["B","We're finding out live."]],[["B","My throw range feels shorter."],["A","Or you're standing further away because you're worried about it being shorter."],["B","That's the kind of thing that's true and doesn't help me."]],[["A","Sweep's minus now. I ate a full combo for it twice."],["B","Was it minus before?"],["A","I don't actually know. Nobody ever punished it."]],[["B","Notes are on the screen out there if you want to squint at them."],["A","Read them to me."],["B","There's a whole paragraph about meter gain and then a list of numbers with no context. I'd rather just lose a few games and work it out."]],[["A","You blocked that. You've never blocked that."],["B","It came out slower. Or you're pressing it later. One of those."],["A","Great. Very useful."],["B","Run it again and I'll tell you which."]],[["B","Someone in the chair behind me swears they nerfed the dash."],["A","Did they say how?"],["B","No, they said it feels worse. Which I'm choosing to take seriously until I have better information."]],[["A","I labbed a combo for two weeks and it doesn't work anymore."],["B","That's rough. Which part drops?"],["A","The end. Or the middle. I've been too annoyed to check properly."]],[["B","Everything I do is still working, which worries me more than if it wasn't."],["A","Means they didn't look at you."],["B","They looked at me. There was a line with my name on it, I just didn't understand it."]],[["A","Hold on. Is my super cheaper?"],["B","You spent it twice in one round, so something's cheaper."],["A","I thought I was just playing well."]],[["B","We should both just read the notes."],["A","And then what, agree on something?"],["B","Fine. Next set."]],[["A","That thing you did on my wakeup. Is that new?"],["B","I've been doing it since before the patch, you just kept mashing through it."],["A","So it's new to me."],["B","Sure. Congratulations on the patch."]],[["B","Half the room's convinced the patch broke their character and the other half hasn't noticed it happened."],["A","Which half are you in?"],["B","I noticed the download."]]]},"not-about-the-game":{"cat":"J","roles":{"A":["rel:close"],"B":["rel:close"]},"world":[],"ex":[[["B","You eat yet?"],["A","I had a granola bar in the car around four."],["B","That's not eating, that's stalling."],["A","There's a place by my work that does a chicken thing. I'll go after. Probably."]],[["A","You looked wrecked when you came in."],["B","Slept maybe three hours. Upstairs neighbor's got a dog with opinions."],["A","Have you talked to them?"],["B","I've composed several very reasonable notes and slid none of them under any door."]],[["B","You still doing the running?"],["A","Twice last week. Knee's been weird."],["B","Weird how."],["A","Clicks. Doesn't hurt. I've decided that's fine."]],[["A","I put a deposit down on the apartment on Culver."],["B","The one with no dishwasher."],["A","It has a window that opens and a landlord who answers the phone. I'll wash a plate."],["B","I've got a truck the second weekend of the month if you need it."]],[["B","Did you ever hear back about the job?"],["A","They said two weeks, then went dark. It's been closer to a month."],["B","That's a no with extra steps."],["A","Yeah. My current boss doesn't know I applied, so at least that stayed clean."]],[["A","You're wearing the good jacket."],["B","I had a funeral this morning. Didn't feel like going home to change."],["A","Anyone I'd know?"],["B","No. Guy from my old apartment building. Nice guy, kept a bird."]],[["B","You get the wedding invite?"],["A","Yeah, and I've got the RSVP card on my counter under a stack of mail, aging."],["B","You're going. I already put you on my table."],["A","You did what."],["B","Fill out the card."]]]},"offering-to-help":{"cat":"I","roles":{"A":["humor:earnest","veteran"],"B":[]},"world":["money:tight"],"ex":[[["A","If the entry fees aren't covering the room anymore, I'll pay double. Nobody has to know."],["B","That's not how the pot works."],["A","Then don't put it in the pot. Put it in the till."],["B","I'll ask. They might say no just to keep it simple."]],[["B","Sign-ups took forty minutes because one person was doing everything."],["A","Hand me the clipboard next week. I'll have people seated before you finish setting up the projector."],["B","You'd miss half your own matches."],["A","I'd play last. It's fine, I like watching the early rounds anyway."]],[["A","You don't have to keep buying the pizzas out of pocket."],["B","Nobody else was going to."],["A","Split it with me. Every week, half, no discussion."],["B","Fine. But you're picking it up, I'm tired of the drive."]],[["A","I'll sweep the room after. Don't argue, you've been here since it opened."],["B","There's a broom behind the vending machines."],["A","I know. I put it there."]],[["B","They're talking about closing the room off on weeknights. Says it costs more to light than it brings in."],["A","Then I'll bring people in on weeknights. I know maybe eight who'd come Tuesdays if somebody actually told them there was a thing."],["B","Eight isn't much."],["A","It's eight more than zero and I'll text every one of them."]],[["A","You've been teaching that new kid for an hour and losing money doing it. Let me take a turn."],["B","You'd have to slow all the way down."],["A","I'm slow already. Go eat something."],["B","Twenty minutes. Don't teach them my stuff."]],[["B","Entry's five and I've got three."],["A","I'll cover the two. Pay me back whenever, or don't."],["B","I'll pay you back."],["A","I know. Go sign up before they close the bracket."]],[["B","Turnout's been bad enough that they're counting heads at the door now."],["A","I'll be here every week regardless. You can count me twice if it helps."],["B","It won't."],["A","Then count me once and I'll bring somebody."]]]},"old-set-dredged":{"cat":"C","roles":{"A":["rel:close"],"B":["rel:close"]},"world":["arcade:established"],"ex":[[["A","That old bracket sheet is still taped up by the vending machine."],["B","I know exactly which line you're looking at."],["A","I didn't say anything."],["B","You walked over there and came back grinning."]],[["B","You still owe me for that long set on the left setup."],["A","Owe you? You won it."],["B","I won it and then you spent a week telling people the pad was drifting."],["A","It was drifting."]],[["A","Someone asked me tonight who's beaten you worst in here."],["B","And you gave them your own name."],["A","I described the whole set. They only wanted a name."],["B","Nobody ever wants the whole set."]],[["B","You had me down to nothing that one time and you put the controller down early."],["A","I didn't put it down. I exhaled."],["B","It was on your knee."],["A","My hands were still on it."]],[["A","You don't remember it at all?"],["B","I remember losing. I don't remember whatever detail you're about to make me remember."],["A","You switched character halfway. Never done it since, not once."],["B","Then it worked out."]],[["B","Two people brought up that bracket set tonight. Both of them new. Somebody's been telling it."],["A","It's a good story."],["B","It's the worst set I've played in this building."],["A","Both of those are true."]],[["A","Last round of that set, you sat on full meter and never spent a bar."],["B","I've stopped taking questions about that one."],["A","Wasn't a question."]],[["B","You've got the face you get before you drag up something from years back."],["A","It's not years. It was last spring."],["B","Then it's the spring one, and no."]],[["A","Kid out on the floor plays exactly like you did when I first beat you."],["B","You didn't beat me first. I took the first game, then you took the set."],["A","Sure."],["B","Not sure. That's how it went and you know it."]],[["A","That set's most of the reason I kept coming back here."],["B","The one where I got 0-2'd in about the time it takes to sit down?"],["A","Yeah."],["B","Keep it, then. Just don't say it near the chairs when they're full."]],[["B","I still go back to that finals set. Not the loss. The round I spent blocking low every single time."],["A","I said at the time you were guessing low."],["B","You said it after."],["A","I said it after because while it was happening it was working."]],[["A","The set where the projector died mid-game. You remember what the score was."],["B","We agreed we weren't relitigating that."],["A","I'm not. I'm remembering out loud."],["B","That's how the relitigating starts."]]]},"one-dumb-thing":{"cat":"A","roles":{"A":["lost"],"B":["won"]},"world":[],"ex":[[["A","You did the same low sweep every time I stood up. Every single time."],["B","Yeah."],["A","You're not even going to pretend it was a read."],["B","It was a read the first time. After that I was just pressing it."]],[["B","I want to say something about that set but I don't have anything to say."],["A","One button. You found one button."],["B","It kept working. What am I supposed to do, stop?"],["A","Blocking low is apparently beyond me, so no."]],[["A","How many times did you go for the throw in that last one?"],["B","I stopped counting. You never teched once."],["A","I was waiting for you to mix it up."],["B","That's the part I was counting on."]],[["B","That wasn't a good set for me. I just did the jab into the same combo until the timer ran out."],["A","You don't have to soften it."],["B","I'm not softening it, I'm telling you I didn't learn anything either."]],[["A","At some point you have to get bored of that."],["B","You'd think. I kept waiting to get bored and then I'd win another round."],["A","I'll have an answer next time."],["B","Then I'll have to actually play. Neither of us wants that."]],[["B","Do you want to know what I was doing or would that make it worse?"],["A","I know what you were doing. Long poke, back up, long poke."],["B","And?"],["A","And I walked into it about nine times, so I don't get to complain."]],[["A","You never once changed it up."],["B","Why would I. You were jumping at the same range every round and the anti-air just sits there."],["A","I thought I was varying it."],["B","From where I was standing it looked pretty consistent."]],[["B","Feels cheap winning like that."],["A","It's not cheap, it's minus nothing. There's no punish. I checked in training mode last week."],["B","You checked and then still tried to punish it?"],["A","Hope, mostly."]],[["A","Same overhead, over and over. I want it on record that I noticed."],["B","Noticing isn't blocking."],["A","Give me a minute, I'm building up to blocking."]],[["B","I'd like to say there was a plan."],["A","There wasn't. You dashed in and pressed the same button, and it beat everything I had."],["B","Beat everything you had is a plan by some definitions."],["A","Not by mine."]],[["B","You know I only did one thing that whole set."],["A","I do know. I was there for all of it."],["B","Sorry."],["A","Don't be sorry, be sorry next set when I'm ready for it."]]]},"one-has-to-leave":{"cat":"B","roles":{"A":[],"B":[]},"world":[],"ex":[[["A","One more."],["B","I've got maybe six minutes before the parking thing turns into a real problem."],["A","Six minutes is a set."],["B","Six minutes is a set if neither of us does anything interesting."]],[["B","You're picking up your bag while asking to run it back, which is confusing me."],["A","I'm doing both. I want to keep playing and I have to be somewhere at eight."],["B","Then go. It'll be the same tomorrow, we'll both still be bad at the same spots."]],[["A","Was that the last one? Say it's not."],["B","It's the last one. I'm on the early shift."],["A","You could just not sleep."],["B","Tried that version of my life already."]],[["B","I want a rematch so badly it's making me stupid."],["A","Then sit down."],["B","Somebody's waiting in the car for me. Actually waiting, not the fake kind."],["A","Go. I'll hold your spot in my head."]],[["A","I finally figured out what you're doing after the knockdown and now you're standing up."],["B","Bad timing for me too. Write it down or you'll lose it."],["A","I won't lose it. I've been eating it for twenty minutes."]],[["B","How long's the wait on this station right now?"],["A","Four deep. So, a while."],["B","Then that's me done. I can't be here past nine and I'm not spending my last half hour standing up."],["A","Next time get here before the after-work crowd."]],[["B","Last game had me actually thinking. Nothing's felt like that in weeks."],["A","So don't stop."],["B","The train's every forty minutes after this one and I am not doing that again."]],[["B","You leaving?"],["A","Have to. My kid's thing is in the morning and I'm the one driving."],["B","Fine. But you're not allowed to tell people you took that set two-nothing, because you didn't, it was closer than that."],["A","I'll describe it accurately and it'll still sound bad for you."]],[["A","That last one, where I switched up the pressure. Did you clock it or did I get lucky?"],["B","Clocked it late. I'd have had it in another game or two."],["A","Guess we don't find out. I'm parked in a two-hour spot and I've been here three."]],[["B","Sit down, one more, I'll be quick about it."],["A","You said that twenty minutes ago and I stayed."],["B","And?"],["A","And now I'm eating dinner at eleven again. No."]]]},"out-early-still-here":{"cat":"G","roles":{"A":["lost","mood:low"],"B":[]},"world":["tournament:today"],"ex":[[["A","I'm not leaving, before you ask."],["B","Nobody asked. There's still four hours of bracket."],["A","Right. I just wanted it said out loud so I stop thinking about the parking lot."]],[["B","You want popcorn? I'm going anyway."],["A","No."],["B","I'll get you some."],["A","Fine. Not the bottom of the machine, it's all the old stuff."]],[["A","Who knocked me out, do you know? I didn't catch the name on the sheet."],["B","Nobody knows that name yet. First time here, I think."],["A","Great. So I'm the answer to a trivia question."],["B","You're the answer to a trivia question nobody's going to ask."]],[["B","Sit down, you've been standing behind that chair for twenty minutes."],["A","If I sit down I'm here for the rest of the day."],["B","You're here for the rest of the day."]],[["A","I dropped the same confirm three times. Three. In one set."],["B","Was it the one off the low, or the other one?"],["A","Off the low. Every time."],["B","Then go put twenty minutes into it in the corner setup. Winners isn't even done, you've got the time."]],[["A","Anyone need a body for casuals? I've got nothing else going on today."],["B","That's a grim way to offer."],["A","It's an accurate way to offer."],["B","Take that station, then. The people on it are up in bracket soon anyway."]],[["B","You're allowed to be annoyed. You've just been annoyed at me specifically for ten minutes."],["A","You were the nearest thing."],["B","Be annoyed at the vending machine. It ate a dollar off me earlier and it can take it."]],[["A","Can I hold your controller for the next one? I want to feel buttons."],["B","I'm on in two matches."],["A","Two matches is ages."],["B","Take it. Don't clean it, don't adjust anything, don't be helpful."]],[["B","You watching, or just facing the screen?"],["A","Facing the screen."],["B","Face it a bit harder, that's your bracket. Whoever wins is who ended you."],["A","Then I hope it goes long and hurts."]],[["A","Did I look tilted out there? Be honest."],["B","You were mashing after the second knockdown, so yeah."],["A","I thought I was being patient."],["B","You were being patient with your face."]],[["B","Two-and-out is a long drive for what you paid at the door."],["A","I know what I paid at the door."],["B","Then stay for the top eight and get your money's worth off the projector. Popcorn's free after the first bracket clears."],["A","It's free because it's terrible."]],[["A","I keep replaying the last round in my head and I still don't know what I was supposed to press."],["B","Nothing. You were minus, they knew, that's it."],["A","That's less comforting than you think."],["B","Wasn't aiming for comforting."]]]},"outsider-turns-up":{"cat":"L","roles":{"A":["newcomer","rel:stranger"],"B":["rel:stranger"]},"world":["stream:growing"],"ex":[[["A","Chat spends the entire stream saying one character is broken. Is that a real argument in here or just online?"],["B","Two people in here think so. They both play that character."],["A","That's usually how it goes."]],[["A","I watched something like six hours of the channel last week and never once checked where it was. Turns out it's twenty minutes from my place."],["B","That's most people's story now. Put your name on the sheet by the popcorn machine if you want games."],["A","There's a sheet?"],["B","There's a sheet. It's a receipt with names on it, but it counts."]],[["B","You're new. You came in and looked at the projector before you looked at any of the setups."],["A","The screen's the only part I've seen. I wasn't sure the rest of it was an actual room."],["B","It's a room. It's smaller than it looks on stream."]],[["A","I walked past the prize counter three separate times looking for the entrance to this."],["B","It's the curtains. Everybody misses the curtains."],["A","I thought that was storage."],["B","There's a mop back there, so you weren't far off."]],[["A","Is the person with the really long forward poke here? I don't know anyone's name, I've only got the stream."],["B","That's about four people."],["A","Ah."],["B","They'll all be in later. You'll sort it out."]],[["B","Port's under the lip on the left, if you brought your own controller."],["A","How did you know I brought one."],["B","Bag's the wrong shape for anything else."],["A","Left side. Got it."]],[["A","There were four hundred people watching the last set on the channel. Did anyone in here know that?"],["B","Somebody said a number out loud at the time. I don't think it landed."],["A","It said four hundred."],["B","Then it was four hundred."]],[["A","If I get taken apart on camera, does that stay up somewhere?"],["B","It saves, yeah. Nobody watches the archives except people looking for their own sets."],["A","That's better than I was expecting."]],[["A","Whoever does the commentary makes the neutral sound completely readable. I sat down here and it isn't."],["B","They're guessing too. They're just guessing in a confident voice."],["A","Do you do it?"],["B","When the mic's free and I'm not playing."]],[["B","You waiting on something to start?"],["A","The stream made it look like there's a schedule."],["B","Bracket goes up around nine, on the whiteboard out front. Next to the birthday specials."],["A","I'll go stand near it."]],[["A","I'm fairly sure I've watched you play. Red controller?"],["B","Could be. There's five red ones in here, somebody found a deal on them."],["A","So that's a no."],["B","That's a maybe."]],[["B","You keep looking at that wall."],["A","There's skee-ball coming through it. On the stream I assumed that was a sound in the game."],["B","Machine's right on the other side. You stop hearing it."]]]},"passion-bottoming-out":{"cat":"K","roles":{"A":["passion:low"],"B":["rel:familiar"]},"world":[],"ex":[[["B","You want the winner side or you sitting this one out?"],["A","Sitting. I'll watch."],["B","You watched the last three too."],["A","Yeah, it's not bad. Popcorn's fresh for once."]],[["A","I haven't opened training mode in weeks. Not once."],["B","Does it show?"],["A","You tell me, you've been beating me on the same low."],["B","I'd have stopped using it if you blocked it."]],[["B","You're mashing a lot more than you used to."],["A","Feels better than thinking about it."],["B","It works, sometimes. That's the annoying part."]],[["A","Can I ask you something and you don't make it a whole thing."],["B","Depends."],["A","Do you still get nervous before a set? Like at all?"],["B","Little bit. Not every time. Why, you not?"]],[["B","Two more?"],["A","I'd rather get a slushie, honestly."],["B","Get me one. Then two more."]],[["A","I keep dropping the same confirm I've had for months."],["B","Hands cold?"],["A","No, I just don't care whether it comes out."],["B","That'll do it more than cold hands will."]],[["B","You left before finals last week."],["A","Had an early morning."],["B","Sure. Just so you know, that set went long and nobody could hear the projector over skee-ball anyway."],["A","Then I picked a good week."]],[["A","There was a patch and I didn't read the notes."],["B","Anything change for you?"],["A","No idea. Somebody said one of my buttons is minus now."],["B","It is. You've been getting punished for it all night."]],[["B","Your bag's still zipped up. You don't want to play at all."],["A","I wanted to come. Playing's a separate question."],["B","Fine. Sit there and tell me what I'm doing wrong then."],["A","You're standing too close when they wake up. Same as always."]]]},"patch-aimed-at-me":{"cat":"F","roles":{"A":["main:nerfed","humor:clowning"],"B":[]},"world":["patch:fresh"],"ex":[[["A","They took two frames off my sweep. Two. Somebody sat down and decided that about me specifically."],["B","You don't think they know your name."],["A","I think there's a whiteboard somewhere with my name on it."],["B","There's a whiteboard out front with the wing deal on it. That's the extent of it."]],[["B","How bad is it actually."],["A","My best button is minus now. Minus. On a normal."],["B","So block less."],["A","That's not, you can't just, okay. Sure. I'll block less."]],[["A","Notice what they didn't touch. Everything you press. Untouched. Pristine."],["B","They nerfed my throw range."],["A","Nobody uses your throw."],["B","I use my throw."]],[["A","I've written a letter."],["B","To who."],["A","Haven't worked that part out. It's mostly feelings right now."]],[["B","You've said the word patch nine times since you walked in."],["A","Because I keep dropping the combo I've done for months. It just ends now. Halfway through, it ends."],["B","Yeah, they cut the recovery. You have to route around it."],["A","I don't want to route around it. I want it back."]],[["A","Some guy watched me play, went home, and did this."],["B","Or they looked at numbers."],["A","Numbers I generated. Personally. With my hands."]],[["B","Play someone else for a week."],["A","That's what they want."],["B","That's what I want. I'm the one standing here."],["A","You're part of it now, is what I'm hearing."]],[["A","Grief has stages and I'm going to be in the angry one for a while, so."],["B","Noted. Do you still want the set."],["A","Obviously I want the set."]],[["B","You lost that one to a throw, not to a patch."],["A","I lost it because my oki doesn't exist anymore, so you got to stand up like a normal person."],["B","That's true, actually."],["A","Don't agree with me, it makes it worse."]],[["A","Everyone else got small stuff. Little tuning. Mine reads like an obituary."],["B","It's four lines long."],["A","Four lines is a lot of lines when they're all about you."],["B","They're about a character."]],[["B","You going to keep bringing this up all night?"],["A","Only until someone acknowledges what happened to me."],["B","Something happened to you. Terrible. Put in your coin."]],[["A","I labbed for two hours and found nothing. There's no tech. They closed it."],["B","You checked the wall combo?"],["A","First thing. Doesn't confirm anymore. I sat there watching it not confirm."],["B","Alright. So we're both figuring out what you do now."]]]},"people-are-watching":{"cat":"L","roles":{"A":[],"B":[]},"world":["stream:growing"],"ex":[[["A","Forty people watching. Forty."],["B","That's more than have ever been in this building at once."],["A","Do I sit different? I feel like I'm sitting different."],["B","You're sitting like someone's about to take your picture. Just play."]],[["B","Somebody in the chat said my spacing was loose."],["A","Was it?"],["B","Yeah. That's the annoying part."]],[["A","Can they hear us?"],["B","The mic's clipped to the chair by the popcorn machine, so they can hear the popcorn machine."],["A","So they can hear us."],["B","They heard you last week. Somebody clipped it."]],[["B","You've got a rooting section now. Two of them are asking when you're on again."],["A","Tell them I don't know. I show up when I show up."],["B","That's a terrible answer and I'm typing it word for word."]],[["A","I dropped the confirm and heard the room go quiet, and then I remembered it goes out to actual people."],["B","Nobody out there remembers a dropped combo past the next game."],["A","You do."],["B","I'm not people, I'm sitting right here."]],[["B","Someone in another city is learning my whole gameplan off the archive."],["A","Good. Then they'll show up and lose to something new."],["B","Or they'll show up with the answer already written down."],["A","Then you get better. That's the deal you signed when you let them point a camera at you."]],[["A","The overlay's got my name spelled wrong."],["B","For how long?"],["A","Since it went up. Nobody said anything."],["B","Leave it. You've got viewers under that spelling now."]],[["B","Chat wants to know why we don't run the setups closer to the screen."],["A","Because then you're staring into a projector all night and you can't see the low hits."],["B","That's a reasonable answer. I'm going to give them a worse one."]],[["A","You go quiet when the camera's on. I've noticed."],["B","I go quiet when I'm losing. The camera's a coincidence."],["A","Sure."]],[["A","You want to run this set on stream or off?"],["B","On. If I lose I want it recorded so I'll actually go lab the reason."],["A","That's the most functional thing anybody's said in here."],["B","It's not, I just don't trust myself to remember."]],[["B","Someone asked if the arcade sells shirts."],["A","Does it?"],["B","There's a bin by the prize counter with three in it. All extra small."],["A","Tell them we're sold out of everything else."]]]},"pocket-failed":{"cat":"E","roles":{"A":["pocket-used","lost"],"B":["won"]},"world":[],"ex":[[["A","That was the plan. The plan was fine, I want that on record."],["B","Plan was fine. You were pressing at the same range you press with your main, and that character's arms are shorter."],["A","Yeah. Whiffing from my normal spot the whole time."]],[["B","When did you pick that up?"],["A","This morning. Maybe an hour in training mode."],["B","It worked for one game and then it didn't, which is worse, because after that I stopped respecting anything you did."],["A","Noted."]],[["A","The combos were there in the lab."],["B","Standing still they always are."],["A","Dropped the confirm three times. All three in rounds I was winning."]],[["B","Is that a project or was that a one-day thing."],["A","Ask me tomorrow."],["B","I'm here another hour if you want to bring the main back out."],["A","Give me a minute at the vending machine first."]],[["A","How were you on the low so fast?"],["B","You only ever used it off a knockdown. Never anywhere else."],["A","It's the only thing I know how to do with the character."],["B","Then oki was easy. I only had two things to look at."]],[["A","It's a better matchup on paper."],["B","Probably true. You still have to press the buttons at the right time."],["A","I'll get there."]],[["B","You know that character has a reversal that doesn't cost meter."],["A","Does it."],["B","You sat and blocked in about four spots where you could've just pressed it."],["A","Okay. Something to do next time."]],[["A","Two games in I wanted my main back and didn't want to say it out loud."],["B","You could've said it. I wasn't going to hold it over you."],["A","The whole point was to sit in it. So I sat in it."]],[["A","That was rough to be inside of."],["B","It was a brand new character against somebody who's played a lot of sets. It wasn't rough, it was just quick."],["A","Quicker than I planned for."]],[["B","Did you get anything out of it?"],["A","The walk speed is a lie."],["B","Slower than it looks?"],["A","It looks slow. It's worse than that."]],[["A","New character, same result."],["B","Different result. You lost neutral tonight. Usually you lose to the mix-up."],["A","Fine. I'd rather lose neutral."]],[["B","Keep it for the matchup your main actually struggles in, {t}. Not against me."],["A","You are the matchup my main struggles in."],["B","Then go lab it properly and come back."],["A","Two weeks. Don't pick anyone new in the meantime."]]]},"pocket-worked":{"cat":"E","roles":{"A":["pocket-used","won"],"B":["lost"]},"world":[],"ex":[[["B","When did you pick that up?"],["A","I've had it a while. Never needed it against anyone else."],["B","So it's for me specifically."],["A","It's for people who block low forever, and that's you."]],[["A","I was going to switch back after the first one."],["B","Why didn't you."],["A","It kept working."]],[["B","That whole set I was waiting for a reversal that character doesn't have."],["A","I know. You kept giving me the turn back for free."],["B","Run it again, I'll respect nothing."],["A","That's the other way to lose to it, but sure."]],[["A","Don't read too much into it. I hit maybe two of the combos right."],["B","You didn't need the combos. I was mashing into a button I've never seen before."],["A","It's not even that good of a button."],["B","It's good enough at this table."]],[["B","How long have you been sitting on that."],["A","Since I got bored in training mode one night."],["B","Great. So my whole afternoon is somebody else's boredom."]],[["A","You want to keep going or you want to go get food."],["B","Food. I'm not learning that matchup on an empty stomach."],["A","There's nothing to learn, honestly. Just block the overhead."],["B","Say that again after I've eaten and I'll pretend to hear it."]],[["B","You didn't even do anything different. Same habits, different body."],["A","Same habits work better when you don't know what's minus."],["B","I was punishing air the entire time."],["A","Yeah, I noticed around the second game and started doing it more."]],[["A","Can I be honest about something."],["B","No."],["A","I don't know that character's throw range at all. I was guessing."],["B","I'd rather not have known that."]],[["B","Are you switching for the rest of the night?"],["A","Depends who's in line."],["B","So it's a me thing."],["A","It's a whoever-keeps-walking-into-that-poke thing."]],[["A","I felt bad picking it, if that helps."],["B","It doesn't."],["A","Didn't think so. I'll go back to the main one next set."],["B","Don't do me favors, just play worse naturally."]],[["B","That thing has a low that fast?"],["A","It's not that fast. You were standing up to press."],["B","Because everything else looked high."],["A","That's sort of the whole idea, yeah."]],[["A","You okay? You got real quiet after the switch."],["B","I was trying to figure out what I was allowed to do."],["A","Anything after the sweep. There's a gap there, it's huge."],["B","Cool. Telling me now."]]]},"projector-playing-up":{"cat":"H","roles":{"A":[],"B":[]},"world":[],"ex":[[["A","Everything on screen is green."],["B","Wiggle the cable where it goes into the back. Not the projector end, the other one."],["A","It's blue now."],["B","Keep going."]],[["B","Stream's frozen on the loading screen. Has been for a while."],["A","Is anyone actually watching it?"],["B","Four people. One of them is me, from my phone, in this room."]],[["A","Projector bulb's going. That yellow's not supposed to be yellow."],["B","They know. There's a work order in somewhere."],["A","How long has there been a work order in."],["B","I'd rather not find out."]],[["B","Audio's about a second behind the picture, so I'm hearing you lose before I see it."],["A","Turn the speakers off, then."],["B","And listen to skee-ball through the curtain instead?"],["A","Yeah."]],[["A","Can we just play on the cabinet screen and skip the projector for tonight?"],["B","Then nobody in the chairs can see anything."],["A","There's two people in the chairs and they're both on their phones."],["B","Fine, but I'm not the one telling them."]],[["B","Whatever's on the screen right now, it isn't us."],["A","That's the setup by the vending machine. Someone swapped the inputs."],["B","So somewhere out there people are watching two guys warm up in silence."],["A","Better than watching me get opened up on wake-up."]],[["A","Every time the popcorn machine kicks on, the picture dips."],["B","It's the same outlet. It's been the same outlet since they set the room up."],["A","Nobody's moved it?"],["B","People like the popcorn."]],[["B","You can keep resetting it, or we can start the set and let it fix itself."],["A","It doesn't fix itself. It just stops bothering me."],["B","That's the same outcome."]],[["B","Stream's down again, so nothing that happens for the next while counts."],["A","It counts to me."],["B","It counted to you last time too and you still lost."],["A","Different reasons."]],[["A","How long do we wait for the stream before we just run the bracket?"],["B","We ran it without the stream last time and nobody complained."],["A","Two people complained."],["B","Neither of them entered. Start it."]],[["B","There's a big dead patch in the middle of the projection now. Right where the health bars sit."],["A","So we can see everything except who's winning."],["B","You'll know. Trust me, you'll know."],["A","I'll sit closer to the screen."]]]},"proper-goodbye":{"cat":"K","roles":{"A":["retiring"],"B":["rel:close"]},"world":["arcade:established"],"ex":[[["A","I'm giving you the stick. Don't be weird about it."],["B","The stick you complained about every single week?"],["A","It's fine now. I resoldered the button that was doubling."],["B","So you fix it and then you go."]],[["B","Last night, then."],["A","Last night here. I'll probably still play at home, badly, and not tell you about it."],["B","You'll tell me."],["A","I'll tell you."]],[["A","Set me up one more time. Not first-to-anything. Just play until I'm tired."],["B","You get tired in about twenty minutes these days."],["A","Then it's twenty minutes."]],[["B","You want to do this behind the curtain or out by the tables where everyone can hear?"],["A","No speech. I'll shake some hands and buy popcorn for whoever's left."],["B","Machine's been empty since this afternoon."],["A","Handshakes, then."]],[["A","Work's moving me and I'm not going to pretend about weekend drives."],["B","People say that. Then they say it again in three months, from that chair."],["A","Which is why I'm only saying it the once."],["B","Okay."]],[["A","My notes are in the folder behind the projector. The matchup pages are still good."],["B","You wrote things down? In all this time you never said you wrote things down."],["A","You'd have read them and used them on me."]],[["B","This place went through a bad stretch and you're one of the reasons anybody still comes."],["A","Don't."],["B","I'm doing it now, while you're standing there and can't leave."],["A","I can leave. I have a car."]],[["A","Take my card off the desk, I'm never spending the tickets."],["B","How many are on it?"],["A","A small stuffed animal, or most of a scooter."],["B","Animal."]],[["B","Anything you never showed anybody?"],["A","There's a low in my oki you never once blocked. I quit using it because I felt bad."],["B","You felt bad."],["A","Around the third time, yeah."]],[["A","Don't write retired next to my name on the board. Just take it off the ladder."],["B","Somebody's going to ask where you went."],["A","Then tell them."]],[["B","Who am I supposed to play now."],["A","There are four people in this room better than me."],["B","That's not what I asked."],["A","I know."]],[["A","The chairs. Somebody has to stack them at close, and it's been me for years."],["B","I know it's been you. I've watched you do it while I sat in one."],["A","So that's the handover. Stack the chairs."],["B","Fine. Show me how you do the back row, because you always end up with two left over."]]]},"queue-for-cabinets":{"cat":"H","roles":{"A":[],"B":[]},"world":["arcade:packed"],"ex":[[["A","How deep is the list?"],["B","Eleven names, and two of them are the same person written twice."],["A","Which two?"],["B","I'll let them explain it when we get there."]],[["A","You want to split a queue slot? You take the first set, I take whoever's after."],["B","That's not a thing. That's just you skipping."],["A","It's a thing if nobody complains."],["B","Someone always complains. Usually the person holding the pen."]],[["B","Standing room only back here. Somebody moved the chairs."],["A","They're stacked by the vending machine. Nobody wanted to be the one to unstack them."],["B","I'll do it if you hold my spot."],["A","Go. If you're not back in five I'm putting my name over yours."]],[["A","Two setups and fourteen people, and one of the setups has a stick that drifts left."],["B","Then thirteen people, because I'm not playing on that one."],["A","You'll play on it when you're up and you know it."],["B","I'll play on it and I'll be loud about it."]],[["B","Anyone actually running the list or are we doing it by memory?"],["A","Memory. It's been holding up better than you'd think."],["B","So who's after the two playing now?"],["A","That's the part memory's not holding up on."]],[["A","You're up in two, by the way."],["B","I was hoping for longer. I haven't warmed up at all."],["A","Nobody's getting warmed up tonight. There's no cabinet to warm up on."],["B","Then I'll lose cold and be back in the queue in five minutes."]],[["B","I keep getting drifted out into the lobby every time someone walks past."],["A","Stand behind the chairs. People don't push through chairs."],["B","Then I can't see the screen."],["A","You've got a fifteen-minute wait to decide which one matters more."]],[["A","Long queue's actually good for my play. I get to sit down and think about what I did wrong."],["B","You've been sitting a while."],["A","I've stopped thinking about what I did wrong. I'm thinking about food now."],["B","Get me a thing of fries and I'll hold your spot."]],[["A","If you lose, do you go to the back or is winner-stays actually being enforced tonight?"],["B","Winner stays. Back of the list if you drop it."],["A","That's brutal with this many people."],["B","It's brutal for you. I don't plan on losing until the room clears out."]]]},"quiet-wing-taking":{"cat":"J","roles":{"A":["veteran"],"B":["newcomer"]},"world":[],"ex":[[["B","Am I in the way? People keep reaching over me."],["A","That's the vending machine. Everybody hits it between sets. Slide down a chair."],["B","This one?"],["A","That one's fine. Nothing behind you there."]],[["A","You keep standing up when you lose. You don't have to."],["B","I thought it was winner stays."],["A","Winner stays, loser can run it back if there's nobody waiting. Nobody's waiting."],["B","Then run it back."]],[["A","Setup's yours, I'm getting a drink. Dummy's already set to block."],["B","I don't want to mess with your settings."],["A","You can't. It forgets everything the second you back out."],["B","Fine. I'll be off it when you're back."]],[["B","You knew the throw was coming. Every single time."],["A","You back up twice and then go for it. Every knockdown."],["B","Twice."],["A","Twice. Try it on the first sometimes."]],[["A","Names go on the board before eight or you're not in the bracket."],["B","I wasn't going to enter. I've been playing like two weeks."],["A","Board's by the curtain. I'm not writing it for you."],["B","Spelled how it sounds, then."]],[["B","Sorry, that wasn't much of a set for you."],["A","Quit doing that."],["B","Doing what?"],["A","The apology after. Say good games, pick again."]],[["B","I think I picked wrong. Nothing I try works."],["A","Give it another week before you drop them."],["B","And if it still doesn't work?"],["A","Then drop them, and learn a whole new set of buttons from scratch. Your call."]],[["A","Eat before seven. After that you're behind a birthday party."],["B","I was going to skip it."],["A","Don't. You'll be shaky by the third set and you'll blame the stick."]],[["B","I had the damage and I dropped it. Again."],["A","Stop going for the long one. Take the two hits and the knockdown."],["B","That's so much less."],["A","It's more than nothing, which is what you've been getting."]],[["A","You're not up for a while. Sit and watch that setup."],["B","Watching doesn't really do much for me."],["A","Watch what they do right after they get thrown. Not the combos. Just that."],["B","Okay."]],[["B","I'm on in two matches and my hands have gone cold. Is that normal?"],["A","Go walk a lap round the pinball machines and come back."],["B","Does that actually help?"],["A","It gets you off the chair."]],[["B","Somebody told me I shouldn't be playing this character at all."],["A","Who."],["B","I didn't get a name."],["A","Then it doesn't count. Plug in, you've got the left side."]]]},"quietly-buffed":{"cat":"F","roles":{"A":["main:buffed"],"B":[]},"world":["patch:fresh"],"ex":[[["A","They barely touched anything. Two frames off the recovery on one poke."],["B","Two frames is the difference between me punishing it and me blocking and eating a throw."],["A","Well. If you want to look at it that way."],["B","That's the only way there is to look at it."]],[["B","You've been very quiet about the patch notes for someone who read them out loud in the parking lot."],["A","I read them for everybody. I read your stuff too."],["B","You read mine in a completely different voice."]],[["A","Still losing the same neutral I was losing before, so."],["B","You're losing it from further away now."],["A","Marginally."],["B","Marginally is what I'd call the whole rest of my week, and I'm still complaining about it."]],[["B","Set?"],["A","Sure, but you should know I don't really have the combo down yet. The new one."],["B","You did it four times against the guy before me."],["A","Not cleanly."]],[["A","Honest question, does that poke feel different to you or am I imagining it."],["B","You're not imagining it and you know you're not, you're asking so I'll say it first."],["A","I would like it in your words, yes."]],[["B","I sat down expecting the old spacing and got hit in the shins twice."],["A","That's a habit thing. You'll adjust in a set."],["B","You've said the word adjust six times tonight and it's never been about you."]],[["A","They gave back something they took away last time. It's not new, it's returned."],["B","Returned with more range."],["A","Same range."],["B","I'm getting hit from where I used to stand safely, so one of us is measuring wrong and it isn't me."]],[["B","How's it feel?"],["A","Fine. Normal. Like it always did."],["B","You've been in training mode since you got here and you haven't taken your jacket off."]],[["B","So what actually changed, in plain words."],["A","The knockdown's better. That's it. Better knockdown."],["B","Meaning your oki, which was already the worst part of playing you."],["A","You're building this into something."]],[["A","Everyone's acting like I got handed a new game. It's the same character with one fewer excuse."],["B","Then use the excuse you've got left."],["A","I don't have one, that's the problem. I have to just play now."]],[["B","You're going to be insufferable for about a month and then they'll take it back."],["A","I'm not being insufferable. I've said almost nothing."],["B","You're doing the modest thing, which costs me more."],["A","Put a coin up and I'll be as loud as you want."]]]},"railbirds":{"cat":"G","roles":{"A":[],"B":[],"C":[]},"world":["tournament:today"],"ex":[[["A","They're both sitting on full meter."],["B","Neither wants to be the one who spends it first."],["A","Somebody's going to time this out and I'm going to be here for it."]],[["C","Screen's washed out on the left side. Can anyone see what the health bars are doing?"],["A","Red on top. Barely."],["C","Then whoever that is needs to stop walking forward."]],[["B","Low, low, low. Third one in a row."],["A","And blocked standing every time. It's not even a mix at this point, it's a request."],["B","They'll switch. Watch. Now they'll switch."],["A","They did not switch."]],[["A","Who's up in the set?"],["C","Blue. Took the last one on a timeout."],["A","Great. Thirty seconds of two people standing still and I missed it."]],[["C","That was a confirm. Off a stray poke, from that far out."],["B","Yeah, okay."],["C","You don't sound impressed."],["B","I'm impressed. I just also have to play that in about twenty minutes."]],[["B","Every knockdown, same oki. Same button, same timing."],["A","It keeps working."],["B","It keeps working."],["A","Then it's not a problem yet."]],[["C","Move up a row, you're standing right in the beam."],["A","Sorry. My arm's on the wall over here."],["C","Better. Now sit down, you're doing the same thing with your head."]],[["A","Round's over and I have no idea what hit them."],["B","Throw. They went for the tech about a half-second late."],["A","On the projector it just looks like everybody hugs and one of them falls over."]],[["B","Nobody's pressing a button. Twenty seconds of walking back and forth."],["C","This is the good part."],["B","It genuinely is, but the room's about to start yelling for a throw."],["C","Room's wrong. Let them cook."]],[["A","That's the second drop in the same combo."],["C","Same spot both times, too. Right after the wall."],["A","That's a labbing thing, not a nerves thing."],["C","Could be both. Could easily be both."]],[["C","Popcorn machine's louder than the stream."],["B","Turn the projector up or turn the popcorn off, those are the options."],["C","I'm not touching the popcorn. There's a line for it."]],[["B","Whoever's on the right keeps trying to walk out of the corner and eating a poke for it."],["A","They've got no answer from there. You can see them looking for one."],["B","Jump. Just jump, take the hit, get out."],["A","That's a lot of damage for a bad seat."]]]},"recruiting":{"cat":"J","roles":{"A":["teammate"],"B":[]},"world":[],"ex":[[["A","We're one short for the team bracket. You in?"],["B","Who else is on it?"],["A","Me and one other. Doesn't change your games either way."],["B","It changes whether I have to talk on the drive."]],[["B","Heard you're looking for a third."],["A","Looking is generous. I've asked five people and one of them walked off while I was still talking."],["B","What slot's left?"],["A","Last. That's why it's left."]],[["A","You free the weekend after next?"],["B","Depends what for."],["A","Teams. We've got two and a hole."],["B","I'll say yes now and check when I get home."]],[["B","I heard there's a spot on your team."],["A","There is. It's yours if you want it."],["B","I lose to you every time we play."],["A","You lose to me. Nobody else in that bracket plays anything like me."]],[["B","How much is it per person?"],["A","Split three ways it's less than dinner."],["B","And if we go out first round?"],["A","Then we go get dinner."]],[["A","We want you last, {t}. Anchor."],["B","Why me."],["A","You don't start swinging wild when you're behind. That's the whole job."],["B","I do swing wild. You just haven't sat through those sets."]],[["A","My teammate wants you on the team and won't come say it."],["B","Why not?"],["A","Decided in advance you'd say no. Doesn't want to hear it out loud."],["B","Tell them to ask anyway."]],[["B","I can't do practice nights. Work's got me on a rotation until who knows when."],["A","Nobody's practising. We show up and hope."],["B","That I can do."]],[["A","There's a team spot open and the other two of us already said—"],["B","Yes."],["A","You haven't heard the part about the entry fee."],["B","Still yes. Now I'm just annoyed about the fee."]],[["A","Has anybody else asked you yet?"],["B","One person. Told them I'd think about it."],["A","Think about ours instead. Same event, better company."],["B","You don't know who asked me."]],[["A","I need a name on the sheet before they lock it up tonight. Yours fits."],["B","Put me down as a maybe."],["A","There's no maybe column. It's three lines and a box for the fee."],["B","Write small, then."]]]},"returning-after-long":{"cat":"D","roles":{"A":["veteran"],"B":["veteran"]},"world":["arcade:established"],"ex":[[["A","You still hold down back when you're nervous."],["B","I was hoping that got patched out of me while I was gone."],["A","It got worse. There's nothing on top of it now."],["B","Give me an hour."]],[["B","Nobody told me the popcorn machine died."],["A","It didn't die. They moved it by the vending machines and it makes a noise now."],["B","What kind of noise."],["A","You'll hear it."]],[["A","Sit down, I've got next after this."],["B","I don't know if I want to start with you."],["A","Start with me, get it out of the way, then you can lose to everyone else fresh."]],[["B","My combos are all half a second late. Everything else feels fine."],["A","That's the part that comes back last. Took me two weeks after my hand thing."],["B","Two weeks of losing."],["A","Two weeks of losing, yeah. You've got the room for it."]],[["A","Throws are three frames faster than when you left."],["B","So that's why I keep eating them."],["A","You keep eating them because you stand still. But also yes."]],[["B","Everyone in here got better."],["A","Everyone in here played. That's the whole mechanism."],["B","I know how it works. I'm just saying it out loud so I stop being surprised."]],[["A","You've still got the same tag on the machine."],["B","I saw. Nobody took it."],["A","A couple of people asked. I said you'd be back."],["B","You didn't know that."]],[["B","Do people still stay till close on Fridays?"],["A","Till the lobby lights go off and then a bit past that."],["B","Good. I've got nothing on tomorrow."]],[["A","You didn't answer any of the messages."],["B","I know."],["A","I'm not asking why. I'm telling you I noticed."],["B","Noted. Put me on the list."]],[["B","That opener you kept doing at me — is that new tech or did I just forget it."],["A","Somebody found it a while back and now half the room does it."],["B","Is it minus?"],["A","Very. Nobody's punishing it yet."]],[["A","You look the same."],["B","I feel worse. Which chair is the broken one now?"],["A","Second from the end. Same one."],["B","At least something held."]],[["B","I thought about coming back four or five times before tonight."],["A","What was the holdup?"],["B","Figured everyone would make a thing of it."],["A","Two people said hi. You're overestimating us."]]]},"rivalry-cooling":{"cat":"C","roles":{"A":["rel:familiar"],"B":["rel:familiar"]},"world":["arcade:established"],"ex":[[["A","You want to run it? I've got the machine for another twenty."],["B","Sure. Not first to five though, my wrist's been bad since the weekend."],["A","First to three's fine."],["B","That's what I meant."]],[["B","Someone told me you were on the other setup all night with the new guy."],["A","They asked. I wasn't going to say no."],["B","No, that's good. They need somebody who'll actually reset the round instead of just farming them."],["A","I farmed them a little."]],[["A","I stopped counting our sets a while back."],["B","You were never counting right anyway. You had that one where the stick died as a win."],["A","It was a win. You lost the round."],["B","Get popcorn, the machine's actually warm for once."]],[["B","You're not blocking low against me anymore, you're just eating it and going for the throw after."],["A","Yeah. Costs less than guessing wrong twice."],["B","Huh. I'd have argued with you about that before."],["A","Argue with me now, I've got nothing else going on."]],[["A","That set felt long."],["B","Five games in and neither of us adapted. That's the whole problem."],["A","We know each other's stuff too well. Nothing left to find."],["B","There's stuff left. Neither of us wants to lab it."]],[["B","Who's got next after you two?"],["A","Nobody. Everyone clears out when we sit down, they think it's going to be a whole thing."],["B","It used to be a whole thing."],["A","Tell them that. I'm tired of playing in an empty row."]],[["A","Do you still watch my replays or did you quit that."],["B","Quit it. Was taking up my evenings and you kept changing your neutral anyway."],["A","I changed it once."],["B","You changed it once and I rewatched four hours. Not doing that again."]],[["B","You didn't say anything when I dropped that confirm just now."],["A","What do you want me to say."],["B","You had a whole routine about it. The sigh, the whole bit."],["A","I'll bring it back if you drop the next one."]],[["A","I'm going to go get food, you eating?"],["B","You never used to leave the room mid-session."],["A","I'm hungry mid-session now. Chicken or the other thing?"],["B","Whatever you're getting."]],[["B","Somebody in line asked me who's better between us."],["A","And?"],["B","I said it depends on the week, which I don't think was the answer they wanted."],["A","It's not the answer I wanted either."]],[["A","Sit down, I'll take the sticky side."],["B","You'd have made me flip a coin for that a while ago."],["A","I've decided I like the sticky one. Something to press against."],["B","Fine. Don't bring it up after."]],[["B","You looked bored in that last one."],["A","I wasn't bored. I just knew what was coming and let it happen."],["B","That's worse than bored."],["A","Probably. Run it again anyway."]]]},"rivals-cold":{"cat":"C","roles":{"A":["rel:hostile"],"B":["rel:hostile"]},"world":[],"ex":[[["A","Take my name off the sheet. I'll just enter the bracket."],["B","Same sheet. That's where the bracket comes from."],["A","Then leave it."],["B","Wasn't going to touch it."]],[["A","Good set."],["B","It wasn't."],["A","No."]],[["B","That adapter's mine."],["A","The one in the cabinet is dead."],["B","Lucky I brought my own, then."],["A","I'll ask someone else."]],[["B","You've got next on this one."],["A","I'll take the other setup."],["B","Other setup's got the dead button on player one."],["A","I'll wait for it anyway."]],[["A","Ten a set, first to three, whenever you want it."],["B","No."],["A","Didn't think so."],["B","You'll get me in bracket like everybody else does."]],[["B","Everything that character does is minus and it never once costs you anything."],["A","Then punish it."],["B","I do punish it. The same pressure is back on me two seconds later."],["A","Punish it twice."]],[["B","Your bag was on my chair."],["A","It was on a chair."],["B","It's under one now."],["A","I saw."]],[["A","Get up. I'm done."],["B","Nobody sat you down there."],["A","Two more games and I take that set."],["B","You had two more games."]],[["B","You switched after the first one."],["A","I switch all the time."],["B","Not against anybody else in here."],["A","Nobody else in here sits on a life lead and runs the clock out."]],[["A","You found something in the corner. I watched you set it up twice."],["B","Did I."],["A","Somebody in here will tell me by next week."],["B","Then wait for next week."]],[["B","I'm out."],["A","You've been here twenty minutes."],["B","And now I'm out."],["A","Right."]],[["A","Sit somewhere else while I'm playing."],["B","I can see the screen from every chair in this room."],["A","Then watch the projector."],["B","Projector's on this match. Same picture."]]]},"rivals-fond":{"cat":"C","roles":{"A":["rel:close","h2h:even"],"B":["rel:close"]},"world":[],"ex":[[["A","We're dead even again. You know that, right?"],["B","I know it down to the game. I checked in the parking lot."],["A","That's worse than me keeping track."],["B","Considerably. Get your character."]],[["B","You're not blocking low anymore. At all. You just stopped."],["A","I decided I'd rather eat it than guess."],["B","That's not a plan, that's a mood."],["A","Worked twice."]],[["A","Sit down, I've got something for you."],["B","If this is the new punish off my sweep, I already fixed the sweep."],["A","You fixed it wrong. You made it minus by more."],["B","Yeah, I know. I was hoping you hadn't looked."]],[["B","Bad day at work?"],["A","Why."],["B","You're mashing throws in neutral. You do that when you've had a bad day."],["A","Two more games and then I'll tell you about it."]],[["B","I dropped the confirm three times that set and you still only just won."],["A","Don't tell me things like that."],["B","You'd have found out anyway."]],[["A","Hand hurts."],["B","Which one."],["A","The one I need."],["B","Then we'll go until it stops working and I'll take the rest of them."]],[["A","When you beat me last week you didn't say anything after."],["B","I was thinking about how you got the round back at the end."],["A","So was I. All week."],["B","Good. Then neither of us slept and we're still level."]],[["B","Anybody else, I'd take the free win and go get a drink."],["A","But."],["B","But you'd bring it up in six months. Sit down and play it properly."]],[["A","You're not going for oki anymore. You just back off and reset."],["B","Because you tech everything I do off a knockdown and it makes me want to leave."],["A","So that's a compliment."],["B","It's a complaint that happens to be flattering. Run it back."]],[["B","You want food or you want to keep going?"],["A","Keep going. I'll eat when one of us is ahead."],["B","We could be here a while."],["A","Get me something from the vending machine, then."]]]},"rivals-plus-audience":{"cat":"C","roles":{"A":["rel:hostile"],"B":["rel:hostile"],"C":["humor:clowning"]},"world":[],"ex":[[["C","You're both in the same half of the bracket. I told the guy at concession to expect a rush."],["A","There's no rush. It's eleven people."],["C","It's a rush if they all stand up at once."],["B","I'll be at the other setup until it gets called."]],[["B","Your bag's on the chair I want."],["A","There are other chairs."],["C","There are nine other chairs, I counted, and I'm in the good one."],["B","I'll stand."]],[["C","For anyone who wandered in from the skee-ball—"],["B","Don't."],["C","—and is now standing in the dark for no clear reason, welcome."],["A","Are we starting or not."]],[["B","You pick a side. I don't care which."],["A","Neither do I. Pick."],["C","I've got a coin. Found it on the DDR machine, so it's neutral."],["B","Flip it, then."]],[["C","Let me put this set on the projector. People will actually come in for once."],["A","No."],["C","That's half a yes."],["B","It isn't."]],[["A","The sweep is minus. It's been minus since launch."],["B","Then punish it instead of announcing it every week."],["C","Don't stop, I'm dragging a chair over. Hold that thought."],["A","There's no thought to hold."]],[["A","Good set."],["B","Yep."],["C","I heard that. Both of you. I'm reporting it at the front desk."],["B","Tell them it was close."]],[["C","I wrote your head-to-head on the whiteboard out front. Under the birthday bookings."],["A","Take it down."],["B","Leave it up."],["A","I'll take it down myself, then."]],[["C","Loser buys from the vending machine and I pick the item."],["B","I'm not eating anything you pick."],["C","You wouldn't be eating it. You'd be paying for it."],["A","Leave me out of that."]],[["C","You two have kept a whole room between you all night and now you're on the same cabinet."],["A","It's the only one open."],["C","I know. I unplugged the other one."],["B","Plug it back in."]],[["C","I'll play the set for one of you. Either one. You'd lose, but nobody would have to talk."],["A","We're not talking."],["B","There's nothing to talk about."],["C","Offer stands."]],[["C","First to two or first to three? I'm asking because of the popcorn."],["B","Two."],["A","Three."],["C","I'll go get a third opinion."]]]},"runback-denied":{"cat":"A","roles":{"A":["lost"],"B":["won"]},"world":[],"ex":[[["A","One more. First to two, we'll be out of here in ten minutes."],["B","I'm packing the pad. It's already in the bag."],["A","Bags open."],["B","Not tonight it doesn't."]],[["B","That's me. I'm going to go buy a pretzel and sit down somewhere with actual light."],["A","Buy it, eat it, come back."],["B","You'd get the last one back and then want three more."],["A","Obviously."]],[["A","You can't leave on that. I dropped two confirms in the one where you switched sides."],["B","You dropped them. That's not a loan."],["A","It's a technicality."],["B","Sure. Take it up with whoever's got next."]],[["A","Runback."],["B","No."],["A","You didn't even think about it."],["B","I did. It was quick."]],[["B","My hands are done. I can feel it in the wrist, and I've got work in the morning."],["A","So play worse. I'm asking for less than your best."],["B","That's what the last set was."]],[["A","I want it now, though. If I wait a week I'll come back with a whole plan and the plan will be wrong."],["B","Then lab it and be wrong on purpose next time."],["A","Not the same."],["B","No. It's better for me."]],[["B","Put your name up, someone else will run you. Half this room's been sitting."],["A","I don't want half this room. I want the person who just did that to me."],["B","Flattering. Still leaving."]],[["B","Good sets. I'm out."],["A","You're leaving while you're up, that's the whole thing here."],["B","Yes. That's why I picked now."]],[["A","I finally figured out the low. I got it twice in a row at the end and then you were gone."],["B","I know you got it. That's information for both of us."],["A","Then let me use it before you sleep on it."],["B","Absolutely not."]],[["A","Come on. You're not even tired, you're just protecting the result."],["B","Correct."],["A","At least pretend it's the wrist or something."],["B","It's a little bit the wrist."]]]},"same-character":{"cat":"E","roles":{"A":["same-main"],"B":["same-main"]},"world":[],"ex":[[["A","You use the low poke way more than I do. Like it's your whole plan."],["B","It's my only way in."],["A","There's another way in. I'll show you after, it's not exciting."]],[["B","Do you hold the button on the second hit?"],["A","No."],["B","Gets you a bit more range. Not a lot. Enough that they stop walking at you."],["A","I'll probably keep not doing it."]],[["A","Mirror's the worst set of my night."],["B","It's just two people refusing to walk forward."],["A","Someone has to. Not going to be me."]],[["B","You've got throw on one button?"],["A","Always have. My hand doesn't make that shape."],["B","Fine. I hate it, but fine."]],[["B","Somebody asked me which of us they should be copying."],["A","And?"],["B","Told them to watch you in neutral and me for punishes."],["A","I'd have sent them to you for both."]],[["A","Take the other color, I can't tell which one of us is which."],["B","You picked that one first last time and I didn't say anything."],["A","I remember. I'm doing it again."]],[["B","You're playing it like a zoner. That's not what it is."],["A","It is when I'm behind."],["B","Fair."]],[["B","I've been in training mode on the same setup all week and it won't work on the short ones."],["A","It doesn't. Height kills it. Use the shorter route on them and just take the knockdown."],["B","That would have been good to know a week ago."],["A","You didn't ask a week ago."]],[["A","What do you take when they whiff the sweep?"],["B","Medium into the knockdown. Anything bigger and I drop it."],["A","There's a full punish there. It's tight, but it's there."],["B","I'll keep the knockdown."]],[["B","You've started cutting the combo short to go for a throw instead. That's mine."],["A","It works."],["B","I know it works. I'd just like it noted."]],[["A","I might pick up somebody else for the bad matchups."],["B","Which ones are bad?"],["A","You know which ones."],["B","I wanted to hear if you meant the same two I do."]]]},"separated-both-here":{"cat":"C","roles":{"A":["rel:hostile"],"B":["rel:hostile"]},"world":[],"ex":[[["A","They've got you on the far setup."],["B","I asked for the far setup."],["A","Then nobody has a problem."],["B","Nobody said anybody did."]],[["B","We're in opposite halves of the bracket."],["A","That wasn't an accident."],["B","No."],["A","Works for me."]],[["A","You're standing in front of the machine."],["B","Buying something."],["A","You've been there since I walked over and you haven't put money in."],["B","Still deciding."]],[["B","My bag's under the chair you're sitting in."],["A","Take it."],["B","I'm going to have to reach past you."],["A","So reach."]],[["A","Two people have asked me tonight if we're running a set."],["B","Tell them no."],["A","I did. They'll come to you next."],["B","Then they'll hear it twice."]],[["A","That last set of yours was clean."],["B","Okay."],["A","That's all I came over to say."],["B","Okay."]],[["B","You were in this line before me."],["A","I'm aware."],["B","Go ahead, then."],["A","I'm not in a hurry."]],[["A","You've got the adapter that actually works."],["B","I do."],["A","The other one eats inputs and I'm on in ten minutes."],["B","Top of my bag. Put it back where you found it."]],[["B","You've been watching my games from back there."],["A","Every chair in this room points at the screen."],["B","Sit at the end of the row, then."],["A","I'll sit where there's a chair."]],[["A","You still owe the entry from last time."],["B","I paid it at the desk. Ask them."],["A","I paid it at the desk."],["B","Then go get your money back and leave me out of it."]],[["A","Someone floated the idea of us shaking hands before this starts."],["B","Not interested."],["A","Neither am I. Tell them, so it doesn't come back to me again."]]]},"should-i-enter":{"cat":"G","roles":{"A":["newcomer"],"B":["veteran"]},"world":["bracket:up"],"ex":[[["A","How bad is it if I sign up and go out immediately?"],["B","You'd be the fourth person to do that tonight. Nobody keeps a list."],["A","I keep a list."],["B","Then sign up early, it's cheaper to get it over with."]],[["B","You've been standing near that bracket long enough to have read it twice."],["A","I'm trying to work out if there's a division for people who learned the throw tech last week."],["B","There isn't. There's also nobody in there who'd be mean about it."]],[["A","Entry's five, right?"],["B","Five, and it all goes back out to the top three. So you're basically funding whoever wins."],["A","That's fine. I've spent five on worse."]],[["B","Sign-ups close when the sheet's full, not at a time. People miss it every single week."],["A","So I should decide now."],["B","You should decide now."],["A","Put me down, then. Before I think about it more."]],[["A","I've only played casuals here. Is the bracket a different crowd?"],["B","Same people. They just sit up straighter and stop talking during rounds."],["A","That part worries me more than the losing."]],[["B","You in or are you going to watch and tell me afterwards you should've entered?"],["A","Second one. It's a solid plan and it's never let me down."],["B","Chairs are up front if you want a good view of your regret."],["A","Fine. Where's the pen."]],[["A","My neutral is bad. Like, I don't have one."],["B","Then you'll find out fast where you're getting hit, which is more than you'll learn from a night of casuals."],["A","That's a very reasonable way to sell me on getting beaten up."]],[["A","Do I need to bring my own pad?"],["B","Sticks are on the cabinets and they work. Most people bring pads anyway because they don't trust that sentence."],["A","I'll use the cabinet."],["B","Left side's better. Write your name down while there's still room."]],[["B","You looked good in that last set. Better than half the sheet."],["A","That was casuals. There's no pressure in casuals."],["B","There's no pressure in this either, it just has a piece of paper attached."]],[["A","Is it double elimination?"],["B","Yeah, so you get two chances to lose. People find that comforting for some reason."],["A","I do find it comforting."]],[["A","I'd want to lab my punishes first. Give me a week."],["B","There's one every week. You'll say that next week too."],["A","Probably."],["B","I'll pencil you in anyway. Cross it out if you chicken out, I don't care."]]]},"sleeper-defender":{"cat":"E","roles":{"A":["main:lowtier"],"B":[]},"world":[],"ex":[[["B","People keep telling me your character's bad and then losing to it."],["A","They're not wrong about the character."],["B","Somebody's wrong about something."]],[["A","New tier list went up. Bottom row again."],["B","Does that bother you?"],["A","They put me under the one with no reversal. That's just sloppy."]],[["B","What's actually wrong with your character? Nobody's ever been able to tell me."],["A","Nothing converts off the low. I have to open you up twice to get what you get once."],["B","That's the whole problem?"],["A","It's plenty. It's just boring to complain about, so nobody does."]],[["A","You don't have to keep defending my character every time it comes up."],["B","I'm not defending you. I've lost to it enough to have my own opinion."],["A","Fine. Keep it."]],[["B","Somebody called your character free. Sitting two chairs down, out loud."],["A","Before or after playing me?"],["B","Before."],["A","Then it'll sort itself out."]],[["A","Everybody being sure my character's garbage does a lot of work for me."],["B","How."],["A","Nobody's bothered to learn what I do to them on wakeup. So they guess, and they guess wrong, and then they blame the guess."]],[["B","I'm taking your character off the list of stuff I don't prepare for."],["A","There was a list."],["B","Short one."],["A","What else is on it?"]],[["B","You never think about playing someone who's plus on something?"],["A","I've got a plus move."],["B","The long poke. Which is plus at the very tip and minus everywhere else."],["A","So I hit them at the tip."]],[["B","Your character's fine in neutral. It's the damage without meter that's the problem."],["A","You've thought about this more than I have."],["B","I lost a set to it and I wanted a reason that wasn't me."]],[["B","Watching you win with that makes me want to pick something bad."],["A","Don't."],["B","Why not."],["A","Because you'd have to actually like it. Liking it is the whole job, and you'd be out in a month."]],[["A","Whoever wrote the tier list on the whiteboard out front put me below the joke pick."],["B","The desk let someone write on that?"],["A","It's dry erase. I fixed it on the way in."]]]},"spending-too-much":{"cat":"I","roles":{"A":["humor:clowning"],"B":[]},"world":[],"ex":[[["A","The money isn't real until the app updates."],["B","It updates instantly. That's the whole point of the app."],["A","Then I'm not opening the app."]],[["A","That vending machine has more of my money than my landlord does this month."],["B","The bottles in there are four dollars."],["A","I know exactly what they are. I'm in there twice a night."]],[["A","Forty in skee-ball and I'm still short on the shark."],["B","They sell those. There's a whole shelf of them with a price tag."],["A","Buying it defeats the purpose."],["B","What's the purpose."]],[["B","Was that your card the counter kept beeping at?"],["A","That's between me and my bank."],["B","I can get your entry, it's fine."],["A","Great. Now it's between me, my bank, and you."]],[["B","New stick?"],["A","The box is still in my trunk. I'm not ready for it to be in the house yet."],["B","That bad."],["A","It's a nice stick, though."]],[["B","You've been in here every night this week."],["A","Cheaper than anywhere else I'd be sitting."],["B","You bought dinner at that counter twice yesterday."],["A","Both of them were dinner. I'm not walking it back."]],[["A","You go straight out to the pinball every single time you drop a set."],["B","It's fifty cents."],["A","It's fifty cents a lot of times."],["B","I know the number. I don't say it out loud."]],[["A","I put fifty on one of those play cards at the front desk and I don't even touch the games out there."],["B","Why would you do that?"],["A","Attendant asked how much and I panicked."]],[["B","That's the third entry you've covered tonight."],["A","I keep a list."],["B","Show me the list, then."],["A","It's more of a feeling."]],[["A","Packed a sandwich today so I'd stop buying food in here."],["B","How'd that go."],["A","Ate it in the parking lot, came in, bought a pretzel."]],[["B","You come in from pretty far out, right?"],["A","Gas both ways runs me more than the entry does."],["B","Ride in with somebody."],["A","Then I go home when they go home. I'd rather pay."]]]},"stop-before-bad":{"cat":"B","roles":{"A":["mood:low"],"B":[]},"world":[],"ex":[[["A","One more."],["B","We can, but you're pressing buttons like you're mad at them."],["A","I am mad at them."],["B","Then let's stop here and I'll owe you a set."]],[["B","You want to keep going or you want to go get a drink and come back to it."],["A","Neither, really."],["B","That's fine too. I'll be on the other cabinet if you change your mind."]],[["A","I'm going to say something unpleasant in about two games and I'd rather not."],["B","Appreciated. Save it."],["A","It wasn't even going to be about you."],["B","Still. Save it."]],[["A","Sorry, that was loud."],["B","It was. Nobody's bothered, but let's cut it here anyway."],["A","Yeah."],["B","Popcorn machine's on. Go stand near it for ten minutes."]],[["B","Set's yours if you want it. I'll take the loss on the sheet."],["A","Don't do that. I don't want it handed over."],["B","Then we didn't play. Nothing on the sheet."],["A","Fine. Nothing on the sheet."]],[["A","Give me a minute before the next one."],["B","Take longer than that. You're not going to enjoy anything you do in the next minute."],["A","That's probably true."]],[["B","You slammed the stick and then apologised to the stick."],["A","I've had a day."],["B","I know. Which is why we're stopping while it's still funny."]],[["A","I keep going for the throw when I know you're just going to tech it. I know and I keep doing it."],["B","So stop for tonight and lab it when you're not annoyed."],["A","I'll be annoyed then too."],["B","Differently annoyed. That's better."]],[["A","Rematch."],["B","No."],["A","Why not."],["B","Because you said rematch the way people say it right before they stop being pleasant to be around."]],[["B","Let's stop. Not because of the score, I just don't want us doing this at each other."],["A","We're not doing anything at each other."],["B","Not yet."],["A","Yeah, all right. Put someone else on."]]]},"streak-not-fun":{"cat":"A","roles":{"A":["lost","h2h:losing"],"B":["won","h2h:dominant"]},"world":[],"ex":[[["A","You can stop being polite about it. I'd rather you just told me what I'm doing."],["B","You block low on wakeup every time. Every single time. I stopped even checking."],["A","So you've been going for the throw all night on autopilot."],["B","I've been thinking about what to have for dinner, mostly."]],[["B","Want to run it back or do you want a break?"],["A","Break. Not because I'm mad, I just need to not look at your character for a bit."],["B","Fair. I'll take somebody else in the meantime, keep the seat warm."],["A","Warm it up for somebody who's going to beat you, ideally."]],[["A","That's what, the fourth set in a row now."],["B","I don't keep count."],["A","You absolutely keep count."],["B","I keep count. It's not a good number for either of us."]],[["A","Do me a favour and pick your worst character next set."],["B","That's not going to help you and it's going to annoy you more when it doesn't."],["A","Then at least I'll be annoyed about something new."]],[["B","I'm not enjoying this either, if that helps."],["A","It does not help. It does the opposite of help."],["B","Right. Forget I said it."],["A","One more. I've got one specific thing I want to try and then I'm done for the night."]],[["A","Every time I get a knockdown I panic and burn all my meter on nothing."],["B","You do. And then you've got nothing left when I get in."],["A","So save it."],["B","Save it, and if you drop the confirm, so what, you still have it."]],[["B","You've had the same set of buttons every game, you know they're not the problem."],["A","I know. I checked anyway."],["B","You checked them twice."],["A","Give me the small dignity of checking them twice."]],[["A","At some point somebody else should get on so you're not just farming me all night."],["B","Nobody's on the list. You're the only one who'll sit down."],["A","That's the sad part of this whole arrangement."],["B","I'll drag somebody in from the pinball side if it makes you feel better."]],[["A","I got one round. Off you. Tonight."],["B","You got two rounds. The one where you switched sides counts."],["A","Then I'm going home on that."]]]},"student-beats-mentor":{"cat":"J","roles":{"A":["student","won"],"B":["mentor","lost"]},"world":["arcade:established"],"ex":[[["B","You stopped throwing out the low poke on wakeup."],["A","You punished it every single time for months. I got tired of it."],["B","Took you long enough. Run it back, I want to see if you can do it twice."]],[["A","Do I say something or do we just keep playing."],["B","We keep playing. But go get a drink first, I need a minute with my hands."],["A","They're fine, you were blocking great."],["B","Blocking's the part I'm good at. That's the problem."]],[["B","Well. That's that, then."],["A","That's what?"],["B","You don't need me telling you what your buttons do anymore. Doesn't mean I'll stop."]],[["A","I dropped the confirm in the last round and still won."],["B","Yeah, because you had life to spend. That's the whole thing I've been trying to get you to understand."],["A","So you're happy about it."],["B","I'm something about it."]],[["B","Who taught you to stand at that range?"],["A","Don't."],["B","No, I'm asking. Genuinely blanking on it."],["A","You did, and you know you did, and I'm going to go put a dollar in the popcorn machine."]],[["A","You want to switch sides? I know you don't like that stick."],["B","The stick was fine. You beat me on the buttons I like."],["A","Okay."],["B","Get the next one in before I think about it too long."]],[["B","Nothing changed. You just did the same three things and I couldn't find an answer."],["A","That's the nicest thing you've ever said to me."],["B","It wasn't nice. It's a problem I have to go work on now."]],[["B","Don't look at me like that."],["A","I'm not looking at you like anything."],["B","You've got the face. I invented that face. Plug the other pad in."]]]},"suddenly-everywhere":{"cat":"F","roles":{"A":[],"B":[]},"world":["tierlist:new"],"ex":[[["A","Four people picked the same character tonight. That's not a coincidence, that's a list."],["B","The list moved it up two spots this morning. Now everyone wants to see what the fuss is."],["A","And? Is there a fuss?"],["B","The dash is genuinely good. The rest of it I think people are imagining."]],[["B","You're on that character now too?"],["A","For one set. I wanted to feel what they're all going on about."],["B","Feel anything?"],["A","My thumb hurts and I lost. So, no."]],[["A","Nobody touched that character for weeks. I couldn't have told you the low was minus."],["B","It's minus. Barely. You need to be standing right on top of them."],["A","I've been blocking it and then just waiting."],["B","Yeah, everyone has. That's the whole reason it looks strong."]],[["B","Third set in a row against them."],["A","Getting a lot of practice against one character, at least."],["B","I don't want practice against one character. I want to play the game."],["A","Then win, and you'll get somebody else."]],[["A","Who was the first one to pick that character? Genuinely."],["B","Somebody at the far setup, before the list went up. Then it went up and now it's five of them."],["A","So the list caused it."],["B","Or the list noticed it. Hard to tell from in here."]],[["B","You know the throw range is longer than it looks."],["A","I found that out. Repeatedly."],["B","Tech it early. Everyone's been teching late because they're guessing off the animation."]],[["A","I labbed the punish for the overhead last night. Two hours."],["B","Against a character that didn't exist last month."],["A","It exists now. It's on every screen in this room."],["B","Fair. Show me the punish, I'll steal it."]],[["B","I liked it better when nobody played them."],["A","Why, you had the matchup solved?"],["B","I had never played the matchup. That's not the same thing but it felt similar."]],[["A","Somebody moved them up on the list and now I can't get a set without seeing that same jump-in."],["B","You could learn to deal with the jump-in."],["A","I'm dealing with it. I'm dealing with it four times a night."],["B","Then in a week you'll be the one everybody avoids. Congratulations."]],[["B","You're going to switch too, aren't you."],["A","I'm thinking about it."],["B","You've said that about three characters since the list came out."],["A","And I've stayed on mine every time. Notice that part."]],[["B","Two months ago I'd never seen that character in neutral once."],["A","Nobody had. That's why the pokes felt unfair, we didn't know the ranges."],["B","Do you know them now?"],["A","I know one of them. It's the one that keeps hitting me."]]]},"system-change":{"cat":"F","roles":{"A":["veteran"],"B":["veteran"]},"world":["patch:system"],"ex":[[["A","Throw tech window got shorter. I've been mashing it since the patch and eating every single one."],["B","I quit trying to tech. I just block low and take the throw."],["A","And that's working."],["B","It works right up until somebody notices."]],[["B","How much of your stuff still works?"],["A","Combos, all fine. Everything I did after a knockdown, dead."],["B","So half."],["A","So half."]],[["A","Hour in training mode and I came out with nothing."],["B","Nothing at all?"],["A","One thing. It needs meter, and I don't build meter anymore."]],[["B","You're the only person in this room not complaining."],["A","Neutral's slower now. I never wanted to be in there fast in the first place."],["B","Everybody else spent forever learning to be fast."],["A","I'm aware."]],[["A","My hands keep doing the old timing. I can feel it's wrong while it's happening and I do it anyway."],["B","Give it a month."],["A","There's a bracket in two weeks."],["B","Then give it two weeks and be worse."]],[["B","That oki you used to run in the corner. Still there?"],["A","No. They just get up now. Straight up, no guess."],["B","You find anything to put in its place?"],["A","I've been throwing them instead. It's a downgrade but nobody's stopped falling for it yet."]],[["A","I'm going through my notes and half the pages are crossed out."],["B","Don't throw the crossed-out ones away."],["A","Why would I keep them?"],["B","They put things back sometimes. I've seen it happen twice."]],[["A","Thinking about dropping mine. Everything that made them worth playing was the old system."],["B","Play them tonight anyway."],["A","Why."],["B","Because you'll say that all week and then play them anyway."]],[["B","Quick getup. Still hold down?"],["A","You tap it as you land now. Holding does nothing."],["B","Tap it as in the frame you land, or—"],["A","Later than feels right. That's honestly the closest I can get it."]],[["A","Just play. You've read the notes about eight times."],["B","I'd like to know what's minus now before I find out the hard way."],["A","You're finding out the hard way either way."],["B","Fine. Set it up."]]]},"team-losing":{"cat":"J","roles":{"A":["teammate","lost"],"B":["teammate","lost"]},"world":["tournament:today"],"ex":[[["A","I gave up the first one. Whole thing starts there."],["B","I lost mine twice as fast, so let's not do the accounting."],["A","Fine. Losers bracket in about forty minutes."],["B","I'm getting a pretzel first. You want anything."]],[["B","We never talked about who takes the anchor slot."],["A","We talked about it in the parking lot."],["B","That was you saying \"you go last\" and then walking inside."],["A","And it held up until it didn't."]],[["A","You had them at a sliver and you went for a throw."],["B","Teched it clean. Nothing to say about that."],["A","I'd have pressed buttons and lost the same, probably."],["B","Probably."]],[["B","Sit down, you're pacing in front of the screen."],["A","I can't watch the next match yet."],["B","Then go stand by the popcorn machine and be mad there."]],[["A","That was ours if either of us blocked low once."],["B","I blocked low. It was the wrong once."],["A","Yeah, I saw. Then I did the exact same wrong once right after."],["B","Team synergy."]],[["A","We should have switched order after the first game."],["B","I thought about it. Didn't want to look like we were panicking."],["A","We were panicking."],["B","We were. It just would have been on the record."]],[["B","Do we get a rematch out of this or are we done for the day."],["A","There's a bracket, they can't just hand us another one because we asked."],["B","I know. I'm asking anyway."]],[["A","Whoever signed us up put us on the same side as the two best people here."],["B","That was me. There was one pen and a line behind me."],["A","Not blaming you."],["B","You are a little."]],[["B","Their neutral was better than ours the whole set and I don't think it was close."],["A","It wasn't. I couldn't get in without eating something on the way."],["B","Same. I want to lab that spacing before next week."],["A","Come at seven, nobody's on the second setup till eight."]]]},"the-adjustment":{"cat":"B","roles":{"A":["rel:familiar"],"B":["rel:familiar"]},"world":[],"ex":[[["A","You quit throwing me after the first game."],["B","You started teching it every time. There's no version of that where I keep going."],["A","So what were you doing instead."],["B","Standing there. Waiting for you to press something."]],[["B","Second half I stopped dashing in after the knockdown and just blocked."],["A","I noticed. Late."],["B","You were still doing the button you use to stop me from coming in. Free."],["A","Yeah, I kept doing it into nothing for a while there."]],[["B","I moved back about a step further in neutral. That's the whole adjustment."],["A","That's why my poke kept coming up short?"],["B","It was whiffing right in front of me and I got to hit you for it."],["A","Great. Cool. Love that."]],[["A","I switched to the slower button in neutral partway through."],["B","That's what that was. I thought my timing had gone."],["A","No, you were fine. I just stopped giving you the fast one to punish."]],[["B","You stopped spending meter the second I went up a game."],["A","I was saving it. Wanted it for the last one."],["B","There wasn't a last one, though."],["A","I'm aware of how that went, yes."]],[["A","Did you change your buttons or did you change what you were doing."],["B","What I was doing. I quit going for the mix-up on wake-up and just took the safe hit."],["A","Hm. Less fun to watch."],["B","It worked, so."]],[["B","I gave up on trying to punish that move and just started blocking it."],["A","You can punish it."],["B","Not on this stick I can't. Not consistently. So I stopped and my life went up considerably."]],[["B","You went quiet in neutral after that first game. Barely pressed anything."],["A","You were whiff punishing everything I threw out. Only thing left was to stop throwing things out."],["B","It's ugly."],["A","It's also two games."]],[["A","That thing where you started jumping. Was that a plan or were you just bored."],["B","Plan. You were sitting on the low button and there's nothing down there that hits me out of the air."],["A","I'll go lab an answer."],["B","Do it before next week, I've got nothing else."]],[["B","I started walking forward instead of dashing. You were catching every dash."],["A","I was guessing on the dash. I don't want to oversell it."],["B","Guessing right is still catching it."],["A","Fine, but don't build a whole game plan around me being smart."]]]},"the-good-chair":{"cat":"H","roles":{"A":["rel:familiar"],"B":["rel:familiar"]},"world":[],"ex":[[["A","That's my chair."],["B","There was nothing on it."],["A","The jacket rule is for the tables out front. In here you just know."],["B","Then I didn't know."]],[["B","You've been sitting in that thing since I walked in and you haven't played a single game."],["A","I'm resting."],["B","Rest in one of the other eleven."],["A","They all lean left."]],[["B","Why are you dragging that one all the way over. Just sit down."],["A","Every other chair in here puts my elbows above the buttons."],["B","So slouch."],["A","That's what the low one does for me. That's the entire reason I want it."]],[["A","Who moved the padded chair out to the pinball side?"],["B","Staff, probably. It was already gone when I got here."],["A","I'm going to go look for it."],["B","If you find it bring two."]],[["B","You play better in that chair, {t}. I've watched it happen."],["A","The chair isn't doing anything."],["B","Last three sets you played standing you lost."],["A","I lost those because I stopped blocking low."]],[["B","Winner stays in the chair too, or just the side?"],["A","Side and the seat. It's been that way as long as anyone's been running it."],["B","Then I care about this set more than I did a minute ago."]],[["A","Whose sweatshirt is folded up on this seat?"],["B","Mine. It's the only way that chair is usable."],["A","So it's the good chair with extra steps."],["B","It's a bad chair wearing my sweatshirt."]],[["B","Your chair creaks right before you jump. Every time."],["A","It does not."],["B","It's done it all night. Half the set I wasn't even looking at the screen."],["A","Fine. Take it and see how you like being listened to."]],[["A","Are you getting up any time soon, or should I plan around it?"],["B","One more set."],["A","You said that when I came in."],["B","It was true then too."]],[["B","The good one finally split down the seat. Right through the middle."],["A","So which chair's the good one now?"],["B","Nobody's decided. Everyone's just standing."]],[["A","That's not one of theirs, is it."],["B","It's from my kitchen. I got tired of the folding ones."],["A","You carried a kitchen chair past the prize counter."],["B","Nobody stopped me."]],[["A","You're up next. Take the chair."],["B","I'm alright standing."],["A","You're not alright standing. You drop the confirm every time you play on your feet."],["B","That happened once."]]]},"this-place-is-filthy":{"cat":"H","roles":{"A":[],"B":[]},"world":["arcade:dirty"],"ex":[[["A","My shoes stuck. Not like a little. I had to pull."],["B","Under the second setup? Yeah, something happened there."],["A","When?"],["B","Nobody's saying."]],[["B","Somebody should mop in here."],["A","Somebody should. We've established that a few times now."],["B","I meant it more as a plan this time."]],[["A","There's popcorn in the chair. Not on. In."],["B","Sit on the other side, that whole row is a loss."],["A","The other side has the puddle."],["B","Then you've got a decision to make."]],[["B","I wiped the buttons down before my set and the paper towel came back grey."],["A","Grey how? Dust grey or people grey?"],["B","I'm not going to answer that."]],[["A","This place is filthy and I say that as someone who doesn't care about much."],["B","You brought your own towel last week. You care."],["A","That's not caring, that's damage control."]],[["B","Are we ever going to talk about the smell in here."],["A","I assumed it was the popcorn machine."],["B","The popcorn machine is part of it. It's not all of it."],["A","Great. Cool. Whose next?"]],[["A","Somebody dropped a drink by the vending machines and just left it."],["B","That's been there since before I got here."],["A","So you walked past it too."],["B","I walked around it. There's a difference and I'm holding onto it."]],[["B","I'm going to get paper towels from concession and do the sticks. All of them."],["A","You'll be there twenty minutes."],["B","I've got twenty minutes."],["A","Then I'll hold the bracket. Do the left one first, it's the worst."]],[["A","Kid came in through the curtain, looked around, left."],["B","Smart kid."],["A","I think it was the floor. You can see the floor's wrong from the doorway."],["B","You can smell it from the doorway."]],[["B","There's a napkin fused to the table. Fused."],["A","Leave it, it's structural at this point."],["B","I peeled it."],["A","And?"],["B","I shouldn't have peeled it."]],[["A","Say something to the front desk about getting in here with a mop."],["B","I did. They said they'd send someone."],["A","When was that?"],["B","Before the floor got like this."]],[["B","My hands feel wrong. Not from playing. From touching things."],["A","Wash them in the bathroom, there's soap sometimes."],["B","Sometimes."],["A","I'd take the tap water and cut your losses."]]]},"threw-it-late":{"cat":"A","roles":{"A":["lost"],"B":["won"]},"world":[],"ex":[[["A","I had that. I was one hit from that."],["B","You went for the throw. You'd been beating me with pokes all set and then you went for a throw."],["A","I wanted it done."],["B","Yeah, well. It got done."]],[["B","You stopped blocking low at the end there."],["A","I stopped blocking anything. I was just pressing buttons and hoping."],["B","You were up two rounds. What happened."],["A","Two rounds happened."]],[["A","Run it back."],["B","Give me a minute, I need water."],["A","I don't want a minute. A minute is how I get sad about that last one."],["B","Then be sad standing up, I'm still getting water."]],[["B","You had me figured out and then you got fancy."],["A","The simple stuff was working and I got bored of it."],["B","Don't get bored of it. Please. I was about to leave."]],[["A","Was I doing something different at the start, or were you?"],["B","You were standing further back. Then you started walking into me and I didn't have to guess anymore."],["A","Huh. I thought I was pressuring you."],["B","You were feeding me."]],[["B","Good set."],["A","It was a good set for like four minutes."],["B","That's four more than I usually get off you."]],[["B","You want to know what changed or do you want to sit with it."],["A","Tell me."],["B","You quit checking my low. Once. And then you didn't go back to it."],["A","That's so stupid. Okay. That's really stupid."]],[["A","I don't lose sets like that."],["B","You just did, though."],["A","I know what I did. I'm saying it's not a thing I do."]],[["B","Sit down, you're pacing."],["A","I'm allowed to pace. I was winning that."],["B","You were. And now there's a chair, and you could be in it."],["A","Fine. Whose next after you."]],[["A","When did you start holding meter? You were spending it early on and then you just stopped."],["B","When I noticed you weren't respecting it. Figured I'd keep it around."],["A","And I walked into it. Twice."],["B","Yeah."]],[["B","You okay? You've been staring at the screen for a bit."],["A","Trying to work out if I got read or if I just fell apart."],["B","Bit of both. I didn't do anything clever, you got faster with your buttons and I let you."],["A","That's worse. I'd rather you'd been clever."]]]},"tired-of-hearing-it":{"cat":"E","roles":{"A":["main:toptier"],"B":[]},"world":[],"ex":[[["A","Say whatever you're going to say now, so I don't have to hear it after the set."],["B","I wasn't going to say anything."],["A","You were doing the face."],["B","That's my whole face. It doesn't mean anything."]],[["A","Nobody who complains can ever tell me which move they think is the problem."],["B","The overhead."],["A","It's minus. You can punish it."],["B","With what, though."]],[["B","Just pick somebody else for a set. That'd shut the back row up."],["A","Then I lose and they say that proves it."],["B","Would you lose?"],["A","Badly. I have one character and about four buttons."]],[["B","There's a tier list on the whiteboard by the registers now. Someone did it in dry erase between the birthday deals."],["A","Of course there is."],["B","Yours is at the top, underlined twice."],["A","Leave it up. I'm not walking out there."]],[["A","You actually want to know where the gaps in my pressure are?"],["B","I want to know if there are any."],["A","Three. Nobody's ever pressed a button in one of them."],["B","Show me the first one."]],[["B","I don't think about your character at all, if that helps."],["A","That's the nicest thing anybody's said to me in here."],["B","It's not a compliment. It's why you keep opening me up with the same low."]],[["B","That last one was clean."],["A","Here we go."],["B","No, it was clean. You confirmed off a hit I didn't think you could even see."],["A","Sorry. Reflex at this point."]],[["B","How am I supposed to get in on that?"],["A","Walk. Slowly. It's boring and it works."],["B","That's the whole answer?"],["A","It's how you took one off me earlier."]],[["B","Is yours the one everybody says is broken?"],["A","Depends who you ask, and how their night went."],["B","I was thinking of picking them up."],["A","Then you get to hear about it too. Sit down, I'll show you the combo everyone thinks is hard."]],[["A","I picked them because of how they walk forward. That's the reason. That's the entire reason."],["B","Nobody in this room is going to believe that."],["A","You asked."]],[["A","You've sat out every set tonight."],["B","I'm not spending a whole evening on one matchup."],["A","It's the only character I've got, so."]],[["A","Three different people have told me what's going to happen to my character when they patch it."],["B","What is going to happen?"],["A","I'll play them worse. Same seat, same nights."]]]},"token-prices-up":{"cat":"H","roles":{"A":[],"B":[]},"world":["price:raised"],"ex":[[["A","Two more per token now."],["B","I saw the sign. Somebody wrote it on the whiteboard in the lobby like it was a birthday."],["A","Doesn't change anything for me, I'm here either way."],["B","Same, I'm just going to be quieter about losing."]],[["A","You want to split a set? I'll cover the first two games."],["B","You don't have to do that."],["A","I know what I dropped at the counter and I know what you dropped, and one of us is getting a longer session out of it."],["B","Fine. First two. Then I'm buying."]],[["B","Did the price go up or did I buy fewer tokens than I thought."],["A","Went up. Same money, less cup."],["B","That explains the last twenty minutes of my night."]],[["A","I'm going to actually block now."],["B","Because of the tokens?"],["A","Because every round costs more than it did last time I was here and I'd like to see the second half of one."],["B","That's the healthiest reason anyone's ever given me for playing defense."]],[["B","There's a kid out on the floor putting a whole cup into skee-ball."],["A","At the new rate?"],["B","Somebody's paying for it and it isn't the kid."],["A","Yeah, well. Nobody's paying for mine."]],[["A","How many you got left?"],["B","Four. Which used to be a warm-up and is now a decision."],["A","Do first-to-two and we both walk out with something."]],[["B","I asked the attendant if the price was going back down."],["A","And?"],["B","Got told to check the whiteboard, which said the same thing as the register."],["A","So no."]],[["A","You've been in training mode the whole time I've been here."],["B","It's free. Everything on the other side of the curtain isn't, anymore."],["A","You can't lab neutral against nobody."],["B","I'm labbing the part where I don't drop the confirm. That part doesn't need you."]],[["A","Rent's up, tokens are up. I'm sensing a theme and I don't like it."],["B","You still came."],["A","Where else am I going, the pinball wall?"],["B","Those went up too."]],[["B","I've started noticing what a game costs while I'm playing it."],["A","That'll wreck you."],["B","It already has. I went for a throw I didn't believe in because I wanted the round over."]],[["A","Bring a stack next time and we'll just run it all night."],["B","A stack is a real number now."],["A","Then bring half a stack and I'll bring half a stack."],["B","That's the same amount of money, you understand that."]],[["B","Everyone's talking about the price and nobody's left."],["A","Where would we go. It's this room or my couch."],["B","Couch has better chairs."],["A","Couch doesn't have you dropping combos on me. Get up, I've got tokens burning a hole."]]]},"unwanted-return":{"cat":"D","roles":{"A":["warned"],"B":["rel:hostile"]},"world":[],"ex":[[["A","Put my name up?"],["B","Marker's on the ledge by the curtain."],["A","You're holding it."],["B","I'm using it."]],[["B","Take the left setup."],["A","Nobody's on this one."],["B","Nobody's on the left one either."],["A","Right."]],[["A","Staff said I'm fine in here as long as I keep my voice down."],["B","Then keep it down."],["A","That's all you've got?"],["B","You asked me about your voice."]],[["B","Got quiet in here fast."],["A","It did."],["B","Something going on out on the floor, probably. Skee-ball or whatever."],["A","Nothing's going on out on the floor."]],[["A","Set?"],["B","Warming up."],["A","You've been in training mode since I walked in."],["B","Yeah."]],[["B","Four names ahead of yours on the list."],["A","None of them are in here right now."],["B","They're at concession. They're coming back."],["A","Fine."]],[["B","The attendant came through here twice while you were setting your buttons."],["A","They can come through as much as they want."],["B","I'm aware."]],[["A","Machine took a dollar off me and gave me nothing."],["B","Front desk does refunds."],["A","You could act like that's a shame."],["B","Front desk does refunds."]],[["A","I'm not going to bring up what happened."],["B","Good."],["A","Just wanted that said out loud."],["B","You brought it up."]],[["B","You hold down-back the whole round until somebody commits to a throw."],["A","It works on you."],["B","It works on most people. I didn't say it didn't work."],["A","Then we're done talking about it."]],[["A","Your neutral's tighter than it was."],["B","Okay."],["A","That was a compliment."],["B","I heard you, {t}."]],[["B","Not that chair. The back's gone on it."],["A","You're telling me that?"],["B","I'd tell anyone that."]]]},"veteran-upset":{"cat":"G","roles":{"A":["veteran","lost"],"B":["newcomer","won"]},"world":["tournament:today"],"ex":[[["B","Good games. I kept jumping in and I figured you'd blow me up for it eventually."],["A","You should have been. I saw it every time and did nothing about it."],["B","So I keep jumping."],["A","Until somebody makes you stop, yeah."]],[["A","That poke you kept using at range, what is it?"],["B","Forward and medium. I don't know what it's called."],["A","It's minus on block, for the record. I never punished it once, so keep pressing it."],["B","It's pretty much the only thing I know how to do."]],[["B","Anything I should have done differently?"],["A","I've got notes, but you won the set, so they're just complaints."],["B","I'll take them anyway."],["A","Ask me after bracket. Losers is up in ten and I don't want to be reasonable yet."]],[["B","Were you going easy that first game?"],["A","No."],["B","Oh."],["A","It's fine. I do my warming up during the set, and that's nobody's problem but mine."]],[["A","Run it back after bracket. Not for anything, just run it."],["B","I'm still in the bracket, though."],["A","Then when you're out. I'm here late regardless."]],[["A","Nice."],["B","You alright?"],["A","Yeah. Going to stand by the popcorn machine a minute and then I'll be alright."]],[["B","The sheet has us again if you come back up through losers."],["A","Then I'll see you in a bit."],["B","You sound sure about that."],["A","I don't have anything else to say about it."]],[["A","Which side were you on?"],["B","Right."],["A","Take the right side next round too, that stick's cleaner. Not an excuse, just telling you."],["B","Okay. Thanks."]],[["B","What was I supposed to do when you had me in the corner?"],["A","Block. You did block. That's the answer."],["B","It felt like I wasn't doing anything at all."],["A","Doing nothing worked."]]]},"visibly-past-it":{"cat":"K","roles":{"A":["veteran","streak:losing"],"B":["veteran"]},"world":["arcade:established"],"ex":[[["A","My hands know exactly what to do. They're doing it about a frame late, every time."],["B","Want the other setup? Chair's better on that side."],["A","It's not the chair."],["B","Didn't say it was."]],[["B","You dropped the same confirm three times in that set."],["A","I saw it hit. All three. I just wasn't there yet."],["B","So it isn't your eyes."],["A","No. I'd already worked that out."]],[["A","Who's after this?"],["B","Nobody. Room's empty, it's just us."],["A","Then keep running it. I'll stop when I win one."],["B","I'm here till eleven."]],[["B","You used to just stand at that range with the long poke and make people walk into it. Nobody wanted to approach you."],["A","I still know where to stand. I get hit standing there now."],["B","Yeah."]],[["A","Got a new prescription last month. Everything's sharp and I still eat the low every single time."],["B","Blocking low isn't really a seeing thing at that speed. It's a guessing thing."],["A","It used to be a seeing thing."]],[["B","That new kid took you two-nothing and then asked you what to practice."],["A","I told them. It was good advice, too."],["B","It was. You just can't do any of it anymore."],["A","Different skill."]],[["A","Tell me what to work on. Actually tell me."],["B","There's nothing. You know all of it better than I do."],["A","Then tell me something that isn't that."],["B","Come earlier. You show up last and you play tired and then you blame your neutral."]],[["A","I'm thinking of cutting back to one night a week."],["B","Which night?"],["A","Whichever one you're here."],["B","Fine."]],[["B","Do you want me to ease off? I'll ease off, I don't care."],["A","No."],["B","Good. I wasn't going to, I just didn't want it sitting there between us all night."]],[["A","That popcorn machine's been running since I got here and not one person has touched it."],["B","You've lost five straight and you're thinking about popcorn."],["A","Six. And I'm not thinking about it, I just noticed."]],[["B","That corner setup you came up with, half the room does it now."],["A","One of them does it right."],["B","The rest mash it and it works anyway."],["A","That's the part that gets me."]],[["A","When people stop coming, do they tell you, or do they just stop?"],["B","They just stop. You'd tell me, though."],["A","Would I."]]]},"waiting-to-be-called":{"cat":"G","roles":{"A":[],"B":[]},"world":["tournament:today"],"ex":[[["A","They called two names and neither of them was mine, so I'm going back to the bathroom."],["B","If you're gone when they call you they just move on."],["A","Then stand here and yell."],["B","I'll yell. I won't go find you."]],[["B","You want to warm up? Both setups are free until they call the next one."],["A","If I warm up I'll figure out something's wrong with my hands and then I'll think about it the whole match."],["B","So you'd rather find out during."],["A","I'd rather find out during, yes."]],[["A","Do you know how many are left in your half?"],["B","Four. Maybe three, someone left to move their car and hasn't come back."],["A","They'll get dropped."],["B","They'll get dropped and then they'll argue about it, and that takes longer than the car did."]],[["B","Sit down. You've been standing behind that chair for twenty minutes."],["A","I sit down and I get sleepy."],["B","Then lean on something. You're breathing on the back of somebody's neck."],["A","They haven't said anything."]],[["A","Popcorn machine's on again."],["B","It's been on since this morning. Nobody's put corn in it."],["A","So it's just hot."],["B","It's just hot."]],[["B","Who'd you get?"],["A","Don't know yet. Bracket's up on the screen but the names are too small from back here."],["B","Go look."],["A","I'd rather sit here and assume it's someone I can beat."]],[["A","Every time I wait this long I come out swinging and lose the first round for free."],["B","Then plan to lose the first round. You'll be less annoyed about it."],["A","That's not planning, that's just being right ahead of time."]],[["B","You eat anything today?"],["A","Pretzel. Around noon."],["B","Go get something now while there's a gap. It'll be your match right after this one and then you're on the other side of it."],["A","Line's four people deep and one of them's ordering for a birthday party."]],[["A","They keep bumping our pool for the stream."],["B","Because ours is boring and theirs has the two people everyone came to watch."],["A","I came to play, not to be scheduling."],["B","You can be both. It's a long day."]],[["B","Your leg's going."],["A","I know it's going. I'm aware of it."],["B","Just saying, the whole row can feel it through the floor."]],[["A","How long's a set here, first to two?"],["B","Two until top eight, then three."],["A","So if I go out early I'm free by five."],["B","You'd still hang around."]],[["B","Whoever wins that one, you get next, right?"],["A","Yeah. And they're on the round I hate, both of them just holding down back all game."],["B","You can hold back too."],["A","I get bored. That's the whole problem with me."]]]},"wandered-in":{"cat":"H","roles":{"A":[],"B":[]},"world":[],"ex":[[["A","Kid's been standing by the curtain for a while now."],["B","Holding a lot of tickets."],["A","Should someone say something?"],["B","Say what. It's not a private club, it just looks like one."]],[["B","We've got an audience."],["A","I noticed. I dropped that combo twice with them standing there."],["B","So it's their fault."],["A","Partly. Mostly the buttons."]],[["A","They asked me what game it was."],["B","And?"],["A","I told them and they said okay and kept watching. That was the whole conversation."],["B","Better than the guy last week who wanted to know if we were the ones on the screen out front."]],[["B","Put a controller in front of them."],["A","Right now? We're mid-set."],["B","After. Just don't run your oki on them, they'll never come back."],["A","I'll block and let them hit me a few times."]],[["A","Someone came in and sat down in the second row."],["B","That's fine."],["A","They've got a full basket of nachos."],["B","That's less fine but still not my problem."]],[["A","Little one just asked if you were winning."],["B","What'd you say."],["A","I said it's a set, ask again in a couple games."],["B","You could have just said yes. I was winning."]],[["B","They flinched when the projector volume spiked."],["A","Everyone does the first time. It's louder in here than out there and out there has skee-ball."],["B","Should turn it down."],["A","Then we can't hear the buttons."]],[["A","Don't look, but there's a whole family behind the chairs."],["B","How many."],["A","Four? One of them's asleep on a stuffed dinosaur."],["B","They're welcome to stay. Bring the dinosaur back next week."]],[["B","You going to keep playing to the crowd or actually block?"],["A","There is one person and they wandered in looking for the bathroom."],["B","You still went for the throw twice in a row."],["A","Because it worked twice in a row."]],[["A","They've been standing there through three of these and haven't said a word."],["B","Then they're doing it right."],["A","I keep waiting for them to ask something."],["B","Give it another set. That's usually when it comes."]],[["B","Kid wants to know what the bar under the health is."],["A","Meter. You spend it on the big stuff."],["B","That's what I said, and then they asked why you never spend yours."],["A","Tell them I'm saving up."]],[["A","Somebody poked their head in and left again pretty fast."],["B","It's dark and there's eleven people not talking. I'd leave too."],["A","We could open the curtain a bit."],["B","Then you get the pinball noise the whole night. I'll take the eleven."]]]},"warned-or-banned":{"cat":"K","roles":{"A":[],"B":[]},"world":[],"ex":[[["A","So it's a two week thing or a never thing?"],["B","Two weeks. Written on the whiteboard out front with everybody's birthday deals."],["A","Out front where the kids are."],["B","I didn't pick the spot."]],[["B","Front desk pulled the plug on the setup mid-set. Just walked in and did it."],["A","Was anybody even yelling by then?"],["B","No, that was the weird part. It had gone quiet like ten minutes before."],["A","So they got the warning for the quiet."]],[["A","You were sitting right there. What actually got said?"],["B","Something about somebody's mother, and then a chair moved."],["A","Moved or got moved."],["B","I'm not answering that in a room with a camera in it."]],[["B","Bracket's short one now."],["A","I'll take the bye and not feel bad about it."],["B","Nobody's asking you to feel bad."]],[["A","Attendant came back here to hand out a warning and could not find the curtain."],["B","They never can. It's two curtains and a doorway, it's not a maze."],["A","Stood by the pinball for a solid minute looking lost."],["B","Should've let them keep looking."]],[["B","You're not going to say anything about it?"],["A","I've got a set to finish."],["B","Everybody else has had a full opinion ready since it happened."],["A","Yeah. I noticed."]],[["A","Half the room's calling it harsh."],["B","Half the room wasn't standing where I was standing."],["A","Where were you standing?"],["B","Close enough that I ducked."]],[["B","Do we actually have rules written down anywhere, or is it just whoever's on register that night?"],["A","There's a sheet taped by the vending machines. Nobody's read it since it got taped up."],["B","Is the ban thing on it?"],["A","It's mostly about food near the cabinets."]],[["A","They messaged me asking if I'd put in a good word."],["B","Are you going to?"],["A","I don't have a good word. I have a neutral word."],["B","Send that one, then. Better than what I'd send."]],[["B","Weird in here tonight."],["A","It's one person missing. Same number of setups."],["B","Still weird. Everybody's being polite to each other."],["A","Give it a week."]],[["A","The warning was for the shouting or for kicking the stool?"],["B","The stool. Shouting happens all night in here and nobody's ever said a thing."],["A","So the furniture has more protection than we do."],["B","The furniture's bolted down. That's the whole reason it's fine."]]]},"welcomed-badly":{"cat":"D","roles":{"A":["newcomer"],"B":["veteran","rel:stranger"]},"world":[],"ex":[[["A","Do I put my name on something, or do I just wait until somebody points at me?"],["B","Sheet on the chair by the vending machine. Write small, people run out of room at the bottom."],["A","Should I put who I play too?"],["B","You can. Nobody reads that part."]],[["B","You came through the wrong curtain if you wanted skee-ball."],["A","No, this is what I came for. I've only played at home, though."],["B","Then sit. Somebody loses eventually and you're in."]],[["A","Is there any way to tell how long the wait is?"],["B","Count the chairs with jackets on them."],["A","That's four."],["B","Then it's about four."]],[["A","Are these on tokens, or does it just run?"],["B","Free play back here. Tokens are for the floor out front."],["A","I bought fifteen dollars of tokens."],["B","Skee-ball's still standing."]],[["A","I don't want to cut into somebody's set."],["B","You can't. It's a queue, you go where the queue puts you."],["A","Who do I tell that I want in?"],["B","You just did."]],[["B","If they give you a choice of side, take the second one. Stick's better."],["A","Is picking a side allowed?"],["B","There's no rule either way. People sit where they sit."]],[["A","That low caught me three times in a row and I never blocked it once."],["B","You blocked it the last time."],["A","Did I?"],["B","You blocked it and then walked forward into a throw. Different problem."]],[["B","You don't have to stand. There's more chairs than people."],["A","I'm alright standing."],["B","Long night, if nobody takes whoever's on the left setup off it."]],[["A","Everybody in here seems to already know each other."],["B","Mm."],["A","How long does that take?"],["B","Some of them still don't. They just sit near each other."]],[["B","You're up after this."],["A","Do I say something, or announce myself, or—"],["B","Sit in the chair when they get out of it."]],[["A","Sorry about that. You probably wanted a real set."],["B","That was a real set."],["A","I won one round."],["B","You won one round."]],[["A","Anything I should know before I go up there?"],["B","Blocking. That's most of it."],["A","That's all you've got for me?"],["B","You asked before you played. Ask again after."]]]},"welcomed-well":{"cat":"D","roles":{"A":["newcomer"],"B":["veteran","humor:earnest"]},"world":[],"ex":[[["A","Is there a sign-up or do I just kind of stand here?"],["B","Standing there works. Put your name on the whiteboard by the curtain if you want to be sure someone reads it."],["A","There's like nine names on it already."],["B","Six of those are the same person's handwriting. You'll get on sooner than it looks."]],[["B","You're on the stick or the pad?"],["A","Pad. Is that going to be a problem?"],["B","Not with me. There's a spare cable in the vending machine gap if yours is short, everyone forgets it's there."]],[["A","I've only played this online. Never in a room with the person."],["B","It's different. You'll hear when you get hit, which throws people off more than they expect."],["A","Great."],["B","You get used to it in about a set. Sit down."]],[["B","Nobody's going to explain the rules to you unless you ask, so ask. It's not rudeness, it's that we forget we know things."],["A","Okay. What's first-to-two versus first-to-three about?"],["B","Casuals are first-to-two so the line keeps moving. Tournament nights we go to three."],["A","And which is tonight?"],["B","Whatever the line feels like. Tonight it's short, so play as long as you want."]],[["A","Sorry, I dropped that whole thing at the end."],["B","Don't apologize for a drop. Nobody in here has a clean confirm rate, they just don't say it out loud."],["A","That's a little comforting."],["B","Run it again. Same character, don't switch off just because one game went bad."]],[["B","First time?"],["A","That obvious?"],["B","You held the curtain open for the person behind you. Regulars let it fall on each other."]],[["B","Grab a chair before the projector side fills up, you can see the screen better from there."],["A","I was going to head out, actually. Just came to look."],["B","Look from the chair. Costs nothing and you'll pick up more than you think."],["A","Fine. One set."]],[["A","How do I know when it's my turn?"],["B","Loser gets up, winner stays. Somebody will say your name."],["A","I didn't give anyone my name."],["B","Give it to me and I'll say it."]],[["B","You were blocking low the whole time and I kept hitting you high. You know why I stopped doing that?"],["A","Because I started blocking high?"],["B","Because you started blocking high after the second one. That's faster than most people. Sit back down."]],[["A","Is there a beginner night or something? I don't want to waste anybody's sets."],["B","You're not wasting mine. I've played the same five people for months and I'm bored of knowing what they'll do."],["A","So I'm useful because I'm unpredictable."],["B","You're useful because you're here. Unpredictable is a bonus."]],[["B","You want the good news or the honest news."],["A","Honest."],["B","You're going to lose for a while. Everyone did, and everyone who quit did it in the first month."],["A","And the good news?"],["B","Popcorn machine's free after nine."]]]},"what-are-the-rules":{"cat":"D","roles":{"A":["newcomer"],"B":["veteran"]},"world":[],"ex":[[["A","Is there a sign-up sheet, or do I just say something?"],["B","Say 'got next' loud enough that somebody hears you. That's the whole system."],["A","What if two people say it at once?"],["B","Then the two of you work it out. It's never once been a problem."]],[["B","You've been standing for ten minutes. You can sit down."],["A","I didn't know if the chair belonged to someone."],["B","Chairs don't belong to anybody. Controllers do."]],[["A","Anything I should definitely not do?"],["B","Don't get up in the middle of a set. Play it out even if it's ugly."],["A","How ugly are we talking?"],["B","Doesn't matter. Play it out."]],[["A","Is it rude to talk while people are playing?"],["B","Talking's fine. Telling somebody what button to press while they're mid-game gets you a look."],["A","Even if I'm right?"],["B","That's the version that gets the look."]],[["B","If you beat somebody and nobody's waiting, offer them another set."],["A","Isn't that rubbing it in?"],["B","Other way round. Winning once and walking off is the rude one."],["A","And if they don't want it?"],["B","They'll say so. Nobody here is shy about that part."]],[["A","Should I have brought my own pad, or can I use these?"],["B","Use these, they live here. Just don't set your drink anywhere it could land on one."],["A","So where does everyone put drinks?"],["B","Floor. Under the chair. It's not a good answer, it's just the answer."]],[["B","One thing, since you're new. Get as loud as you want at the screen. Don't aim it at the person sitting next to you."],["A","What happens if somebody does?"],["B","Nothing happens. They just stop getting sets."]],[["A","If someone's obviously way better than me, can I ask what I'm doing wrong?"],["B","After the set, not between games. And be ready, most people will tell you way more than you asked for."],["A","That's honestly what I want."],["B","Then you'll be fine here."]],[["A","I stacked quarters on the edge of the cabinet like the machines up front. Nobody touched them."],["B","Different room, different rules. Back here you just say you've got next."],["A","So the quarters did nothing."],["B","The quarters get you skee-ball."]],[["A","What if I need to get up between games? Bathroom, whatever."],["B","Say it out loud. Nobody minds waiting a minute, people mind sitting there guessing whether you left."],["A","That's all?"],["B","That's all. Come back, though."]],[["B","The stick on the far setup, the one with tape on the corner. That's somebody's. Don't pick it up."],["A","Should I know whose?"],["B","They usually get here around eight. You'll figure it out."]],[["A","Is switching characters between games frowned on here?"],["B","No. Play whoever you want, change every game if you like."],["A","Someone at the last place I played made a whole speech about it."],["B","Sounds like a lot of effort."]]]},"what-was-that":{"cat":"A","roles":{"A":["lost"],"B":["won"]},"world":[],"ex":[[["A","The low that came out after the sweep. That's not the normal follow-up."],["B","It's a delay. Same button, I just sit on it for a bit."],["A","So I was blocking on the wrong frame the entire time."],["B","You were blocking correctly for a version of it that I stopped doing."]],[["B","You want to know what the wall thing was."],["A","I want to know how it's plus. It should not be plus."],["B","It isn't. You just never pressed."]],[["A","New combo or new route into the same combo?"],["B","Route. Ender's the same, I just get there with meter now instead of the jump."],["A","Feels like more damage."],["B","It's a little more. Mostly it leaves me closer for oki."]],[["B","You kept holding up after the knockdown."],["A","Because you always press there. You didn't press there."],["B","I labbed the whiff punish for the jump instead. Took twenty minutes."],["A","Show me the input, I'm not going to sit here guessing at it."]],[["A","That mix-up in the corner. Is that a real thing or did you make it up on the spot?"],["B","Real. Somebody posted it and I've been trying to get it to work for a while."],["A","It worked."],["B","It worked on you. Different claim."]],[["A","I need the notation for that punish. Written down."],["B","It's not a punish, you were plus. I just pressed anyway and you also pressed."],["A","So it's a coin flip you kept winning."],["B","Four times, yeah."]],[["B","Ask. You've been standing there."],["A","The dash after the throw. You didn't used to do that."],["B","It puts me on the other side about half the time. I can't control which half."]],[["A","That second hit doesn't normally connect from there."],["B","It does if you delay the first one so they fall into it. Bit tight."],["A","You dropped it twice."],["B","And landed it the other times, which is the part that mattered."]],[["A","What was the thing you were doing at range where I couldn't step in."],["B","Just the long poke. I stopped throwing out the other button entirely."],["A","That's it? You subtracted something."],["B","Yeah. Works better than adding, mostly."]],[["B","You can have it, I'm not precious about it."],["A","I'd rather figure it out. Just tell me if it's a true blockstring or not."],["B","Not true. There's a gap in the middle."],["A","Then I'm mad at myself and not at you, which is worse."]],[["A","How long have you been sitting on that anti-air conversion?"],["B","Couple weeks. I wanted it to be clean before I used it on anybody."],["A","And I'm anybody."],["B","You're the person who jumps. It was always going to be you."]]]},"whitewash-unspoken":{"cat":"A","roles":{"A":["lost"],"B":["won"]},"world":[],"ex":[[["A","Good games."],["B","Yeah."],["A","I'm gonna get a drink and think about my life."],["B","Get me one."]],[["B","You want to run it back?"],["A","Give me a minute. I want to sit here and not press buttons for a bit."],["B","Chair's not going anywhere."]],[["A","My hands were cold the whole time. Not an excuse, just true."],["B","It is cold in here. They keep it like a meat locker."],["A","Right, so we're agreed it was the temperature."],["B","Sure."]],[["B","You were doing the right things. Some of it."],["A","Which part."],["B","The walking back. That part was fine."],["A","Great. I'll build from there."]],[["A","What did I do wrong at the start of every round?"],["B","Same button, every time. I didn't even have to look."],["A","Okay. Well. Now I know that about myself."]],[["A","I dropped the one conversion I actually had."],["B","You had it. It was there."],["A","And then it wasn't."],["B","And then it wasn't."]],[["B","You switching for the next one?"],["A","Thinking about it. Not because of anything that just happened."],["B","Obviously."]],[["A","How long was that, five minutes?"],["B","Something like that. I wasn't watching the clock."],["A","Feels bad to hold the setup for five minutes."],["B","Nobody's waiting. Sit down."]],[["A","Anything I should be doing differently on my way up off the floor?"],["B","Vary it. You picked the same option every knockdown, so I just sat on it."],["A","That's the whole answer?"],["B","That's the whole answer."]],[["B","You've gone very quiet."],["A","I'm fine. I'm just doing math on how bad that was."],["B","Don't. Popcorn machine's on, go get some."],["A","In a minute."]]]},"who-is-it-for":{"cat":"E","roles":{"A":["settled"],"B":["settled"]},"world":[],"ex":[[["A","Every time somebody picks up my character they play it like a rushdown character and then quit after a week."],["B","Because that's what the tools say. Fast walk, plus jabs. What else are people supposed to read from that."],["A","The walk speed is for backing up."],["B","Nobody in the history of this game has bought a fast walk to go backwards."]],[["B","Yours is a defensive character. You just refuse to play it that way."],["A","There's no reward for blocking with it. I sit there, I win the block, I get one jab."],["B","That's the character. One jab at a time until they get bored."],["A","Then I'd rather be wrong and have fun."]],[["A","Who's your character actually supposed to beat?"],["B","Anyone who wants to be in front of me. Which is most of the cast, so, fine."],["A","I don't want to be in front of you and I still lose."],["B","Then maybe it's supposed to beat you specifically."]],[["B","You're playing that like it's a zoner and it's not a zoner."],["A","It has two projectiles."],["B","Both of them are combo tools. They're not there for you to sit at the far end of the screen."],["A","They work from the far end of the screen."]],[["B","That character's designed for someone patient and you are the least patient person who comes in here."],["A","I've won sets off you with it."],["B","By doing things the character isn't good at, which is somehow worse."]],[["A","The devs clearly built yours for beginners. Big buttons, easy conversions, one super you can't drop."],["B","And yet the beginners don't play it. They play the flashy one and get destroyed and go play skee-ball."],["A","That's a marketing problem, not a design one."],["B","Either way I'm not giving it back."]],[["B","Explain the throw range to me. On your character. Explain why it has that."],["A","Because the neutral is bad. It's compensation."],["B","So it's a grappler."],["A","It's a character with one good tool and I use the tool."]],[["A","Yours is for people who like footsies. Actual footsies, long pokes, all of that."],["B","Correct."],["A","So why are you in my face the whole set."],["B","Because you don't press anything when I'm close and I noticed."]],[["B","Nobody's figured out what yours wants yet. Including you."],["A","I've got a plan."],["B","You've got three plans and you switch when the first one doesn't work in eight seconds."],["A","That is a plan."]],[["A","There's an anti-air on that thing that nobody uses. Why is it in the game."],["B","It's for the matchups where people jump. You just don't play against anyone who jumps."],["A","I jump."],["B","You jump once a set and it's out of frustration. That's not a matchup."]],[["B","Your character got built for tournaments and you're using it to bully people in casuals."],["A","What's the difference. Same buttons."],["B","The difference is people came in here to have a nice time."],["A","I'm having a nice time."]]]},"winner-apologetic":{"cat":"A","roles":{"A":["lost"],"B":["won","humor:earnest"]},"world":[],"ex":[[["B","That last one wasn't really me winning. You dropped the confirm twice and I just stood there."],["A","I know what I dropped. I was there."],["B","I meant it more like, on a normal day you take that."],["A","Put your name back up and beat me on a normal day then."]],[["A","Say good set and let go of it."],["B","Good set. I still think the throw at the end was ugly."],["A","It was ugly. It also worked. Both of those are allowed."]],[["B","Feels bad taking it like that, you were clearly figuring the spacing out."],["A","Clearly not fast enough."],["B","No, you were. Another game and I think it flips."],["A","Then run it again instead of telling me about it."]],[["A","You're doing the face."],["B","What face."],["A","The one where you're about to explain why you didn't deserve it. I'd rather you just gloat, genuinely."],["B","I don't know how to do that."]],[["B","Half of that was me guessing right on the wake-up. That's not knowledge, that's luck."],["A","You guessed right four or five times in a row."],["B","Which is lucky."],["A","Or you had a read on me and I'd like to sit with that quietly for a minute."]],[["B","I don't want you thinking that's how it usually goes between us."],["A","It's how it went. That's the only part on the screen."],["B","Fair."],["A","Winner stays. Go sit down before someone thinks you're being nice to me."]],[["B","That whole thing was one button. I hit the same low over and over and you never made me stop."],["A","Yeah. I'll block it next time."],["B","I'm not saying it to be a jerk about it, I just don't feel great about the way it happened."],["A","You won with one button. Feel great. That's the reward."]],[["A","Stop shaking your head. It's not a funeral."],["B","You had it in that one where you switched. I was totally lost."],["A","And then I wasn't lost enough to close it, so."],["B","So. Water?"]],[["B","You want to know what I was doing? Because it's not complicated and I feel weird holding onto it."],["A","No. I want to work it out myself and beat you with it."],["B","That's better anyway."],["A","It is. So stop trying to hand me things."]],[["A","You keep saying it was close."],["B","It was close."],["A","You can say the score out loud. It won't hurt me more than you being gentle about it does."]]]},"wont-discuss":{"cat":"A","roles":{"A":["lost"],"B":["won"]},"world":[],"ex":[[["A","That second one, when I was up and you just stopped moving forward. What was that."],["B","Is the popcorn machine on? I smelled popcorn earlier and now nothing."],["A","You stopped moving forward and I walked into everything."],["B","Someone turned it off. There's a whole bag in there going stale."]],[["B","You want anything? I'm going out to the vending machine."],["A","I want to know what I was doing wrong on the wake-up."],["B","Water or the orange one."],["A","Water. But I'm asking again when you get back."]],[["A","I dropped the confirm twice. Twice, in the same spot."],["B","I saw."],["A","That's it? You saw?"],["B","You'll get it. Can you move your bag, someone's got next."]],[["A","Sit back down, I'm not done thinking about this."],["B","I am, though. Done thinking about it."],["A","One question. The throw at the end."],["B","You were mashing. That's the answer to every question you're about to ask."]],[["B","Did you park out front or on the side? They were towing on the side earlier."],["A","Front. Was my spacing bad in that last one or were you just further out than I thought?"],["B","Go check anyway, they don't care whose it is."]],[["B","How's the new place? You said the ceiling was doing something."],["A","It's fine. What were you doing on my knockdowns, because it wasn't the same thing twice."],["B","It was mostly nothing. Ceiling still leaking?"],["A","Mostly nothing. Great."]],[["A","Was any of that a read or were you guessing."],["B","Both. Neither. I don't know. My back hurts from these chairs."],["A","Pick one."],["B","Guessing. Feel better?"],["A","No."]],[["B","Curtain's open again. Every time someone walks through it stays open and the skee-ball comes right in."],["A","I couldn't get in on you at all. Not once, the whole set."],["B","I'm going to prop something against it."]]]}}
